"use strict";(self.webpackChunkkgenots=self.webpackChunkkgenots||[]).push([[8130],{7735:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"privileged-non-root-capabilities","metadata":{"permalink":"/blog/privileged-non-root-capabilities","source":"@site/blog/2026-09-04-privileged-non-root-capabilities/index.md","title":"privileged: true\uc778\ub370 permission denied\uac00 \ub0ac\uc2b5\ub2c8\ub2e4","description":"\ucee8\ud14c\uc774\ub108\uac00 \ube44 root \uc0ac\uc6a9\uc790\ub85c \uc2e4\ud589\ub418\uba74 privileged: true\ub97c \uc9c0\uc815\ud574\ub3c4 capability\uac00 \uc804\ub2ec\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ucee4\ub110\uc774 UID\ub97c \uc804\ud658\ud558\uba74\uc11c permitted \uc9d1\ud569\uacfc effective \uc9d1\ud569\uc744 \ube44\uc6b0\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.","date":"2026-09-04T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Kubernetes","permalink":"/blog/tags/kubernetes"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Linux","permalink":"/blog/tags/linux"}],"readingTime":1.87,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"privileged: true\uc778\ub370 permission denied\uac00 \ub0ac\uc2b5\ub2c8\ub2e4","slug":"privileged-non-root-capabilities","authors":["kgenots"],"tags":["Reference","Kubernetes","Ops","Linux"],"image":"/assets/blog/cover-privileged-non-root-capabilities.webp","hide_table_of_contents":false},"unlisted":false,"nextItem":{"title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","permalink":"/blog/fast-day-of-week"}},"content":"\ucee8\ud14c\uc774\ub108\uac00 \ube44 root \uc0ac\uc6a9\uc790\ub85c \uc2e4\ud589\ub418\uba74 `privileged: true`\ub97c \uc9c0\uc815\ud574\ub3c4 capability\uac00 \uc804\ub2ec\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ucee4\ub110\uc774 UID\ub97c \uc804\ud658\ud558\uba74\uc11c permitted \uc9d1\ud569\uacfc effective \uc9d1\ud569\uc744 \ube44\uc6b0\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ubc31\uc5c5\uc774 \uc870\uc6a9\ud788 \uba48\ucdc4\uc2b5\ub2c8\ub2e4\\n\\nvelero\ub85c PVC\ub97c \ubc31\uc5c5\ud558\ub294\ub370 \uc5b4\ub290 \ub0a0\ubd80\ud130 \ud30c\uc77c\uc2dc\uc2a4\ud15c \ubc31\uc5c5\ub9cc \ub204\ub77d\ub418\uae30 \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4. velero server \ud30c\ub4dc\ub294 \uacc4\uc18d Running\uc774\uc5c8\uace0 \ubc31\uc5c5 \uc624\ube0c\uc81d\ud2b8\ub3c4 \ub9cc\ub4e4\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \uc0c1\ud0dc\ub9cc `PartiallyFailed`\uc600\uc2b5\ub2c8\ub2e4.\\n\\n\ud30c\uc77c\uc2dc\uc2a4\ud15c \ubc31\uc5c5\uc744 \ub2f4\ub2f9\ud558\ub294 \ucabd\uc740 `node-agent` DaemonSet\uc785\ub2c8\ub2e4. \ub85c\uadf8\uc5d0\ub294 \ud55c \uc904\uc774 \ubc18\ubcf5\ub418\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n```\\nopen /host_pods/: permission denied\\n```\\n\\n\ub9e4\ub2c8\ud398\uc2a4\ud2b8\uc5d0\ub294 `privileged: true`\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \uc694\uccad\ud55c capability\uc640 \uc2e4\uc81c capability\uac00 \ub2e4\ub985\ub2c8\ub2e4\\n\\n`privileged: true`\ub97c \uc9c0\uc815\ud588\ub294\ub370 \uad8c\ud55c\uc774 \uc5c6\ub2e4\uba74 \uc694\uccad\uac12\uacfc \uacb0\uacfc\uac12\uc744 \ub530\ub85c \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4. \ucee8\ud14c\uc774\ub108\uac00 \uc2e4\uc81c\ub85c \uc5b4\ub5a4 \uc0ac\uc6a9\uc790\uc640 capability\ub85c \uc2e4\ud589 \uc911\uc778\uc9c0\ub294 `crictl`\ub85c \ubd05\ub2c8\ub2e4.\\n\\n```bash\\ncrictl inspect <container-id> \\\\\\n  | jq \'.info.runtimeSpec.process | {user, capabilities}\'\\n```\\n\\n\uc5ec\uae30\uc5d0\ub294 \uc694\uccad\ud55c capability 41\uac1c\uac00 \uadf8\ub300\ub85c \ubcf4\uc785\ub2c8\ub2e4. \ud504\ub85c\uc138\uc2a4\uac00 \uc2e4\uc81c\ub85c \ubcf4\uc720\ud55c \uac12\uc740 \ub2e4\ub985\ub2c8\ub2e4. \uac19\uc740 uid\ub85c \ud504\ub85c\ube0c \ud30c\ub4dc\ub97c \ub744\uc6cc `/proc/self/status`\ub97c \uc9c1\uc811 \uc77d\uc73c\uba74 \ucc28\uc774\uac00 \ub4dc\ub7ec\ub0a9\ub2c8\ub2e4.\\n\\n```bash\\nkubectl run capprobe --rm -it --restart=Never --image=nginx:alpine \\\\\\n  --overrides=\'{\\"spec\\":{\\"containers\\":[{\\"name\\":\\"p\\",\\"image\\":\\"nginx:alpine\\",\\n  \\"securityContext\\":{\\"privileged\\":true,\\"runAsUser\\":1002},\\n  \\"command\\":[\\"grep\\",\\"Cap\\",\\"/proc/self/status\\"]}]}}\'\\n```\\n\\n| \uc9d1\ud569 | \uac12 |\\n| --- | --- |\\n| CapBnd (bounding) | 41\uac1c \uc804\ubd80 |\\n| CapPrm (permitted) | 0 |\\n| CapEff (effective) | 0 |\\n\\n<span style={{ backgroundColor: \'#fff5b1\'}}>`privileged: true`\ub294 bounding set\ub9cc \ucc44\uc6c1\ub2c8\ub2e4.</span> \uc2e4\uc81c\ub85c \uad8c\ud55c\uc744 \ud589\uc0ac\ud558\ub294 effective set\uc740 \ube44\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ub9e4\ub2c8\ud398\uc2a4\ud2b8\ub9cc \uc77d\uc5b4\uc11c\ub294 \uc774 \ucc28\uc774\uac00 \ubcf4\uc774\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \ucee4\ub110\uc774 UID\ub97c \uc804\ud658\ud560 \ub54c \uc9d1\ud569\uc744 \ube44\uc6c1\ub2c8\ub2e4\\n\\n`capabilities(7)` \ubb38\uc11c\uc5d0 \uaddc\uce59\uc774 \uc801\ud600 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n> If the effective user ID is changed from nonzero to 0, then the permitted set is copied to the effective set.\\n\\n0\uc5d0\uc11c 0\uc774 \uc544\ub2cc \uac12\uc73c\ub85c \ubc14\ub014 \ub54c\ub294 \ubc18\ub300\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4. \ucee4\ub110\uc774 permitted \uc9d1\ud569\uacfc effective \uc9d1\ud569\uc744 \ube44\uc6c1\ub2c8\ub2e4. `SECBIT_NO_SETUID_FIXUP` \uc2dc\ud050\uc5b4\ube44\ud2b8\ub97c \uc124\uc815\ud558\uba74 \uc774 \ub3d9\uc791\uc744 \ub9c9\uc744 \uc218 \uc788\uc9c0\ub9cc, \ucee8\ud14c\uc774\ub108 \ub7f0\ud0c0\uc784\uc740 \uc774 \ube44\ud2b8\ub97c \uc124\uc815\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. Docker\uc5d0\uc11c\ub3c4 \uac19\uc740 \ub3d9\uc791\uc774 \ubcf4\uace0\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\nbounding set\uc740 \uc55e\uc73c\ub85c \ud68d\ub4dd\ud560 \uc218 \uc788\ub294 capability\uc758 \uc0c1\ud55c\ub9cc \uc815\ud569\ub2c8\ub2e4. \uc774\ubbf8 \ube44\uc6cc\uc9c4 effective set\uc744 \ub418\uc0b4\ub9ac\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \uc774\ubbf8\uc9c0\uc758 \uae30\ubcf8 \uc0ac\uc6a9\uc790\uac00 root\uac00 \uc544\ub2c8\uc5c8\uc2b5\ub2c8\ub2e4\\n\\n`velero/velero:v1.15.2`\uc758 \uae30\ubcf8 \uc0ac\uc6a9\uc790\ub97c \ud655\uc778\ud558\uba74 `cnb:cnb`\uac00 \ub098\uc635\ub2c8\ub2e4. uid 1002\uc785\ub2c8\ub2e4.\\n\\n```bash\\nnerdctl image inspect velero/velero:v1.15.2 | jq -r \'.[0].Config.User\'\\n# cnb:cnb\\n```\\n\\n\ud638\uc2a4\ud2b8\uc758 `/var/lib/kubelet/pods`\ub294 \uad8c\ud55c\uc774 `0750`\uc774\uace0 \uc18c\uc720\uc790\uac00 `root:root`\uc785\ub2c8\ub2e4. uid 1002\ub85c \uc2e4\ud589\ub418\ub294 \ud504\ub85c\uc138\uc2a4\uac00 `CAP_DAC_OVERRIDE` \uc5c6\uc774 \uc774 \ub514\ub809\ud130\ub9ac\ub97c \uc5f4\ub824\uace0 \ud558\uba74 \uac70\ubd80\ub2f9\ud569\ub2c8\ub2e4.\\n\\n## \ud30c\ub4dc \ub808\ubca8 runAsUser\ub97c 0\uc73c\ub85c \ub461\ub2c8\ub2e4\\n\\n\ucee8\ud14c\uc774\ub108 \ub808\ubca8 `privileged`\uac00 \uc544\ub2c8\ub77c \ud30c\ub4dc \ub808\ubca8 `runAsUser`\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n```yaml\\nspec:\\n  securityContext:\\n    runAsUser: 0\\n  containers:\\n    - name: node-agent\\n      securityContext:\\n        privileged: false\\n```\\n\\nupstream\uc758 `velero install --use-node-agent`\ub3c4 \uac19\uc740 \uc870\ud569\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. `runAsUser: 0`\uc774 \uc788\uc73c\uba74 containerd \uae30\ubcf8 capability \uc9d1\ud569\uc5d0 `CAP_DAC_OVERRIDE`\uac00 \ud3ec\ud568\ub418\ubbc0\ub85c `privileged`\ub97c \ucf24 \uc774\uc720\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## \uba87 \ub2ec \ub3d9\uc548 \uc815\uc0c1\uc774\ub358 \uc124\uc815\uc774 \ubc30\ud3ec \ud55c \ubc88\uc5d0 \uc2e4\ud328\ud588\uc2b5\ub2c8\ub2e4\\n\\n\uc774 \ub9e4\ub2c8\ud398\uc2a4\ud2b8\ub294 \ucc98\uc74c\ubd80\ud130 \ud2c0\ub824 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370\ub3c4 \uba87 \ub2ec \ub3d9\uc548 \ubc31\uc5c5\uc774 \uc815\uc0c1\uc73c\ub85c \ub3d9\uc791\ud588\uc2b5\ub2c8\ub2e4. \uc774\ubbf8\uc9c0\uc758 \uae30\ubcf8 \uc0ac\uc6a9\uc790\uac00 \uc911\uac04\uc5d0 \ubc14\ub00c\uc5c8\uace0, \ud30c\ub4dc\ub294 \uadf8 \ub4a4\ub85c \uc7ac\uc0dd\uc131\ub418\uc9c0 \uc54a\uc544 \uc608\uc804 \uc774\ubbf8\uc9c0\ub97c \uacc4\uc18d \uc0ac\uc6a9\ud558\uace0 \uc788\uc5c8\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\nCI\uac00 \uc778\ud504\ub77c\ub97c \ubc30\ud3ec\ud558\uba74\uc11c \ud30c\ub4dc\ub97c \uc7ac\uc0dd\uc131\ud55c \uc21c\uac04 \uc0c8 \uc774\ubbf8\uc9c0\ub97c \uac00\uc838\uc654\uace0, \uadf8\ub54c \uc7a5\uc560\uac00 \ub4dc\ub7ec\ub0ac\uc2b5\ub2c8\ub2e4. **\uc774\ubbf8\uc9c0 \ud0dc\uadf8\uac00 \uac19\uc544\ub3c4 \ud30c\ub4dc\uac00 \uc7ac\uc0dd\uc131\ub420 \ub54c \uc774\ubbf8\uc9c0\uac00 \ud568\uaed8 \uad50\uccb4\ub429\ub2c8\ub2e4.**\\n\\n\uac10\uc9c0\uac00 \ub2a6\uc740 \uc774\uc720\ub294 \ub530\ub85c \uc788\uc5c8\uc2b5\ub2c8\ub2e4. velero server \ud30c\ub4dc\ub294 \uacc4\uc18d Running\uc774\ub77c `kubectl get pods`\ub9cc \ud655\uc778\ud574\uc11c\ub294 \uc815\uc0c1\uc73c\ub85c \ubcf4\uc600\uc2b5\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \uba48\ucd98 \ucabd\uc740 DaemonSet\uc774\uc5c8\uace0, \uc99d\uc0c1\uc740 \ubc31\uc5c5 \uc624\ube0c\uc81d\ud2b8\uc758 `PartiallyFailed` \uc0c1\ud0dc\uc5d0\ub9cc \ub0a8\uc558\uc2b5\ub2c8\ub2e4. \ubcf5\uad6c\uae4c\uc9c0 25\uc2dc\uac04\uc774 \uac78\ub838\uc2b5\ub2c8\ub2e4.\\n\\n## \ub85c\uadf8\ub97c \ud655\uc778\ud560 \ub54c \uc2dc\uac04\ub300\ub97c \uc11e\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4\\n\\n`kubectl`\uc774 \ucd9c\ub825\ud558\ub294 \ud0c0\uc784\uc2a4\ud0ec\ud504\uc640 velero \ubc31\uc5c5 \uc774\ub984\uc740 UTC\ub97c \uc501\ub2c8\ub2e4. `journalctl`\uc758 `--since`\uc640 `--until`\uc740 \ub85c\uceec \uc2dc\uac04\uc744 \ubc1b\uc2b5\ub2c8\ub2e4. \ub450 \uac12\uc744 \uc11e\uc73c\uba74 9\uc2dc\uac04 \uc5b4\uae0b\ub09c \uad6c\uac04\uc744 \ud655\uc778\ud558\uac8c \ub429\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\\n\\n- [capabilities(7) - Linux manual page](https://man7.org/linux/man-pages/man7/capabilities.7.html)\\n- [moby#45491 Process capabilities cannot be retained when starting a container as non-root](https://github.com/moby/moby/issues/45491)"},{"id":"fast-day-of-week","metadata":{"permalink":"/blog/fast-day-of-week","source":"@site/blog/2026-08-28-fast-day-of-week/index.md","title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","description":"\ub0a0\uc9dc\uc5d0\uc11c \uc694\uc77c\uc744 \uad6c\ud560 \ub54c \ud754\ud788 \uc4f0\ub294 % 7 \uc5c6\uc774, \uacf1\uc148 \ud55c \ubc88\uacfc \uc2dc\ud504\ud2b8\ub9cc\uc73c\ub85c \uc694\uc77c\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc744 Ben Joffe\uc758 \uae00 Fast day-of-week computation\uc744 \ubc14\ud0d5\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-08-28T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Algorithm","permalink":"/blog/tags/algorithm"}],"readingTime":3.67,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","slug":"fast-day-of-week","authors":["kgenots"],"tags":["Reference","Algorithm"],"image":"/assets/blog/cover-fast-day-of-week.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"privileged: true\uc778\ub370 permission denied\uac00 \ub0ac\uc2b5\ub2c8\ub2e4","permalink":"/blog/privileged-non-root-capabilities"},"nextItem":{"title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","permalink":"/blog/airgap-container-install"}},"content":"\ub0a0\uc9dc\uc5d0\uc11c \uc694\uc77c\uc744 \uad6c\ud560 \ub54c \ud754\ud788 \uc4f0\ub294 `% 7` \uc5c6\uc774, \uacf1\uc148 \ud55c \ubc88\uacfc \uc2dc\ud504\ud2b8\ub9cc\uc73c\ub85c \uc694\uc77c\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc744 Ben Joffe\uc758 \uae00 [Fast day-of-week computation](https://www.benjoffe.com/fast-day-of-week)\uc744 \ubc14\ud0d5\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ub0a0\uc9dc\uc5d0\uc11c \uc694\uc77c\uc744 \uad6c\ud558\ub294 \ucf54\ub4dc\ub294 \ub300\uac1c `% 7`\ub85c \ub05d\ub0a9\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uc694\uc77c \uacc4\uc0b0\uc740 \uacf1\uc148 1\ubc88 + \ub367\uc148 1\ubc88 + \uc2dc\ud504\ud2b8 1\ubc88, \ucd1d 3\uc5f0\uc0b0\uc73c\ub85c\ub3c4 \ub05d\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uae30\uc874\uc5d0 \uac00\uc7a5 \ube60\ub974\ub2e4\uace0 \uc54c\ub824\uc9c4 \ubc29\ubc95(Neri, 2024) \ub300\ube44 4~6\ubc30 \ube60\ub985\ub2c8\ub2e4.\\n\\n```c\\n// rd: 1970-01-01 \uae30\uc900 \uacbd\uacfc \uc77c\uc218 (rata die), \uacb0\uacfc: 0=\uc77c\uc694\uc77c ~ 6=\ud1a0\uc694\uc77c\\nuint32_t weekday(int32_t rd) {\\n    const uint32_t M = 613566757;   // (2^32 / 7) + 1\\n    const uint32_t Z = 0x94920000;  // \uc5d0\ud3ec\ud06c(1970-01-01 = \ubaa9\uc694\uc77c) \uc815\ub82c\uc6a9\\n    return ((uint32_t)rd * M + Z) >> 29;\\n}\\n```\\n\\n\uc774 \uae00\uc758 \uc0c1\uc218\uc640 \ud56d\ub4f1\uc2dd\uc740 \ud30c\uc774\uc36c\uc73c\ub85c \uc804 \uad6c\uac04 \uc7ac\uac80\uc99d\uc744 \ud588\uace0, \ubaa8\ub450 \uc6d0\ubb38 \uc8fc\uc7a5\ub300\ub85c \ub3d9\uc791\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \uc694\uc77c \uacc4\uc0b0\uc740 \uc65c % 7 \uc778\uac00\\n\\n\uc694\uc77c \uacc4\uc0b0\uc758 \ucd9c\ubc1c\uc810\uc740 <b>rata die</b>, \uc989 \uae30\uc900\uc77c\ub85c\ubd80\ud130\uc758 \uacbd\uacfc \uc77c\uc218\uc785\ub2c8\ub2e4. \uc720\ub2c9\uc2a4 \uc5d0\ud3ec\ud06c(1970-01-01)\ub294 \ubaa9\uc694\uc77c\uc774\ubbc0\ub85c, \uc77c\uc694\uc77c\uc744 0\uc73c\ub85c \ub450\uba74 \uc694\uc77c\uc740 \uc774\ub807\uac8c \uad6c\ud569\ub2c8\ub2e4.\\n\\n```c\\nweekday = ((rd % 7) + 7 + 4) % 7   // C/C++: \uc74c\uc218 \ub098\uba38\uc9c0 \ubcf4\uc815 \ub54c\ubb38\uc5d0 \ub450 \ubc88\\nweekday = (rd + 4).rem_euclid(7)   // Rust: \uc591\uc218 \ub098\uba38\uc9c0 \ud55c \ubc88\\n```\\n\\n\uc77d\uae30 \uc27d\uace0 \uc720\uc9c0\ubcf4\uc218\ub3c4 \ud3b8\ud569\ub2c8\ub2e4. \ub2e4\ub9cc <span style={{ backgroundColor: \'#ffdce0\'}}>`% 7` \uc790\uccb4\uac00 CPU \uc785\uc7a5\uc5d0\uc11c \uc2fc \uc5f0\uc0b0\uc774 \uc544\ub2d9\ub2c8\ub2e4.</span>\\n\\n## % 7 \uc740 \uc65c \ub290\ub9b0\uac00\\n\\n\ub098\ub217\uc148\uc740 CPU\uc5d0\uc11c \uac00\uc7a5 \ub290\ub9b0 \uc0b0\uc220 \uc5f0\uc0b0\uc5d0 \uc18d\ud569\ub2c8\ub2e4. \uadf8\ub798\uc11c \ucef4\ud30c\uc77c\ub7ec\ub294 \uc0c1\uc218 \ub098\ub217\uc148\uc744 \\"\uc5ed\uc218 \uacf1\uc148\\"\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4. `x / 7`\uc744 `x * (2^32 / 7) >> 32` \ube44\uc2b7\ud55c \ud615\ud0dc\ub85c \ubc14\uafb8\ub294 \uac83\uc73c\ub85c, Hacker\'s Delight\ub77c\ub294 \ucc45\uc73c\ub85c \uc798 \uc54c\ub824\uc9c4 \uace0\uc804 \uae30\ubc95\uc785\ub2c8\ub2e4.\\n\\n\uadf8\ub7f0\ub370 7\uc740 \uc774 \ubcc0\ud658\uc774 \uae54\ub054\ud558\uac8c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. `2^32 / 7 = 613566756.57...`\ucc98\ub7fc \uc18c\uc218\ubd80\uac00 \ub0a8\uc544\uc11c, \ucef4\ud30c\uc77c\ub7ec\uac00 \ub9cc\ub4e0 \ucf54\ub4dc\uc5d0 \uc624\ucc28 \ubcf4\uc815\uc6a9 \uc5f0\uc0b0\uc774 \uba87 \uac1c \ub354 \ubd99\uc2b5\ub2c8\ub2e4. \ub098\uba38\uc9c0(`% 7`)\uae4c\uc9c0 \uad6c\ud558\ub824\uba74 `x - (x/7)*7`\uc744 \ub610 \ud574\uc57c \ud558\ub2c8 \uc5f0\uc0b0\uc774 \ub354 \ub298\uc5b4\ub0a9\ub2c8\ub2e4.\\n\\n## \ud575\uc2ec \uc544\uc774\ub514\uc5b4: 7\uc77c\uc9dc\ub9ac \uc8fc\ub97c 8\uce78\uc5d0 \uc5b9\uae30\\n\\n7\uc740 \uba54\ub974\uc13c \uc218(2\xb3 - 1)\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub2e4\uc74c \ud56d\ub4f1\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4.\\n\\n```text\\nN % 7 == floor(N \xd7 8 / 7) % 8\\n```\\n\\n`% 8`\uc740 \ud558\uc704 3\ube44\ud2b8\ub9cc \uc77d\uc73c\uba74 \ub418\ub294 \uacf5\uc9dc \uc5f0\uc0b0\uc785\ub2c8\ub2e4. 7\ub85c \ub098\ub208 \ub098\uba38\uc9c0 \ubb38\uc81c\uac00, 8/7\ubc30\ub85c \ub298\ub9b0 \ub2e4\uc74c \ud558\uc704 3\ube44\ud2b8\ub97c \uc77d\ub294 \ubb38\uc81c\ub85c \ubc14\ub01d\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/fast-day-of-week-padding.webp\\"\\n    alt=\\"7\uc77c \uc8fc\uae30\ub97c 8\uce78 \uadf8\ub9ac\ub4dc\uc5d0 \ud328\ub529\ud574\uc11c \ud558\uc704 3\ube44\ud2b8\ub85c \uc694\uc77c\uc744 \uc77d\ub294 \uad6c\uc870\\"\\n  />\\n  <figcaption>7\uc77c \uc8fc\uae30\ub97c 8\uce78\uc5d0 \ub298\ub824 \uc5b9\uc73c\uba74, \uce78 \ubc88\ud638(\ud558\uc704 3\ube44\ud2b8)\uac00 \uace7 \uc694\uc77c\uc774 \ub429\ub2c8\ub2e4.</figcaption>\\n</figure>\\n\\n7\uc77c\ub9c8\ub2e4 \ubc18\ubcf5\ub418\ub294 \ub2ec\ub825\uc744, \ud55c \uc8fc\uac00 8\uce78\uc778 \uacf5\ucc45\uc5d0 \uae00\uc790 \ud3ed\uc744 8/7\ubc30\ub85c \ub298\ub824\uc11c \uc62e\uaca8 \uc801\uc2b5\ub2c8\ub2e4. \uc5b4\ub5a4 \ub0a0\uc774 \ubb34\uc2a8 \uc694\uc77c\uc778\uc9c0 \uc54c\uace0 \uc2f6\uc73c\uba74 \ub098\ub217\uc148 \uc5c6\uc774 \\"\uba87 \ubc88\uc9f8 \uce78\uc778\uac00\\"\ub9cc \ubcf4\uba74 \ub429\ub2c8\ub2e4.\\n\\n\uace0\ub300 \ub85c\ub9c8\uc5d0\ub294 \uc2e4\uc81c\ub85c 8\uc77c\ub9c8\ub2e4 \uc7a5\uc774 \uc11c\ub294 \ub208\ub514\ub214(nundinum) \uc8fc\uae30\uac00 \uc788\uc5c8\uace0, \uc6d0\ubb38 \uc800\uc790\ub294 \uc5ec\uae30\uc11c \uc774\ub984\uc744 \ub530 \uc774 \uae30\ubc95\uc744 \\"Nundinal Map\\"\uc774\ub77c \ubd80\ub985\ub2c8\ub2e4.\\n\\n\ub9e8 \uc704\uc758 3\uc5f0\uc0b0 \ucf54\ub4dc\ub294 \uc774 \uadf8\ub9bc \uadf8\ub300\ub85c\uc785\ub2c8\ub2e4.\\n\\n- `rd * M` : M \u2248 2\xb2\u2079 \xd7 8/7 \uc774\ubbc0\ub85c, \\"8/7\ubc30 \ub298\ub9ac\uae30\\"\uc640 \\"\uc0c1\uc704 \ube44\ud2b8\ub85c \ubc00\uc5b4\uc62c\ub9ac\uae30\\"\ub97c \uacf1\uc148 \ud55c \ubc88\uc5d0 \ud569\ub2c8\ub2e4.\\n- `+ Z` : \uacb0\uacfc\ub97c \uc5d0\ud3ec\ud06c \uc694\uc77c(\ubaa9\uc694\uc77c)\uc5d0 \ub9de\uac8c \ud68c\uc804\uc2dc\ud0a4\ub294 \uc624\ud504\uc14b\uc785\ub2c8\ub2e4.\\n- `>> 29` : \uc0c1\uc704 3\ube44\ud2b8\ub9cc \ub0a8\uae41\ub2c8\ub2e4. \uc774\uac8c `% 8`, \uace7 \uc694\uc77c\uc785\ub2c8\ub2e4.\\n\\n## \uc720\ud6a8 \ubc94\uc704: \uc57d \xb124\ub9cc \ub144\\n\\nM\uc774 8/7\uc758 \uadfc\uc0ac\uac12\uc774\ub77c\uc11c \uc785\ub825\uc774 \ucee4\uc9c8\uc218\ub85d \uc624\ucc28\uac00 \uc313\uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c 3\uc5f0\uc0b0 \ubc84\uc804\uc740 <span style={{ backgroundColor: \'#fff5b1\'}}>\xb18,900\ub9cc \uc77c(\uc57d \xb124\ub9cc \ub144) \ubc94\uc704 \uc548\uc5d0\uc11c\ub9cc \uc815\ud655</span>\ud569\ub2c8\ub2e4. \uc9c1\uc811 \uac80\uc99d\ud574 \ubcf4\ub2c8 \uccab \uc624\ub2f5\uc740 +89,522,176\uc77c\uacfc -89,434,797\uc77c\uc5d0\uc11c \ub098\uc654\uc2b5\ub2c8\ub2e4.\\n\\n24\ub9cc \ub144\uc774\uba74 \ubd80\uc871\ud560 \uc77c\uc774 \uc5c6\uc5b4 \ubcf4\uc774\uc9c0\ub9cc, \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 int32 \uc804\uccb4 \ubc94\uc704(\xb158\uc5b5 \ub144 \uc0c1\ub2f9)\ub97c \ubc1b\ub294 \uacbd\uc6b0\uac00 \uc788\uc5b4 \uc6d0\ubb38\uc740 \uc804\uccb4 \ubc94\uc704 \ubcc0\ud615\ub3c4 \ud568\uaed8 \uc81c\uc2dc\ud569\ub2c8\ub2e4.\\n\\n## \uc804\uccb4 \ubc94\uc704\uac00 \ud544\uc694\ud558\uba74: \uc2dc\ud504\ud2b8 \ubcf4\uc815 \ubcc0\ud615\\n\\nint32 \uc804\uccb4 \ubc94\uc704\ub97c \ucee4\ubc84\ud558\ub294 \ubcc0\ud615 \uc911 \uac00\uc7a5 \ub2e8\uc21c\ud55c \ucabd\uc740, \ubc18\uc62c\ub9bc \ub300\uc2e0 \ub0b4\ub9bc \uc0c1\uc218\ub97c \uc4f0\uace0 \ubd80\uc871\ubd84\uc744 \uc2dc\ud504\ud2b8 \ub450 \ubc88\uc73c\ub85c \ucc44\uc6c1\ub2c8\ub2e4.\\n\\n```c\\nuint32_t weekday_full(int32_t rd) {\\n    const uint32_t M = 613566756;   // 2^32 / 7 \ub0b4\ub9bc\\n    const uint32_t Z = 0x95000000;\\n    uint32_t a = (uint32_t)rd * M + Z;\\n    uint32_t b = (rd >> 1) + (rd >> 4);  // 4/7 \u2248 1/2 + 1/16 \uadfc\uc0ac \ubcf4\uc815\\n    return (a + b) >> 29;\\n}\\n```\\n\\n\ub0b4\ub9bc\uc73c\ub85c \uc798\ub824 \ub098\uac04 \uc18c\uc218\ubd80\ub294 \uc815\ud655\ud788 4/7\uc785\ub2c8\ub2e4. `(x >> 1) + (x >> 4)`\ub294 0.5 + 0.0625 = 0.5625, \uc989 4/7(0.5714...)\uc758 \uadfc\uc0ac\uac12\uc774\ub77c \uc774 \ubd80\uc871\ubd84\uc744 \uba54\uc6cc \uc90d\ub2c8\ub2e4. \uc2dc\ud504\ud2b8\ub294 \uacf1\uc148\uc774 \ub3c4\ub294 \ub3d9\uc548 \ubcd1\ub82c\ub85c \uc2e4\ud589\ub418\ubbc0\ub85c \ucd94\uac00 \ube44\uc6a9\uc774 \uac70\uc758 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uc774 \ubcc0\ud615\ub3c4 int32 \uc804\uccb4 \ubc94\uc704\uc5d0\uc11c \ub79c\ub364 50\ub9cc \uac74\uacfc \uacbd\uacc4\uac12\uc73c\ub85c \uac80\uc99d\ud588\uace0 \uc804\ubd80 \uc815\ud655\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\uc774 \ubc16\uc5d0\ub3c4 64\ube44\ud2b8 \uacf1\uc73c\ub85c \uc815\ubc00\ub3c4\ub97c \uc62c\ub9b0 \ubcc0\ud615, \uacf1\uc148 2\uac1c\ub97c \ud30c\uc774\ud504\ub77c\uc778\uc73c\ub85c \uacb9\uce58\ub294 \ubcc0\ud615, x86\uc758 LEA \uba85\ub839\uc5b4 \ud558\ub098\uc5d0 \uacf1\uc148\xb7\ub367\uc148\xb7\uc0c1\uc218\ub97c \uc6b1\uc5ec\ub123\ub294 3\uc5f0\uc0b0 \ubcc0\ud615\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc790\uc138\ud55c \ub0b4\uc6a9\uc740 \uc6d0\ubb38\uc744 \ubcf4\uc2dc\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \uc77c\ubc18\ud654: 2\uc758 \uac70\ub4ed\uc81c\uacf1 \ud328\ub529 (x % 24, x % 60)\\n\\n\uac19\uc740 \ud328\ub529\uc744 \ub2e4\ub978 \ub098\ub217\uc218\uc5d0\ub3c4 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```text\\nx mod D == (x + c \xd7 floor(x / D)) mod (D + c)    (D + c \uac00 2\uc758 \uac70\ub4ed\uc81c\uacf1\uc774 \ub418\ub3c4\ub85d c \uc120\ud0dd)\\n```\\n\\n\ub098\ub217\uc218\ub97c 2\uc758 \uac70\ub4ed\uc81c\uacf1\uae4c\uc9c0 \\"\ud328\ub529\\"\ud558\uba74 \ub098\uba38\uc9c0 \uc5f0\uc0b0\uc774 \ube44\ud2b8 AND\ub85c \ubc14\ub01d\ub2c8\ub2e4. \uc2dc\uac04 \uacc4\uc0b0\uc5d0 \ubc14\ub85c \uc368\uba39\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n| \uacc4\uc0b0 | \ud328\ub529 \uacf5\uc2dd | \ube44\uace0 |\\n| --- | --- | --- |\\n| `x % 24` (\uc2dc) | `(x + (x/24 << 3)) & 31` | 24 + 8 = 32 |\\n| `x % 60` (\ubd84\xb7\ucd08) | `(x + (x/60 << 2)) & 63` | 60 + 4 = 64 |\\n\\n`x / 24`\ub294 \uc5b4\ucc28\ud53c \ub0a0\uc9dc \uacc4\uc0b0\uc5d0\uc11c \ud568\uaed8 \uad6c\ud558\ub294 \uac12\uc774\ub77c, \uadf8 \ubd80\uc0b0\ubb3c\ub85c \ub098\uba38\uc9c0\ub97c \uacf5\uc9dc\uc5d0 \uac00\uae5d\uac8c \uc5bb\uc2b5\ub2c8\ub2e4. \ub450 \uacf5\uc2dd \ubaa8\ub450 0\ubd80\ud130 200\ub9cc\uae4c\uc9c0 \uc804\uc218 \uac80\uc99d\ud588\uc2b5\ub2c8\ub2e4.\\n\\n## \uc5bc\ub9c8\ub098 \ube60\ub978\uac00\\n\\n\uc6d0\ubb38 \ubca4\uce58\ub9c8\ud06c(AMD Ryzen 9, Apple M4 Pro)\uc785\ub2c8\ub2e4. \uae30\uc900\uc740 \uae30\uc874 \ucd5c\uace0 \uae30\ub85d\uc778 Neri(2024) = 1.0, \uc22b\uc790\uac00 \uc791\uc744\uc218\ub85d \ube60\ub985\ub2c8\ub2e4.\\n\\n| \uc54c\uace0\ub9ac\uc998 | \uc0c1\ub300 \ucc98\ub9ac\ub7c9 | \uc720\ud6a8 \ubc94\uc704 |\\n| --- | --- | --- |\\n| \uc21c\uc9c4\ud55c \uc774\uc911 `% 7` | ~2.8 | \uc804\uccb4 |\\n| Hinnant (2014) | ~2.9 | \uac70\uc758 \uc804\uccb4 |\\n| Neri (2024) | 1.0 (\uae30\uc900) | \uc804\uccb4 |\\n| <b>3\uc5f0\uc0b0 \ubc84\uc804</b> | <b>0.17 ~ 0.27</b> | \xb124\ub9cc \ub144 |\\n| \uc2dc\ud504\ud2b8 \ubcf4\uc815 \ubcc0\ud615 | 0.39 ~ 0.55 | \uc804\uccb4 |\\n\\n## \uc8fc\uc758\uc0ac\ud56d\\n\\n- 3\uc5f0\uc0b0 \ubc84\uc804\uc5d0\ub294 \ubc94\uc704 \uc81c\ud55c\uc774 \uc788\uc2b5\ub2c8\ub2e4. \xb124\ub9cc \ub144\uc744 \ub118\ub294 \uc785\ub825\uc774 \ub4e4\uc5b4\uc62c \uc218 \uc788\uc73c\uba74 \uc804\uccb4 \ubc94\uc704 \ubcc0\ud615\uc744 \uc4f0\uac70\ub098 \uc785\ub825\uc744 \uac78\ub7ec\uc57c \ud569\ub2c8\ub2e4. Rust\uc758 Jiff\ucc98\ub7fc \xb11\ub9cc \ub144\ub9cc \uc9c0\uc6d0\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\ub294 \uadf8\ub300\ub85c \uc548\uc804\ud569\ub2c8\ub2e4.\\n- \ubd80\ud638 \uc788\ub294 \uc815\uc218\ub97c unsigned\ub85c \uce90\uc2a4\ud305\ud558\ub294 \ubd80\ubd84\uc740 2\uc758 \ubcf4\uc218 \ub798\ud551\uc744 \uc804\uc81c\ud569\ub2c8\ub2e4. Rust\uc5d0\uc11c\ub294 \uc815\uc758\ub41c \ub3d9\uc791\uc774\uc9c0\ub9cc C/C++\uc5d0\uc11c\ub294 \uce90\uc2a4\ud305 \ubc29\uc2dd\uc744 \uc9c0\ucf1c\uc57c \ud569\ub2c8\ub2e4.\\n- \uc804\uccb4 \ubc94\uc704 \ubcc0\ud615\ub4e4\uc740 \ucef4\ud30c\uc77c\ub7ec\uac00 \ucd5c\uc801 \ucf54\ub4dc\ub85c \uad6c\uc6cc \uc8fc\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \uc788\uc5b4, \uc6d0\ubb38\uc740 x86 \uc5b4\uc148\ube14\ub9ac \uc218\uc900\uc758 \ubc30\uce58\uae4c\uc9c0 \ub2e4\ub8f9\ub2c8\ub2e4. \uc5ec\uae30\uae4c\uc9c0 \uac00\uae30 \uc804\uc5d0, \ub9c8\uc774\ud06c\ub85c \ucd5c\uc801\ud654\uac00 \ud544\uc694\ud55c \uc0c1\ud669\uc778\uc9c0\ubd80\ud130 \ub530\uc838 \ubcf4\ub294 \uac8c \uc21c\uc11c\uaca0\uc9c0\uc694.\\n\\n## Q&A\\n\\n- **\uc694\uc77c \uacc4\uc0b0\uc5d0 % 7 \uc744 \uc548 \uc4f0\uace0 \uacc4\uc0b0\ud558\ub294 \ubc29\ubc95\uc774 \uc788\ub098\uc694?**\\n  - \uc788\uc2b5\ub2c8\ub2e4. 7\uc774 2\xb3 - 1\uc774\ub77c\ub294 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 `N % 7 == floor(N \xd7 8 / 7) % 8`\uc774 \uc131\ub9bd\ud558\uace0, \uc774\ub97c \uacf1\uc148 1\ubc88 + \ub367\uc148 1\ubc88 + \uc2dc\ud504\ud2b8 1\ubc88\uc73c\ub85c \uad6c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc704\uc758 3\uc5f0\uc0b0 \ucf54\ub4dc\uac00 \uadf8 \uad6c\ud604\uc785\ub2c8\ub2e4.\\n- **\uc774 \ucd5c\uc801\ud654\uac00 \uc2e4\uc81c\ub85c \uc758\ubbf8\uac00 \uc788\ub098\uc694?**\\n  - \ub0a0\uc9dc \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \ub300\ub7c9 \ub370\uc774\ud130 \ucc98\ub9ac\ucc98\ub7fc \uc694\uc77c \uacc4\uc0b0\uc774 \ud56b\ud328\uc2a4\uc5d0 \uc788\uc73c\uba74 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ud55c \ubc88 \ud638\ucd9c\ud558\uace0 \ub9c8\ub294 \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ucf54\ub4dc\ub77c\uba74 \uc77d\uae30 \uc26c\uc6b4 `% 7`\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.\\n- **7 \ub9d0\uace0 \ub2e4\ub978 \uc218\uc5d0\ub3c4 \uc4f8 \uc218 \uc788\ub098\uc694?**\\n  - \ub098\ub217\uc218\ub97c 2\uc758 \uac70\ub4ed\uc81c\uacf1\uae4c\uc9c0 \ud328\ub529\ud558\ub294 \uc77c\ubc18\ud615\uc73c\ub85c \ud655\uc7a5\ub429\ub2c8\ub2e4. `x % 24`\ub294 32\ub85c, `x % 60`\uc740 64\ub85c \ud328\ub529\ud574\uc11c \ube44\ud2b8 AND\ub85c \ubc14\uafc0 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\\"\ucef4\ud30c\uc77c\ub7ec\uac00 \uc54c\uc544\uc11c \ucd5c\uc801\ud654\ud574 \uc8fc\uaca0\uc9c0\\" \ud558\ub294 \uc601\uc5ed\uc5d0\ub3c4 \uc0ac\ub78c \uc190\uc73c\ub85c \uc9dc\ub0bc \uc5ec\uc9c0\uac00 \ub0a8\uc544 \uc788\ub2e4\ub294 \uac8c \uc7ac\ubbf8\uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ub098\ub217\uc218\ub97c 8\ub85c \ubc14\uafd4\uce58\uae30\ud55c\ub2e4\ub294 \ubc1c\uc0c1\uc774 \uc624\ub798 \uae30\uc5b5\uc5d0 \ub0a8\uc744 \uac83 \uac19\uc544 \ub808\ud37c\ub7f0\uc2a4\ub85c \ub0a8\uae41\ub2c8\ub2e4.\\n\\n- \uc6d0\ubb38: [Fast day-of-week computation](https://www.benjoffe.com/fast-day-of-week) (Ben Joffe)\\n- \ucf54\ub4dc: [benjoffe/fast-world-calendars](https://github.com/benjoffe/fast-world-calendars) (MIT)"},{"id":"airgap-container-install","metadata":{"permalink":"/blog/airgap-container-install","source":"@site/blog/2026-06-19-airgap-container-install/index.md","title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","description":"\uc778\ud130\ub137\uc774 \ub9c9\ud78c \uc5d0\uc5b4\uac2d(air-gap) \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub97c \ubc18\uc785\ud558\uace0 \uc124\uce58\ud558\ub294 \ubc29\ubc95\uacfc, \\"\ubc1b\uc544\uc62c \uc218 \uc788\ub2e4\\"\ub294 \uac00\uc815 \ub54c\ubb38\uc5d0 \ub370\uc774\ub294 \uc9c0\uc810\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Kubernetes","permalink":"/blog/tags/kubernetes"}],"readingTime":1.98,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","slug":"airgap-container-install","authors":["kgenots"],"tags":["Reference","Ops","Kubernetes"],"image":"/assets/blog/cover-airgap-container-install.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub098\uba38\uc9c0 \uc5f0\uc0b0 \uc5c6\ub294 \ube60\ub978 \uc694\uc77c \uacc4\uc0b0, \uacf1\uc148 \ud55c \ubc88\uc774\uba74 \ub429\ub2c8\ub2e4","permalink":"/blog/fast-day-of-week"},"nextItem":{"title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","permalink":"/blog/duckdb-parquet-on-s3"}},"content":"\uc778\ud130\ub137\uc774 \ub9c9\ud78c \uc5d0\uc5b4\uac2d(air-gap) \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub97c \ubc18\uc785\ud558\uace0 \uc124\uce58\ud558\ub294 \ubc29\ubc95\uacfc, \\"\ubc1b\uc544\uc62c \uc218 \uc788\ub2e4\\"\ub294 \uac00\uc815 \ub54c\ubb38\uc5d0 \ub370\uc774\ub294 \uc9c0\uc810\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ud544\uc694\ud55c \uc774\ubbf8\uc9c0\ub97c \ud558\ub098\ub3c4 \ube60\uc9d0\uc5c6\uc774 \ubbf8\ub9ac \ubb36\uc5b4 \ubc18\uc785\ud558\uace0, \uc124\uce58\ud560 \ub54c\ub294 \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0\uc11c\ub9cc \ubc1b\uac8c \ud569\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ucf54\ub4dc\uc640 \uc2a4\ud06c\ub9bd\ud2b8\uc5d0 \uc228\uc5b4 \uc788\ub294 \\"\ud544\uc694\ud560 \ub54c \uc778\ud130\ub137\uc5d0\uc11c \ubc1b\uc544\uc628\ub2e4\\"\ub294 \uac00\uc815\uc744 \uc804\ubd80 \uac77\uc5b4\ub0c5\ub2c8\ub2e4.\\n\\n## \uc5d0\uc5b4\uac2d(air-gap) \ud658\uacbd\uc774\ub780 \ubb34\uc5c7\uc778\uac00\\n\\n\uc5d0\uc5b4\uac2d\uc740 \ubcf4\uc548\uc744 \uc704\ud574 \uc678\ubd80 \uc778\ud130\ub137\uacfc \ubb3c\ub9ac\uc801\uc73c\ub85c \ubd84\ub9ac\ub41c \ud658\uacbd\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uace0\uac1d\uc0ac \ub370\uc774\ud130\uc13c\ud130\ucc98\ub7fc \ub370\uc774\ud130\uac00 \ubc16\uc73c\ub85c \ub098\uac00\uba74 \uc548 \ub418\ub294 \uacf3\uc5d0\uc11c \uc501\ub2c8\ub2e4.\\n\\n\ub9c8\ud2b8 \uc5c6\ub294 \uc0b0\uc7a5\uc5d0 \uc0b4\ub9bc\uc744 \ucc28\ub9ac\ub294 \uc77c\uacfc \ube44\uc2b7\ud569\ub2c8\ub2e4. \uc778\ud130\ub137\uc774 \ub418\ub294 \uacf3\uc5d0\uc11c\ub294 \uc7ac\ub8cc\uac00 \ub5a8\uc5b4\uc9c0\uba74 \uc0ac \uc624\uba74 \ub418\uc9c0\ub9cc, \uc5d0\uc5b4\uac2d\uc5d0\uc11c\ub294 \ud544\uc694\ud55c \uac83\uc744 \ud558\ub098\ub3c4 \ube60\uc9d0\uc5c6\uc774 \ubbf8\ub9ac \uc2f8 \ub4e4\uace0 \ub4e4\uc5b4\uac00\uc57c \ud569\ub2c8\ub2e4.\\n\\n## \uc5d0\uc5b4\uac2d \uc124\uce58\uac00 \uc5b4\ub824\uc6b4 \uc774\uc720\\n\\n\ud3c9\uc18c\uc758 \uc124\uce58 \uc808\ucc28\uac00 \uc778\ud130\ub137\uc5d0\uc11c \ubb34\uc5b8\uac00\ub97c \ubc1b\uc544\uc628\ub2e4\uace0 \uc804\uc81c\ud558\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ucee8\ud14c\uc774\ub108 \uc774\ubbf8\uc9c0\ub294 \ubcf4\ud1b5 \uc678\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac(Docker Hub \ub4f1)\uc5d0\uc11c \ubc1b\uc544\uc624\ub294\ub370, \uc5d0\uc5b4\uac2d\uc5d0\uc11c\ub294 \uadf8 \uacbd\ub85c\uac00 \ub9c9\ud600 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uac8c\ub2e4\uac00 \ubc1b\uc544\uc57c \ud560 \uac83\uc740 \uc6b0\ub9ac \uc11c\ube44\uc2a4 \uc774\ubbf8\uc9c0\ub9cc\uc774 \uc544\ub2d9\ub2c8\ub2e4. <span style={{ backgroundColor: \'#ffdce0\'}}>\ubca0\uc774\uc2a4 \uc774\ubbf8\uc9c0, \uc0ac\uc774\ub4dc\uce74, \ub370\uc774\ud130\ubca0\uc774\uc2a4, \ubaa8\ub2c8\ud130\ub9c1 \ub3c4\uad6c\uae4c\uc9c0</span> \uc804\ubd80 \ud544\uc694\ud569\ub2c8\ub2e4. \ud558\ub098\ub77c\ub3c4 \ube60\uc9c0\uba74 \uc124\uce58\uac00 \uc911\uac04\uc5d0 \uba48\ucda5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/airgap-container-install-2.webp\\"\\n    alt=\\"\uc571 \uc774\ubbf8\uc9c0\ubfd0 \uc544\ub2c8\ub77c \ubca0\uc774\uc2a4\xb7\uc0ac\uc774\ub4dc\uce74\xb7DB\xb7OS \ud328\ud0a4\uc9c0\xb7\ud5ec\ub984 \ucc28\ud2b8\uae4c\uc9c0 \ubaa8\ub450 \ubc18\uc785\ud574\uc57c \ud55c\ub2e4\\"\\n  />\\n</figure>\\n\\n## \uc774\ubbf8\uc9c0 \uc800\uc7a5\ubd80\ud130 \ubc18\uc785\uae4c\uc9c0 \ub124 \ub2e8\uacc4 (docker save, ctr import)\\n\\n\uc5d0\uc5b4\uac2d \ubc30\ud3ec\ub294 \ud06c\uac8c \ub124 \ub2e8\uacc4\uc785\ub2c8\ub2e4. \u2460 \ud544\uc694\ud55c \uc774\ubbf8\uc9c0\ub97c \ube60\uc9d0\uc5c6\uc774 \ubaa8\uc73c\uace0, \u2461 \ubb36\uc5b4\uc11c \ubc18\uc785\ud558\uace0, \u2462 \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0 \uc62c\ub9ac\uace0, \u2463 \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uac00 \uadf8 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac00\ub9ac\ud0a4\uac8c \ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/airgap-container-install.webp\\"\\n    alt=\\"\uc778\ud130\ub137 \uc788\ub294 \uacf3\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \ubb36\uc5b4 \ubc18\uc785\ud558\uace0 \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub85c \ubc30\ud3ec\ud558\ub294 \uc5d0\uc5b4\uac2d \ud750\ub984\\"\\n  />\\n</figure>\\n\\n### 1. \ud544\uc694\ud55c \uc774\ubbf8\uc9c0 \ubaa9\ub85d \ub9cc\ub4e4\uae30\\n\\n\ub9e4\ub2c8\ud398\uc2a4\ud2b8(\ucfe0\ubc84\ub124\ud2f0\uc2a4 YAML, compose \ud30c\uc77c \ub4f1)\uc5d0\uc11c \uc4f0\ub294 \uc774\ubbf8\uc9c0\ub97c \uc804\ubd80 \ucd94\ucd9c\ud569\ub2c8\ub2e4. \ubca0\uc774\uc2a4\xb7\uc0ac\uc774\ub4dc\uce74\uae4c\uc9c0 \ub204\ub77d \uc5c6\uc774 \ubaa8\uc74d\ub2c8\ub2e4.\\n\\n```bash\\n# k8s \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uc5d0\uc11c image: \uc904\ub9cc \ucd94\ucd9c\\ngrep -rhoE \'image:\\\\s*\\\\S+\' manifests/ | awk \'{print $2}\' | sort -u\\n```\\n\\n### 2. \uc774\ubbf8\uc9c0\ub97c \ubb36\uc5b4\uc11c \ubc18\uc785\\n\\n\uc778\ud130\ub137\uc774 \ub418\ub294 \uacf3\uc5d0\uc11c \uc774\ubbf8\uc9c0\ub97c \ubc1b\uc544 \ud558\ub098\uc758 \ud30c\uc77c\ub85c \ubb36\uc2b5\ub2c8\ub2e4.\\n\\n```bash\\n# \uc5ec\ub7ec \uc774\ubbf8\uc9c0\ub97c \ud55c tar \ub85c \uc800\uc7a5\\ndocker save -o bundle.tar app:1.0 postgres:16 nats:2.10 ...\\n# (\ub610\ub294 \ub808\uc9c0\uc2a4\ud2b8\ub9ac \uac04 \uc9c1\uc811 \ubcf5\uc0ac: skopeo copy / crane)\\n```\\n\\n\uc774 `bundle.tar`\ub97c USB\xb7\uc2b9\uc778\ub41c \ub9e4\uccb4\ub85c \uc5d0\uc5b4\uac2d \uc548\uc73c\ub85c \ubc18\uc785\ud569\ub2c8\ub2e4.\\n\\n### 3. \ub0b4\ubd80 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0 \uc62c\ub9ac\uae30\\n\\n\uc5d0\uc5b4\uac2d \uc548\uc5d0 \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \ub744\uc6b0\uace0, \ubc18\uc785\ud55c \uc774\ubbf8\uc9c0\ub97c \ud480\uc5b4 \uc62c\ub9bd\ub2c8\ub2e4.\\n\\n```bash\\ndocker load -i bundle.tar\\ndocker tag app:1.0 registry.internal:5000/app:1.0\\ndocker push registry.internal:5000/app:1.0\\n```\\n\\n### 4. \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uac00 \ub0b4\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac00\ub9ac\ud0a4\uac8c\\n\\n\uc774\ubbf8\uc9c0 \uc8fc\uc18c\ub97c \uc678\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\uc5d0\uc11c \ub0b4\ubd80 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub85c \ubc14\uafc9\ub2c8\ub2e4. \uc124\uce58\ub294 \uc774\uc81c \uc778\ud130\ub137\uc774 \uc544\ub2c8\ub77c \ub0b4\ubd80\uc5d0\uc11c\ub9cc \uc774\ubbf8\uc9c0\ub97c \ubc1b\uc2b5\ub2c8\ub2e4.\\n\\n```yaml\\n# before: image: docker.io/library/app:1.0\\nimage: registry.internal:5000/app:1.0\\n```\\n\\n## \uc544\ud0a4\ud14d\ucc98 \ubd88\uc77c\uce58\uc640 \uc774\ubbf8\uc9c0 \ub204\ub77d\\n\\n- \uc758\uc874 \uc774\ubbf8\uc9c0 \ub204\ub77d: \uc6b0\ub9ac \uc571\ub9cc \ucc59\uae30\uace0 \ubca0\uc774\uc2a4\xb7\uc0ac\uc774\ub4dc\uce74\xb7DB\ub97c \ube60\ub728\ub9ac\uae30 \uc27d\uc2b5\ub2c8\ub2e4. \ub208\uc73c\ub85c \ud6d1\uc9c0 \ub9d0\uace0 \ub9e4\ub2c8\ud398\uc2a4\ud2b8\uc5d0\uc11c \uae30\uacc4\uc801\uc73c\ub85c \uc804\ubd80 \ubf51\uc544 \ubaa8\uc74d\ub2c8\ub2e4.\\n- \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac pull\uc774 \ub290\ub9bc: \uc791\uc740 \uc774\ubbf8\uc9c0\ub294 \uad1c\ucc2e\uc9c0\ub9cc <span style={{ backgroundColor: \'#ffdce0\'}}>\ud070 \uc774\ubbf8\uc9c0\ub294 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac70\uce58\uba74 \uc624\ub798 \uac78\ub9bd\ub2c8\ub2e4.</span> \uc6a9\ub7c9\uc774 \ud070 \uc774\ubbf8\uc9c0\ub294 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \uac74\ub108\ub6f0\uace0 \ucee8\ud14c\uc774\ub108 \ub7f0\ud0c0\uc784\uc73c\ub85c \uc9c1\uc811 \ubc18\uc785\ud569\ub2c8\ub2e4(`ctr image import` \ub4f1).\\n- \uc124\uce58 \uc2a4\ud06c\ub9bd\ud2b8\uc5d0 \uc228\uc740 \uc778\ud130\ub137 \uac00\uc815: \ud328\ud0a4\uc9c0 \uc124\uce58, \uc678\ubd80 URL \ub2e4\uc6b4\ub85c\ub4dc \uac19\uc740 \ucf54\ub4dc\uac00 \uacf3\uacf3\uc5d0 \uc228\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ub9c9\ud78c \ud658\uacbd\uc5d0\uc11c\ub294 \uc904\uc904\uc774 \uba48\ucd94\ub2c8, \\"\ubc1b\uc544\uc628\ub2e4\\"\ub294 \uac00\uc815\uc744 \ud558\ub098\uc529 \ucc3e\uc544 \uc9c0\uc6c1\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac \uc5c6\uc774 \uadf8\ub0e5 \uc774\ubbf8\uc9c0\ub9cc \ub123\uc73c\uba74 \uc548 \ub418\ub098\uc694?**\\n  - \ub178\ub4dc\ub9c8\ub2e4 `docker load`\ub85c \uc9c1\uc811 \ub123\uc744 \uc218\ub3c4 \uc788\uc9c0\ub9cc, \ub178\ub4dc\uac00 \ub298\uba74 \uad00\ub9ac\uac00 \ud798\ub4ed\ub2c8\ub2e4. \uc0ac\uc124 \ub808\uc9c0\uc2a4\ud2b8\ub9ac\ub97c \ud55c \ubc88 \ub744\uc6cc \ub450\ub294 \ud3b8\uc774 \uae54\ub054\ud569\ub2c8\ub2e4.\\n- **\uc5b4\ub5a4 \uc774\ubbf8\uc9c0\ub97c \ube60\ub728\ub838\ub294\uc9c0 \uc5b4\ub5bb\uac8c \ud655\uc778\ud558\ub098\uc694?**\\n  - \uc124\uce58\ub97c \ud55c \ubc88 \ub3cc\ub824 \ubcf4\uace0, \uc774\ubbf8\uc9c0 pull \uc2e4\ud328 \ub85c\uadf8\ub97c \ubaa8\uc74d\ub2c8\ub2e4. \uadf8 \ubaa9\ub85d\uc744 \ub2e4\uc74c \ubc88\ub4e4\uc5d0 \ucd94\uac00\ud569\ub2c8\ub2e4. \ucc98\uc74c\ubd80\ud130 \uc644\ubcbd\ud788 \ubaa8\uc73c\uae34 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.\\n- **\uc774\ubbf8\uc9c0 \uc678\uc5d0 \ub610 \ucc59\uae38 \uac83\uc774 \uc788\ub098\uc694?**\\n  - \uc788\uc2b5\ub2c8\ub2e4. OS \ud328\ud0a4\uc9c0, \uc5b8\uc5b4 \ub7f0\ud0c0\uc784 \uc758\uc874\uc131, \ud5ec\ub984 \ucc28\ud2b8, \uc124\uce58 \uc2a4\ud06c\ub9bd\ud2b8\uac00 \ubc1b\ub294 \ubaa8\ub4e0 \uc678\ubd80 \ud30c\uc77c\uc774 \ub300\uc0c1\uc785\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- [docker image save](https://docs.docker.com/reference/cli/docker/image/save/) / [docker image load](https://docs.docker.com/reference/cli/docker/image/load/)\\n- [skopeo](https://github.com/containers/skopeo): \ub808\uc9c0\uc2a4\ud2b8\ub9ac \uc0ac\uc774 \uc774\ubbf8\uc9c0 \ubcf5\uc0ac\\n- [crane](https://github.com/google/go-containerregistry/blob/main/cmd/crane/README.md): \ub808\uc9c0\uc2a4\ud2b8\ub9ac \uc870\uc791 CLI\\n- [containerd getting started](https://github.com/containerd/containerd/blob/main/docs/getting-started.md): `ctr image import`"},{"id":"duckdb-parquet-on-s3","metadata":{"permalink":"/blog/duckdb-parquet-on-s3","source":"@site/blog/2026-06-19-duckdb-parquet-on-s3/index.md","title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","description":"\ubd84\uc11d\uc6a9 \ub370\uc774\ud130\ub97c \ubcc4\ub3c4 DB\ub85c \uc62e\uae30\uc9c0 \uc54a\uace0, S3\uc5d0 Parquet\ub85c \uc313\uc544 DuckDB\ub85c \uc9c1\uc811 SQL \uc870\ud68c\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"DB","permalink":"/blog/tags/db"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"}],"readingTime":2.46,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","slug":"duckdb-parquet-on-s3","authors":["kgenots"],"tags":["Reference","DB","Ops"],"image":"/assets/blog/cover-duckdb-parquet-on-s3.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\uc778\ud130\ub137 \uc5c6\ub294 \ud658\uacbd\uc5d0 \ucee8\ud14c\uc774\ub108 \ubc30\ud3ec\ud558\uae30 (\uc5d0\uc5b4\uac2d)","permalink":"/blog/airgap-container-install"},"nextItem":{"title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","permalink":"/blog/monorepo-workspace-tooling"}},"content":"\ubd84\uc11d\uc6a9 \ub370\uc774\ud130\ub97c \ubcc4\ub3c4 DB\ub85c \uc62e\uae30\uc9c0 \uc54a\uace0, S3\uc5d0 Parquet\ub85c \uc313\uc544 DuckDB\ub85c \uc9c1\uc811 SQL \uc870\ud68c\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ubd84\uc11d\uc6a9 \ub370\uc774\ud130\ub294 \uc6b4\uc601 DB\ub85c \uc62e\uae30\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4. S3\uc5d0 Parquet\ub85c \uc313\uc544 \ub450\uace0, DuckDB\ub85c \uadf8 \ud30c\uc77c\uc744 \uc9c1\uc811 SQL \uc870\ud68c\ud569\ub2c8\ub2e4.\\n\\n\ubcc4\ub3c4 \ubd84\uc11d DB\ub098 \ubb34\uac70\uc6b4 ETL \uc5c6\uc774 \uc77d\uae30 \uc804\uc6a9 \ubd84\uc11d\uc774 \ub429\ub2c8\ub2e4.\\n\\n## Parquet\uc640 DuckDB, \ubb34\uc5c7\uc744 \ud558\ub294 \ubb3c\uac74\uc778\uac00\\n\\nParquet\ub294 \uc5f4(\uceec\ub7fc) \ub2e8\uc704\ub85c \uc800\uc7a5\ud558\ub294 \ud30c\uc77c \ud615\uc2dd\uc774\uace0, DuckDB\ub294 \ud30c\uc77c\uc744 \uc9c1\uc811 \uc77d\uc5b4 SQL\uc744 \ub3cc\ub9ac\ub294 \uac00\ubcbc\uc6b4 \ubd84\uc11d\uc6a9 DB\uc785\ub2c8\ub2e4. \ub458\uc744 \ud569\uce58\uba74 S3\uc5d0 \uc62c\ub824 \ub454 Parquet \ud30c\uc77c\uc744 \uc62e\uae30\uc9c0 \uc54a\uace0 \uadf8\ub300\ub85c \uc870\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ud589 \ub2e8\uc704 \uc800\uc7a5(CSV \ub4f1)\uc774 \uc11c\ub958\ub97c \ud1b5\uc9f8\ub85c \ubb36\uc5b4 \ub450\ub294 \ubc29\uc2dd\uc774\ub77c\uba74, Parquet\ub294 \ud56d\ubaa9\ubcc4 \uce78\uc73c\ub85c \ub098\ub220 \uc815\ub9ac\ud574 \ub454 \uc11c\ub958\ud568\uc785\ub2c8\ub2e4. \\"\uc774\ub984 \uce78\ub9cc \ubcf4\uace0 \uc2f6\ub2e4\\"\uba74 \uadf8 \uce78\ub9cc \uaebc\ub0b4\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \uc6b4\uc601 DB\uc5d0 \ubd84\uc11d \ucffc\ub9ac\ub97c \uc9c1\uc811 \ub3cc\ub9ac\uba74\\n\\n\uc6b4\uc601 DB\uc5d0 \ubd84\uc11d \ucffc\ub9ac\ub97c \uc9c1\uc811 \ub3cc\ub9ac\uba74 <span style={{ backgroundColor: \'#ffdce0\'}}>\ubb34\uac70\uc6b4 \uc9d1\uacc4\uac00 \uc11c\ube44\uc2a4 \ud2b8\ub798\ud53d\uacfc \uc790\uc6d0\uc744 \ub2e4\ud23d\ub2c8\ub2e4.</span> \uadf8\ub807\ub2e4\uace0 \ubcf8\uaca9 \ub370\uc774\ud130 \uc6e8\uc5b4\ud558\uc6b0\uc2a4\ub97c \ub450\uae30\uc5d4 \ubb34\uac81\uace0 \ube44\uc309\ub2c8\ub2e4.\\n\\n\uadf8 \uc911\uac04\uc774 S3 Parquet + DuckDB\uc785\ub2c8\ub2e4. \ub370\uc774\ud130\ub294 S3\uc5d0 \uac12\uc2f8\uac8c \uc313\uc544 \ub450\uace0, \ubd84\uc11d\ud560 \ub54c\ub9cc DuckDB\uac00 \ud544\uc694\ud55c \ubd80\ubd84\uc744 \uc77d\uc2b5\ub2c8\ub2e4. \uc6b4\uc601 DB\ub294 \uac74\ub4dc\ub9ac\uc9c0 \uc54a\uace0, \uc0c1\uc2dc \ub5a0 \uc788\ub294 \ubd84\uc11d \uc11c\ubc84\ub3c4 \ub450\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/duckdb-parquet-on-s3-2.webp\\"\\n    alt=\\"\uc6b4\uc601 DB\uc5d0 \ubd84\uc11d \ucffc\ub9ac\ub97c \uc9c1\uc811 \ub3cc\ub9ac\uba74 \ud2b8\ub798\ud53d\uacfc \uc790\uc6d0\uc744 \ub2e4\ud22c\ub294 \uacbd\uc6b0\uc640, S3 Parquet\uc5d0 \uc313\uace0 DuckDB\ub85c \ud544\uc694\ud560 \ub54c\ub9cc \uc77d\ub294 \uad6c\uc870 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n## S3 Parquet \uc9c1\uc811 \uc870\ud68c (httpfs, CREATE SECRET)\\n\\nDuckDB\uc5d0 S3 \uc811\uadfc \ud655\uc7a5(`httpfs`)\uc744 \uc62c\ub9ac\uba74, S3 \uacbd\ub85c\ub97c \ud14c\uc774\ube14\ucc98\ub7fc \ubc14\ub85c \uc870\ud68c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```sql\\nINSTALL httpfs; LOAD httpfs;\\n\\n-- \uc790\uaca9 \uc99d\uba85\uc740 SECRET \uc73c\ub85c \ub4f1\ub85d\ud569\ub2c8\ub2e4\\nCREATE OR REPLACE SECRET s3_analytics (\\n    TYPE s3,\\n    PROVIDER config,\\n    KEY_ID \'...\',\\n    SECRET \'...\',\\n    REGION \'ap-northeast-2\'\\n);\\n\\n-- S3 \uc758 Parquet \ub97c \uc9c1\uc811 \uc870\ud68c\\nSELECT count(*)\\nFROM read_parquet(\'s3://my-bucket/events/2026-06-19/*.parquet\');\\n```\\n\\nEC2\xb7EKS \ucc98\ub7fc \uc778\uc2a4\ud134\uc2a4 \uc5ed\ud560\uc774\ub098 IRSA \ub85c \uad8c\ud55c\uc774 \ubd99\uc5b4 \uc788\ub294 \uacf3\uc5d0\uc11c\ub294 \ud0a4\ub97c \uc801\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n`aws` \ud655\uc7a5\uc744 \uc62c\ub9ac\uace0 `PROVIDER credential_chain` \uc744 \uc4f0\uba74 AWS SDK \uac00 \uc54c\uc544\uc11c \uc790\uaca9\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.\\n\\n```sql\\nINSTALL aws; LOAD aws;\\nCREATE OR REPLACE SECRET s3_analytics (TYPE s3, PROVIDER credential_chain);\\n```\\n\\n`SET s3_region = \'...\'` \ub85c \uc124\uc815\ud558\ub294 \uc61b \ubc29\uc2dd\ub3c4 \uc544\uc9c1 \ub3d9\uc791\ud558\uc9c0\ub9cc, DuckDB \ubb38\uc11c\ub294 \uc774\ucabd\uc744\\n[Legacy Authentication Scheme](https://duckdb.org/docs/stable/core_extensions/httpfs/s3api_legacy_authentication)\\n\uc73c\ub85c \ubd84\ub958\ud558\uace0 secret \uc0ac\uc6a9\uc744 \uad8c\ud569\ub2c8\ub2e4.\\n\\n\uc5ec\ub7ec \ud30c\uc77c\uc740 \uae00\ub86d(`*`)\uc73c\ub85c \ud55c \ubc88\uc5d0 \uc77d\uc2b5\ub2c8\ub2e4. \ubcc4\ub3c4 \uc801\uc7ac(load) \ub2e8\uacc4\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n## Hive \ud30c\ud2f0\uc154\ub2dd\uc73c\ub85c \uc77d\ub294 \uc591 \uc904\uc774\uae30\\n\\n\ub0a0\uc9dc \uac19\uc740 \uae30\uc900\uc73c\ub85c \ud3f4\ub354\ub97c \ub098\ub220 \uc800\uc7a5\ud558\uba74(\ud30c\ud2f0\uc154\ub2dd) \ube68\ub77c\uc9d1\ub2c8\ub2e4. \ucffc\ub9ac \uc870\uac74\uc5d0 \uadf8 \uae30\uc900\uc774 \ub4e4\uc5b4\uac00\uba74, DuckDB\ub294 \ud574\ub2f9 \ud3f4\ub354\ub9cc \uc77d\uace0 \ub098\uba38\uc9c0\ub294 \uac74\ub108\ub701\ub2c8\ub2e4(\ud30c\ud2f0\uc158 \ud504\ub8e8\ub2dd).\\n\\n```sql\\n-- dt=YYYY-MM-DD \ub85c \ud3f4\ub354\uac00 \ub098\ub258\uc5b4 \uc788\uc73c\uba74\\nSELECT user_id, count(*)\\nFROM read_parquet(\'s3://my-bucket/events/*/*.parquet\', hive_partitioning = true)\\nWHERE dt = \'2026-06-19\'        -- \uc774 \ud3f4\ub354\ub9cc \uc77d\uc74c\\nGROUP BY user_id;\\n```\\n\\n\uc5ec\uae30\uc5d0 Parquet\uc758 \uceec\ub7fc \uc800\uc7a5 \ud2b9\uc131\uc774 \ub354\ud574\uc9d1\ub2c8\ub2e4. `SELECT user_id`\ub9cc \ud558\uba74 \uadf8 \uc5f4\ub9cc \uc77d\uace0, \ub098\uba38\uc9c0 \uc5f4\uc740 \ub514\uc2a4\ud06c\uc5d0\uc11c \uc77d\uc9c0\ub3c4 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n\ud30c\ud2f0\uc158\uc73c\ub85c \uc77d\uc744 \ud30c\uc77c \uc218\ub97c \uc904\uc774\uace0, \uceec\ub7fc\uc73c\ub85c \ud30c\uc77c \uc548\uc5d0\uc11c \uc77d\ub294 \uc591\uc744 \uc904\uc785\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/duckdb-parquet-on-s3-3.webp\\"\\n    alt=\\"\ud30c\ud2f0\uc158 \ud504\ub8e8\ub2dd\uc73c\ub85c \ud574\ub2f9 \ub0a0\uc9dc \ud3f4\ub354\ub9cc \uc77d\uace0, \uceec\ub7fc \uc800\uc7a5\uc73c\ub85c \ud544\uc694\ud55c \uc5f4\ub9cc \uc77d\uc5b4 \uc77d\ub294 \uc591\uc744 \uc904\uc774\ub294 \uc6d0\ub9ac\\"\\n  />\\n</figure>\\n\\n## \uc791\uc740 \ud30c\uc77c\uc774 \ub9ce\uc544\uc9c8 \ub54c (ROW_GROUP_SIZE, compaction)\\n\\n\uc774\ubca4\ud2b8\ub97c \uac74\uac74\uc774 \uc791\uc740 \ud30c\uc77c\ub85c \uc313\uc73c\uba74 \ud30c\uc77c \ud558\ub098\ud558\ub098 \uc5ec\ub294 \ube44\uc6a9\uc774 \uc870\ud68c \uc2dc\uac04\uc744 \uc7a1\uc544\uba39\uc2b5\ub2c8\ub2e4. \uc8fc\uae30\uc801\uc73c\ub85c \ubb36\uc5b4 \uc8fc\ub294 \uc791\uc5c5(compaction)\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n\ubb36\ub294 \ub2e8\uc704\ub294 Parquet \uc758 row group \uc785\ub2c8\ub2e4. DuckDB \uc758 `ROW_GROUP_SIZE` \uae30\ubcf8\uac12\uc740 122,880\ud589\uc774\uace0,\\n\ucd5c\uc19f\uac12\uc740 DuckDB \ubca1\ud130 \ud06c\uae30\uc778 2,048\ud589\uc785\ub2c8\ub2e4. \uc555\ucd95\uc740 row group \ub2e8\uc704\ub85c \uac78\ub9ac\uae30 \ub54c\ubb38\uc5d0 \ud06c\uac8c \uc7a1\uc744\uc218\ub85d\\n\uc555\ucd95\ub960\uc774 \uc62c\ub77c\uac11\ub2c8\ub2e4. \ub300\uc2e0 \uc2a4\ub808\ub4dc\ub9c8\ub2e4 \uadf8\ub9cc\ud07c\uc744 \uba54\ubaa8\ub9ac\uc5d0 \ub4e4\uace0 \uc788\ub2e4\uac00 \ub0b4\ubcf4\ub0b4\uace0, row group \uc740 \ud558\ub098\uc758\\n\ud30c\uc77c \uc548\uc5d0\uc11c\ub3c4 \ubcd1\ub82c\ub85c \uc77d\ud788\ubbc0\ub85c \ubb34\uc791\uc815 \ud0a4\uc6b0\uba74 \ubcd1\ub82c\uc131\uc774 \uc904\uc5b4\ub4ed\ub2c8\ub2e4. \uc774 \ud2b8\ub808\uc774\ub4dc\uc624\ud504\uc758 \uc801\uc815\uac12\uc740\\n\ub370\uc774\ud130 \ubaa8\uc591\uc5d0 \ub530\ub77c \ub2e4\ub974\ubbc0\ub85c \uae30\ubcf8\uac12\uc5d0\uc11c \uc2dc\uc791\ud574 \uc7ac \ubcf4\ub294 \ucabd\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.\\n\\n`WHERE` \uc5d0 \ud30c\ud2f0\uc158 \uae30\uc900(dt \ub4f1)\uc774 \uc5c6\uc73c\uba74 \ud504\ub8e8\ub2dd\uc774 \uac78\ub9ac\uc9c0 \uc54a\uace0 \uc804\uccb4\ub97c \uc2a4\uce94\ud569\ub2c8\ub2e4. \ud30c\ud2f0\uc158\uc744 \ub098\ub220\\n\ub450\uace0\ub3c4 \uc870\uac74\uc744 \uc548 \uac78\uba74 \ub098\ub208 \uc758\ubbf8\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n\uadf8\ub9ac\uace0 \uc774 \ubc29\uc2dd\uc740 \uc77d\uae30 \uc804\uc6a9 \ubd84\uc11d\uc5d0 \ub9de\uc2b5\ub2c8\ub2e4. \uc7a6\uc740 \uac31\uc2e0\uacfc \ud2b8\ub79c\uc7ad\uc158\uc774 \ud544\uc694\ud55c \ub370\uc774\ud130\ub294 \uc6b4\uc601 DB \uc5d0 \ub461\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\uc6b4\uc601 DB \ub370\uc774\ud130\ub97c \uc5b4\ub5bb\uac8c S3 Parquet\ub85c \ubcf4\ub0b4\ub098\uc694?**\\n  - \ubcf4\ud1b5 \uc774\ubca4\ud2b8\ub098 \ubcc0\uacbd\ubd84\uc744 \uc8fc\uae30\uc801\uc73c\ub85c Parquet\ub85c \ub0b4\ubcf4\ub0b4(export) S3\uc5d0 \uc801\uc7ac\ud569\ub2c8\ub2e4. \uc2e4\uc2dc\uac04\uc774 \ud544\uc694\ud558\uba74 \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c, \uc544\ub2c8\uba74 \ubc30\uce58\ub85c \ucda9\ubd84\ud569\ub2c8\ub2e4.\\n- **DuckDB\ub97c \uc5b4\ub514\uc11c \uc2e4\ud589\ud558\ub098\uc694?**\\n  - \uc784\ubca0\ub514\ub4dc\ub77c \ubd84\uc11d \ucf54\ub4dc \uc548\uc5d0\uc11c \ubc14\ub85c \ub744\uc6c1\ub2c8\ub2e4. \uc0c1\uc2dc \uc11c\ubc84\uac00 \ud544\uc694 \uc5c6\uace0, \uc870\ud68c\ud560 \ub54c\ub9cc \ud504\ub85c\uc138\uc2a4\uac00 S3\ub97c \uc77d\uc2b5\ub2c8\ub2e4.\\n- **\ub370\uc774\ud130\uac00 \uc544\uc8fc \ucee4\uc9c0\uba74\uc694?**\\n  - \uc5b4\ub514\uae4c\uc9c0 \ubc84\ud2f0\ub294\uc9c0\ub294 \ub370\uc774\ud130 \ubaa8\uc591\uacfc \ucffc\ub9ac \ud328\ud134\uc5d0 \ub2ec\ub824 \uc788\uc5b4\uc11c \uc77c\ubc18\uc801\uc778 \uae30\uc900\uc120\uc744 \ub9d0\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ud30c\ud2f0\uc154\ub2dd\uacfc compaction \uc744 \uba3c\uc800 \uac78\uc5b4 \ubcf4\uace0, \uadf8\ub798\ub3c4 \ucffc\ub9ac \uc2dc\uac04\uc774 \uc548 \ub098\uc624\uac70\ub098 \ub3d9\uc2dc \uc0ac\uc6a9\uc790\uac00 \ub298\uba74 \uadf8\ub54c \ub370\uc774\ud130 \uc6e8\uc5b4\ud558\uc6b0\uc2a4\ub97c \uac80\ud1a0\ud569\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- [DuckDB: S3 API Support](https://duckdb.org/docs/stable/core_extensions/httpfs/s3api): `CREATE SECRET`, `config` / `credential_chain` provider\\n- [DuckDB: Hive Partitioning](https://duckdb.org/docs/stable/data/partitioning/hive_partitioning)\\n- [DuckDB: Reading Parquet Files](https://duckdb.org/docs/stable/data/parquet/overview)\\n- [Apache Parquet](https://parquet.apache.org/docs/file-format/): \uceec\ub7fc\ud615 \uc800\uc7a5 \ud615\uc2dd"},{"id":"monorepo-workspace-tooling","metadata":{"permalink":"/blog/monorepo-workspace-tooling","source":"@site/blog/2026-06-19-monorepo-workspace-tooling/index.md","title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","description":"\ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uacf5\uc720\ud558\uace0, \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uac8c \ud574 \uc8fc\ub294 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\uac00 \ubb34\uc5c7\uc774\uace0 \uc5b4\ub5bb\uac8c \ub098\ub258\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Architecture","permalink":"/blog/tags/architecture"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"}],"readingTime":1.79,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","slug":"monorepo-workspace-tooling","authors":["kgenots"],"tags":["Reference","Architecture","Ops"],"image":"/assets/blog/cover-monorepo-workspace-tooling.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"S3 Parquet\ub97c DuckDB\ub85c \uc870\ud68c\ud558\uae30","permalink":"/blog/duckdb-parquet-on-s3"},"nextItem":{"title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","permalink":"/blog/nats-jetstream-retention"}},"content":"\ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uacf5\uc720\ud558\uace0, \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uac8c \ud574 \uc8fc\ub294 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\uac00 \ubb34\uc5c7\uc774\uace0 \uc5b4\ub5bb\uac8c \ub098\ub258\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ubaa8\ub178\ub808\ud3ec \ub3c4\uad6c\ub294 \ub450 \uce35\uc704\ub85c \ub098\ub269\ub2c8\ub2e4. \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\uc758 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\uac00 \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0\ud558\uace0, \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ube4c\ub4dc(\uc99d\ubd84 \ube4c\ub4dc)\ud558\uace0 \uce90\uc2dc\ub97c \uad00\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\ub458\uc744 \ud55c \ub369\uc5b4\ub9ac\ub85c \ubcf4\uba74, \ube4c\ub4dc\uac00 \ub290\ub9b4 \ub54c \uc5b4\ub290 \ucabd\uc744 \uc190\ubd10\uc57c \ud558\ub294\uc9c0 \ud5f7\uac08\ub9bd\ub2c8\ub2e4.\\n\\n## \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\uac00 \ud558\ub294 \uc77c\\n\\n\uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c\ub294 \ud55c \ub808\ud3ec \uc548\uc758 \uc5ec\ub7ec \ud328\ud0a4\uc9c0\ub97c \ud568\uaed8 \uad00\ub9ac\ud558\uac8c \ud574 \uc8fc\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4. \uacf5\ud1b5 \ucf54\ub4dc\ub97c \uc5ec\ub7ec \uc571\uc774 \ub098\ub220 \uc4f0\uac8c \uc5f0\uacb0\ud558\uace0, \ubb34\uc5c7\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud560\uc9c0 \uc815\ub9ac\ud574 \uc90d\ub2c8\ub2e4.\\n\\n\uc694\ub9ac\uc5d0 \ube44\uc720\ud558\uba74, \uc5ec\ub7ec \uba54\ub274(\uc571)\uac00 \uacf5\uc6a9 \uc7ac\ub8cc \ucc3d\uace0(\uacf5\uc720 \ud328\ud0a4\uc9c0)\ub97c \ud568\uaed8 \uc501\ub2c8\ub2e4. \uc7ac\ub8cc\uac00 \ubc14\ub00c\uba74 \uadf8 \uc7ac\ub8cc\ub97c \uc4f0\ub294 \uba54\ub274\ub9cc \ub2e4\uc2dc \uc870\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\ucc3d\uace0\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uacfc \ub2e4\uc2dc \uc870\ub9ac\ud560 \uba54\ub274\ub97c \uace0\ub974\ub294 \uc77c\uc740 \uc11c\ub85c \ub2e4\ub985\ub2c8\ub2e4.\\n\\n## \ub450 \uce35\uc704\ub85c \ub098\ub220 \ubcf4\uae30\\n\\n\ub3c4\uad6c\ub97c \ub450 \uce35\uc704\ub85c \ub098\ub220 \ubcf4\uba74 \uc5ed\ud560\uc774 \ubd84\uba85\ud574\uc9d1\ub2c8\ub2e4.\\n\\n| \uce35\uc704 | \uc5ed\ud560 | \ub300\ud45c \ub3c4\uad6c |\\n| --- | --- | --- |\\n| \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 | \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0(\uc758\uc874\uc131) | pnpm/yarn workspaces, uv, Cargo, Go workspace |\\n| \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130 | task \uadf8\ub798\ud504 + \uc99d\ubd84 \ube4c\ub4dc\xb7\uce90\uc2dc | Turborepo, Nx |\\n\\n\ub458\uc740 \ud568\uaed8 \uc501\ub2c8\ub2e4. \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\uac00 \\"\ubb34\uc5c7\uc744 \uacf5\uc720\ud558\ub294\uc9c0\\"\ub97c \uc54c\uace0, \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \\"\ubb34\uc5c7\uc744 \ub2e4\uc2dc \ub9cc\ub4e4\uc9c0\\"\ub97c \uc815\ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/monorepo-workspace-tooling-2.webp\\"\\n    alt=\\"\ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\uac00 \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0\ud558\uace0, \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uac00 \uc99d\ubd84 \ube4c\ub4dc\uc640 \uce90\uc2dc\ub97c \ub2f4\ub2f9\ud558\ub294 \ub450 \uce35\uc704 \uad6c\ubd84\\"\\n  />\\n</figure>\\n\\n## \uacf5\uc720 \ud328\ud0a4\uc9c0 \uc5f0\uacb0 (\ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800)\\n\\n\uccab \uce35\uc704\ub294 \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc5f0\uacb0\ud558\ub294 \uc77c\uc785\ub2c8\ub2e4. \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\ub97c \uc120\uc5b8\ud558\uba74, \ud55c \ud328\ud0a4\uc9c0\ub97c \uace0\ucce4\uc744 \ub54c \uadf8\uac83\uc744 \uc4f0\ub294 \uc571\uc774 \uc989\uc2dc \uac19\uc740 \ucf54\ub4dc\ub97c \ubd05\ub2c8\ub2e4.\\n\\n\ubc84\uc804\uc744 \uc62c\ub824 \ubc30\ud3ec\ud558\uace0 \ub2e4\uc2dc \ubc1b\uc544\uc624\ub294 \uc655\ubcf5\uc774 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.\\n\\n```yaml\\n# pnpm-workspace.yaml\\npackages:\\n  - \\"apps/*\\"\\n  - \\"packages/*\\"\\n```\\n\\n```json\\n// apps/web/package.json (\uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uadf8\ub300\ub85c \uc758\uc874)\\n{ \\"dependencies\\": { \\"@acme/ui\\": \\"workspace:*\\" } }\\n```\\n\\n\uc774 \uc5f0\uacb0\uc774 \ubaa8\ub178\ub808\ud3ec\uc758 \uac00\uc7a5 \ud070 \uc774\uc810\uc785\ub2c8\ub2e4. \uacf5\uc720 \ucf54\ub4dc\uc640 \uacc4\uc57d\uc774 \ud55c \ucee4\ubc0b\uc5d0\uc11c \uac19\uc774 \uc6c0\uc9c1\uc785\ub2c8\ub2e4.\\n\\n## \ubc14\ub010 \uac83\ub9cc \ube4c\ub4dc (\uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130)\\n\\n\ub458\uc9f8 \uce35\uc704\ub294 \ubc14\ub010 \uac83\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\ub294 \uc77c\uc785\ub2c8\ub2e4. \ube4c\ub4dc \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\ub294 \ud328\ud0a4\uc9c0 \uc0ac\uc774\uc758 \uc758\uc874 \uadf8\ub798\ud504\ub97c \uc54c\uace0 \uc788\uc5b4\uc11c, \ubc14\ub010 \ud328\ud0a4\uc9c0\uc640 \uadf8 \uc601\ud5a5\uc744 \ubc1b\ub294 \uc571\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0 \ub098\uba38\uc9c0\ub294 \uce90\uc2dc \uacb0\uacfc\ub97c \uc501\ub2c8\ub2e4.\\n\\n```bash\\nturbo run build       # \ubc14\ub010 \uac83 + \uc601\ud5a5\ubc1b\ub294 \uac83\ub9cc \ube4c\ub4dc, \ub098\uba38\uc9c0\ub294 \uce90\uc2dc\\n```\\n\\n\uc785\ub825(\uc18c\uc2a4\xb7\uc758\uc874\xb7\uc124\uc815)\uc774 \uadf8\ub300\ub85c\uba74 \uc774\uc804 \ube4c\ub4dc \uacb0\uacfc\ub97c \uce90\uc2dc\uc5d0\uc11c \uadf8\ub300\ub85c \uac00\uc838\uc635\ub2c8\ub2e4. \uc804\uccb4\ub97c \ub9e4\ubc88 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uc9c0 \uc54a\uc73c\ub2c8, \ub808\ud3ec\uac00 \ucee4\uc838\ub3c4 \ud53c\ub4dc\ubc31\uc774 \ub290\ub824\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/monorepo-workspace-tooling-3.webp\\"\\n    alt=\\"\ubcc0\uacbd\ub41c \uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uadf8\uac83\uc744 \uc758\uc874\ud558\ub294 \uc571\ub9cc \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0, \ubb34\uad00\ud55c \ud328\ud0a4\uc9c0\xb7\uc571\uc740 \uce90\uc2dc \uacb0\uacfc\ub97c \uac00\uc838\uc624\ub294 \uc99d\ubd84 \ube4c\ub4dc\\"\\n  />\\n</figure>\\n\\n## \uc21c\ud658 \uc758\uc874\uacfc \uce90\uc2dc \ud0a4 \ub204\ub77d\\n\\n- \uc21c\ud658 \uc758\uc874: \ud328\ud0a4\uc9c0 A\uac00 B\ub97c, B\uac00 \ub2e4\uc2dc A\ub97c \uc758\uc874\ud558\uba74 \uadf8\ub798\ud504\uac00 \uaf2c\uc5ec \uc99d\ubd84 \ube4c\ub4dc\uac00 \uc5b4\uae0b\ub0a9\ub2c8\ub2e4. \uc758\uc874 \ubc29\ud5a5\uc740 \ud55c\ucabd\uc73c\ub85c \uc720\uc9c0\ud569\ub2c8\ub2e4.\\n- \uce90\uc2dc \ud0a4\ub97c \uc798\ubabb \uc7a1\uc74c: \ube4c\ub4dc\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc785\ub825(\ud658\uacbd \ubcc0\uc218\xb7\uc124\uc815 \ud30c\uc77c \ub4f1)\uc744 \uce90\uc2dc \ud0a4\uc5d0\uc11c \ube60\ub728\ub9ac\uba74, <span style={{ backgroundColor: \'#ffdce0\'}}>\ubc14\ub00c\uc5c8\ub294\ub370\ub3c4 \uc61b \uce90\uc2dc\ub97c \uac00\uc838\uc635\ub2c8\ub2e4.</span> \uc785\ub825\uc744 \ube60\uc9d0\uc5c6\uc774 \ud0a4\uc5d0 \ub123\uc2b5\ub2c8\ub2e4.\\n- \uacb0\uad6d \uc804\ubd80 \ube4c\ub4dc: \uc758\uc874\uc744 \ub108\ubb34 \ub113\uac8c \uac78\uba74 \uc791\uc740 \ubcc0\uacbd\uc5d0\ub3c4 \uc804\ubd80 \ub2e4\uc2dc \ube4c\ub4dc\ub429\ub2c8\ub2e4. \uacf5\uc720 \ud328\ud0a4\uc9c0\ub97c \uc798\uac8c \ub098\ub220 \uc601\ud5a5 \ubc94\uc704\ub97c \uc881\ud799\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **\ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800 \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\ub9cc \uc788\uc73c\uba74 \uc548 \ub418\ub098\uc694?**\\n  - \uacf5\uc720\ub294 \ub429\ub2c8\ub2e4. \ub2e4\ub9cc \\"\ubb34\uc5c7\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud560\uc9c0\\"\ub294 \uc9c1\uc811 \uad00\ub9ac\ud574\uc57c \ud569\ub2c8\ub2e4. \ub808\ud3ec\uac00 \ucee4\uc9c0\uba74 \uc99d\ubd84 \ube4c\ub4dc\xb7\uce90\uc2dc\ub97c \uc8fc\ub294 \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\uc758 \uc774\uc810\uc774 \ucee4\uc9d1\ub2c8\ub2e4.\\n- **Turborepo\uc640 Nx \uc911 \ubb34\uc5c7\uc744 \uace0\ub974\ub098\uc694?**\\n  - \ud575\uc2ec \uae30\ub2a5(task \uadf8\ub798\ud504\xb7\uce90\uc2dc)\uc740 \ube44\uc2b7\ud569\ub2c8\ub2e4. \uc124\uc815\uc774 \uac00\ubccd\uace0 \ub2e8\uc21c\ud558\uba74 Turborepo, \ud50c\ub7ec\uadf8\uc778\uacfc \ucf54\ub4dc \uc0dd\uc131\uae4c\uc9c0 \ud3ed\ub113\uac8c \uc4f0\ub824\uba74 Nx\uac00 \ud754\ud55c \uc120\ud0dd\uc785\ub2c8\ub2e4.\\n- **JS\uac00 \uc544\ub2cc \uc5b8\uc5b4\ub3c4 \ub418\ub098\uc694?**\\n  - \ub429\ub2c8\ub2e4. uv(\ud30c\uc774\uc36c), Cargo(\ub7ec\uc2a4\ud2b8), Go workspace\uac00 \uac19\uc740 \\"\uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4\\" \uac1c\ub150\uc744 \uc81c\uacf5\ud569\ub2c8\ub2e4. \uc624\ucf00\uc2a4\ud2b8\ub808\uc774\ud130\ub3c4 \uc5b8\uc5b4 \ubb34\uad00\ud558\uac8c task\ub97c \ubb36\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- [Turborepo: Caching](https://turborepo.com/docs/crafting-your-repository/caching): \ud0dc\uc2a4\ud06c \uadf8\ub798\ud504\uc640 \uce90\uc2dc \ud0a4\\n- [Nx: Cache Task Results](https://nx.dev/features/cache-task-results)\\n- [pnpm workspaces](https://pnpm.io/workspaces): `workspace:` \ud504\ub85c\ud1a0\ucf5c"},{"id":"nats-jetstream-retention","metadata":{"permalink":"/blog/nats-jetstream-retention","source":"@site/blog/2026-06-19-nats-jetstream-retention/index.md","title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","description":"NATS JetStream \uc2a4\ud2b8\ub9bc\uc774 \uba54\uc2dc\uc9c0\ub97c \uc5b8\uc81c\uae4c\uc9c0 \ubcf4\uad00\ud558\uace0 \uc5b8\uc81c \uc9c0\uc6b0\ub294\uc9c0, \uadf8\ub9ac\uace0 \ubcf4\uad00 \uae30\uac04\uc744 \uc798\ubabb \uc7a1\uc73c\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc0dd\uae30\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Backend","permalink":"/blog/tags/backend"},{"inline":true,"label":"NATS","permalink":"/blog/tags/nats"}],"readingTime":1.73,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","slug":"nats-jetstream-retention","authors":["kgenots"],"tags":["Reference","Backend","NATS"],"image":"/assets/blog/cover-nats-jetstream-retention.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ubaa8\ub178\ub808\ud3ec \uc6cc\ud06c\uc2a4\ud398\uc774\uc2a4 \ub3c4\uad6c \uc774\ud574\ud558\uae30 (\uacf5\uc720 \ud328\ud0a4\uc9c0\uc640 \uc99d\ubd84 \ube4c\ub4dc)","permalink":"/blog/monorepo-workspace-tooling"},"nextItem":{"title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","permalink":"/blog/spa-runtime-config"}},"content":"NATS JetStream \uc2a4\ud2b8\ub9bc\uc774 \uba54\uc2dc\uc9c0\ub97c \uc5b8\uc81c\uae4c\uc9c0 \ubcf4\uad00\ud558\uace0 \uc5b8\uc81c \uc9c0\uc6b0\ub294\uc9c0, \uadf8\ub9ac\uace0 \ubcf4\uad00 \uae30\uac04\uc744 \uc798\ubabb \uc7a1\uc73c\uba74 \uc5b4\ub5a4 \uc77c\uc774 \uc0dd\uae30\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uae30\uac04(`max_age`)\uc740 \uc18c\ube44\uc790\uac00 \uba54\uc2dc\uc9c0\ub97c \uac00\uc838\uac00\ub294 \uc8fc\uae30\ubcf4\ub2e4 \ub109\ub109\ud788 \uae38\uac8c \uc7a1\uc2b5\ub2c8\ub2e4. \uc774 \uac12\uc774 \uc9e7\uc73c\uba74 \uc18c\ube44\uc790\uac00 \uc624\uae30 \uc804\uc5d0 \uba54\uc2dc\uc9c0\uac00 \ub9cc\ub8cc\ub418\uc5b4 \uc0ac\ub77c\uc9d1\ub2c8\ub2e4.\\n\\n\ubd84\uba85\ud788 \ubc1c\ud589\ud588\ub294\ub370 \uc18c\ube44 \ucabd\uc5d0\ub294 \uc544\ubb34\uac83\ub3c4 \ub3c4\ucc29\ud558\uc9c0 \uc54a\ub294 \uc0ac\uace0\uac00 \ub300\uac1c \uc5ec\uae30\uc11c \ub0a9\ub2c8\ub2e4.\\n\\n## JetStream \uc2a4\ud2b8\ub9bc\uacfc \ubcf4\uad00 \uc815\ucc45(retention policy)\\n\\nJetStream \uc2a4\ud2b8\ub9bc\uc740 NATS\uac00 \uba54\uc2dc\uc9c0\ub97c \ub514\uc2a4\ud06c\uc5d0 \uc800\uc7a5\ud574 \ub450\ub294 \uc800\uc7a5\uc18c\uc785\ub2c8\ub2e4. \uc77c\ubc18 NATS\ub294 \uba54\uc2dc\uc9c0\ub97c \ud758\ub824\ubcf4\ub0b4\uace0 \ub05d\uc774\uc9c0\ub9cc, JetStream\uc740 \uc2a4\ud2b8\ub9bc\uc5d0 \uc313\uc544 \ub450\uace0 \uc18c\ube44\uc790\uac00 \ub098\uc911\uc5d0 \uac00\uc838\uac08 \uc218 \uc788\uac8c \ud569\ub2c8\ub2e4.\\n\\n\ubcf4\uad00 \uc815\ucc45(retention policy)\uc740 \uc774\ub807\uac8c \uc313\uc778 \uba54\uc2dc\uc9c0\ub97c \uc5b8\uc81c \uc9c0\uc6b8\uc9c0 \uc815\ud558\ub294 \uaddc\uce59\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uba54\uc2dc\uc9c0\ub97c \uc601\uc6d0\ud788 \ub458 \uc218\ub294 \uc5c6\uc73c\ub2c8 \uc2a4\ud2b8\ub9bc\ub9c8\ub2e4 \uc9c0\uc6b0\ub294 \uae30\uc900\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n## \ubcf4\uad00 \uc815\ucc45 \uc138 \uac00\uc9c0\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/nats-jetstream-retention.webp\\"\\n    alt=\\"NATS JetStream \ubcf4\uad00 \uc815\ucc45 \uc138 \uac00\uc9c0\uc640 \uba54\uc2dc\uc9c0\uac00 \uc9c0\uc6cc\uc9c0\ub294 \uc870\uac74\\"\\n  />\\n</figure>\\n\\nNATS JetStream\uc758 \ubcf4\uad00 \uc815\ucc45\uc740 \uc138 \uac00\uc9c0\uc785\ub2c8\ub2e4.\\n\\n| \uc815\ucc45 | \uba54\uc2dc\uc9c0\ub97c \uc9c0\uc6b0\ub294 \uc2dc\uc810 | \uc4f0\ub294 \uacf3 |\\n| --- | --- | --- |\\n| Limits (\uae30\ubcf8) | \ud55c\ub3c4(\uac1c\uc218\xb7\uc6a9\ub7c9\xb7\uae30\uac04)\uc5d0 \ub3c4\ub2ec\ud558\uba74 \uc624\ub798\ub41c \uac83\ubd80\ud130 | \uc5ec\ub7ec \uc18c\ube44\uc790\uac00 \uac19\uc740 \uba54\uc2dc\uc9c0\ub97c \uac01\uc790 \uc77d\ub294 \uacbd\uc6b0 |\\n| Interest | \uad00\uc2ec \uc788\ub294 \ubaa8\ub4e0 \uc18c\ube44\uc790\uac00 ack\ud558\uba74 | \uad6c\ub3c5\uc790 \ubaa8\ub450 \ucc98\ub9ac\ud55c \ub4a4 \ube44\uc6cc\ub3c4 \ub420 \ub54c |\\n| WorkQueue | \uc18c\ube44\uc790 \ud558\ub098\uac00 ack\ud558\uba74 \uc989\uc2dc | \uc791\uc5c5 \ud050(\ud55c \uba54\uc2dc\uc9c0\ub97c \ud55c \ubc88\ub9cc \ucc98\ub9ac) |\\n\\n\uae30\ubcf8\uac12\uc740 Limits \uc785\ub2c8\ub2e4. \uadf8\ub798\uc11c \ud55c\ub3c4\ub97c \uc5b4\ub5bb\uac8c \uc7a1\ub290\ub0d0\uac00 \ubb38\uc81c\uac00 \ub429\ub2c8\ub2e4.\\n\\n## \uba54\uc2dc\uc9c0\ub294 \uc5b8\uc81c \uc9c0\uc6cc\uc9c0\ub098 (Limits \uc815\ucc45)\\n\\nLimits \uc815\ucc45\uc5d0\uc11c\ub294 \ub2e4\uc74c \uc138 \ud55c\ub3c4 \uc911 \ud558\ub098\ub77c\ub3c4 \ub118\uc73c\uba74 \uc624\ub798\ub41c \uba54\uc2dc\uc9c0\ubd80\ud130 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n- `max_msgs`: \ucd5c\ub300 \uba54\uc2dc\uc9c0 \uac1c\uc218\\n- `max_bytes`: \ucd5c\ub300 \uc6a9\ub7c9\\n- `max_age`: \ucd5c\ub300 \ubcf4\uad00 \uae30\uac04(\uba54\uc2dc\uc9c0\uc758 \uc218\uba85)\\n\\n\uc774 \uc14b \uc911 \uc0ac\uace0\uac00 \uac00\uc7a5 \uc7a6\uc740 \uac12\uc774 `max_age`\uc785\ub2c8\ub2e4. \uac1c\uc218\uc640 \uc6a9\ub7c9\uc740 \uc2a4\ud2b8\ub9bc\uc774 \ucee4\uc9c8 \ub54c \uac78\ub9ac\uc9c0\ub9cc, \uae30\uac04\uc740 \uba54\uc2dc\uc9c0\uac00 \uba87 \uac74\uc774\ub4e0 \uadf8\ub0e5 \uc9c0\ub098\uac11\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/nats-jetstream-retention-2.webp\\"\\n    alt=\\"max_age\uac00 \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uc73c\uba74 \uc18c\ube44 \uc804\uc5d0 \uc0ad\uc81c\ub418\uace0, \uae38\uba74 \uc18c\ube44 \ud6c4 \ub9cc\ub8cc\ub418\uc5b4 \uc548\uc804\ud558\ub2e4\\"\\n  />\\n</figure>\\n\\n## \uc2a4\ud2b8\ub9bc \uc124\uc815 \ubc29\ubc95\\n\\n\uc2a4\ud2b8\ub9bc\uc744 \ub9cc\ub4e4 \ub54c `StreamConfig`\uc5d0 \uc815\ucc45\uacfc \ud55c\ub3c4\ub97c \uc9c0\uc815\ud569\ub2c8\ub2e4.\\n\\n```python\\nfrom nats.js.api import StreamConfig, RetentionPolicy\\n\\nconfig = StreamConfig(\\n    name=\\"MY_STREAM\\",\\n    subjects=[\\"my-service.>\\"],\\n    retention=RetentionPolicy.LIMITS,   # \uae30\ubcf8\\n    max_age=14 * 24 * 60 * 60,          # 14\uc77c (\ucd08 \ub2e8\uc704), \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uae38\uac8c\\n    # max_msgs, max_bytes \ub3c4 \ud568\uaed8 \ub458 \uc218 \uc788\uc74c\\n)\\nawait js.add_stream(config)\\n```\\n\\n`max_age`\ub294 \uc18c\ube44\uc790\uac00 \uba54\uc2dc\uc9c0\ub97c \uac00\uc838\uac00\ub294 \uc8fc\uae30\ubcf4\ub2e4 \ub109\ub109\ud788 \uc7a1\uc2b5\ub2c8\ub2e4. \ud558\ub8e8 \ud55c \ubc88 \ubaa8\uc544 \uac00\ub294 \uc18c\ube44\uc790\uac00 \uc788\ub2e4\uba74, \ud558\ub8e8\ub85c \uc7a1\uc9c0 \ub9d0\uace0 \uba70\uce60 \uc774\uc0c1 \ub450\ub294 \uc2dd\uc785\ub2c8\ub2e4.\\n\\n## max_age \ub97c \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uac8c \uc7a1\uc73c\uba74\\n\\n- `max_age`\ub97c \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 \uc9e7\uac8c \ub450\uae30: <span style={{ backgroundColor: \'#ffdce0\'}}>\uc18c\ube44 \uc804\uc5d0 \uba54\uc2dc\uc9c0\uac00 \uc0ad\uc81c\ub429\ub2c8\ub2e4.</span> \ubc1c\ud589\ub3c4 \uc0ad\uc81c\ub3c4 \uc815\uc0c1 \ub3d9\uc791\uc774\ub77c \uc624\ub958 \ub85c\uadf8\uac00 \ub0a8\uc9c0 \uc54a\uace0, \uadf8\ub798\uc11c \ucc3e\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.\\n- CLI\ub85c \uc784\uc2dc \ubcc0\uacbd: `nats stream edit`\ub85c \ubc14\uafd4\ub3c4, \uc11c\ube44\uc2a4\uac00 \ucf54\ub4dc\uc758 `StreamConfig`\ub85c \uc2a4\ud2b8\ub9bc\uc744 \ub2e4\uc2dc \uac31\uc2e0\ud558\uba74 \ucf54\ub4dc\uac12\uc73c\ub85c \ub418\ub3cc\uc544\uac11\ub2c8\ub2e4. \uc601\uad6c\ud788 \ubc14\uafb8\ub824\uba74 \ucf54\ub4dc\ub97c \uace0\uce69\ub2c8\ub2e4.\\n- \uc2a4\ud2b8\ub9bc\ub9c8\ub2e4 \uc81c\uac01\uac01\uc778 \ubcf4\uad00 \uae30\uac04: \ud300\uc5d0\uc11c 1d/7d/30d\ub97c \uc784\uc758\ub85c \uc11e\uc73c\uba74 \uc2e4\uc218\uac00 \ub0a9\ub2c8\ub2e4. \uacf5\ud1b5 \uc0c1\uc218 \ud558\ub098\ub85c \uace0\uc815\ud558\ub294 \ud3b8\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **max_age\uc640 \uc18c\ube44\uc790(consumer)\uc758 ack\ub294 \ubb34\uc2a8 \uad00\uacc4\uc778\uac00\uc694?**\\n  - Limits \uc815\ucc45\uc5d0\uc11c\ub294 \ubb34\uad00\ud569\ub2c8\ub2e4. \uc18c\ube44\uc790\uac00 ack\ud558\uc9c0 \uc54a\uc544\ub3c4 `max_age`\uac00 \uc9c0\ub098\uba74 \uc9c0\uc6cc\uc9d1\ub2c8\ub2e4. ack \uae30\ubc18\uc73c\ub85c \uc9c0\uc6b0\ub824\uba74 Interest\ub098 WorkQueue \uc815\ucc45\uc744 \uc501\ub2c8\ub2e4.\\n- **\uba54\uc2dc\uc9c0\ub97c \uc783\uc9c0 \uc54a\uc73c\ub824\uba74 \uc5b4\ub5bb\uac8c \ud558\ub098\uc694?**\\n  - \uc18c\ube44 \uc8fc\uae30\ubcf4\ub2e4 `max_age`\ub97c \uae38\uac8c \ub450\uace0, \ucc98\ub9ac \uc2e4\ud328\ubd84\uc740 \ubcc4\ub3c4 DLQ(\ub370\ub4dc\ub808\ud130) \uc2a4\ud2b8\ub9bc\uc73c\ub85c \ubcf4\ub0c5\ub2c8\ub2e4. DLQ\ub294 \ubcf4\ud1b5 \ubcf4\uad00 \ud55c\ub3c4\ub97c \ub450\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- **\ud55c\ub3c4\ub97c \uc5ec\ub7ec \uac1c \ub3d9\uc2dc\uc5d0 \uac78 \uc218 \uc788\ub098\uc694?**\\n  - \ub124. `max_msgs`, `max_bytes`, `max_age`\ub97c \ud568\uaed8 \ub450\uba74 \uac00\uc7a5 \uba3c\uc800 \ub3c4\ub2ec\ud55c \ud55c\ub3c4\uac00 \uc801\uc6a9\ub429\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- [NATS: JetStream Streams](https://docs.nats.io/nats-concepts/jetstream/streams): `RetentionPolicy`, `max_age`, `max_bytes`, `max_msgs`\\n- [NATS CLI](https://docs.nats.io/using-nats/nats-tools/nats_cli): `nats stream add`"},{"id":"spa-runtime-config","metadata":{"permalink":"/blog/spa-runtime-config","source":"@site/blog/2026-06-19-spa-runtime-config/index.md","title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","description":"API \uc8fc\uc18c\ucc98\ub7fc \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc744, \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \uc54a\uace0 \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\uac8c \ub9cc\ub4e4\uc5b4 \ud55c \ubc88 \ube4c\ub4dc\ub85c \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ubc30\ud3ec\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.","date":"2026-06-19T00:00:00.000Z","tags":[{"inline":true,"label":"Reference","permalink":"/blog/tags/reference"},{"inline":true,"label":"Frontend","permalink":"/blog/tags/frontend"},{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"}],"readingTime":1.93,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","slug":"spa-runtime-config","authors":["kgenots"],"tags":["Reference","Frontend","Ops"],"image":"/assets/blog/cover-spa-runtime-config.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"NATS JetStream \uc2a4\ud2b8\ub9bc \ubcf4\uad00 \uc815\ucc45 \uc774\ud574\ud558\uae30","permalink":"/blog/nats-jetstream-retention"},"nextItem":{"title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","permalink":"/blog/why-learn-python-now"}},"content":"API \uc8fc\uc18c\ucc98\ub7fc \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc744, \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \uc54a\uace0 \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\uac8c \ub9cc\ub4e4\uc5b4 \ud55c \ubc88 \ube4c\ub4dc\ub85c \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ubc30\ud3ec\ud558\ub294 \ubc29\ubc95\uc744 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ud658\uacbd\uc774 \ud558\ub098 \ub298 \ub54c\ub9c8\ub2e4 \uc571\uc744 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0 \uc788\ub2e4\uba74, \ud658\uacbd\ubcc4 \uac12\uc774 \ube4c\ub4dc \uacb0\uacfc\ubb3c \uc548\uc5d0 \ubc15\ud600 \uc788\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \uc774\ub7f0 \uac12\uc740 \ube4c\ub4dc\uc5d0 \ubc15\uc9c0 \ub9d0\uace0 \uc571\uc774 \ucf1c\uc9c8 \ub54c \uc77d\ub294 \ub7f0\ud0c0\uc784 \uc124\uc815 \ud30c\uc77c\ub85c \ubd84\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\uadf8\ub7ec\uba74 \uc571\uc740 \ud55c \ubc88\ub9cc \ube4c\ub4dc\ud558\uace0, \uc124\uc815 \ud30c\uc77c\ub9cc \ud658\uacbd\uc5d0 \ub9de\uac8c \uac08\uc544 \ub07c\uc6b0\uba74 \ub429\ub2c8\ub2e4.\\n\\n## \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uacfc \ub7f0\ud0c0\uc784 \uc8fc\uc785, \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00\\n\\n\ucc28\uc774\ub294 \ud658\uacbd\ubcc4 \uac12\uc774 \uc815\ud574\uc9c0\ub294 \uc2dc\uc810\uc785\ub2c8\ub2e4. \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uc740 \ube4c\ub4dc\ud560 \ub54c \uac12\uc744 \ucf54\ub4dc\uc5d0 \ubc15\uc544 \ub123\uace0, \ub7f0\ud0c0\uc784 \uc8fc\uc785\uc740 \uc571\uc774 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ucf1c\uc9c8 \ub54c \uac12\uc744 \uc77d\uc2b5\ub2c8\ub2e4.\\n\\n| \uad6c\ubd84 | \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785 | \ub7f0\ud0c0\uc784 \uc8fc\uc785 |\\n| --- | --- | --- |\\n| \uac12\uc774 \uc815\ud574\uc9c0\ub294 \uc2dc\uc810 | \ube4c\ub4dc\ud560 \ub54c | \uc571\uc774 \ucf1c\uc9c8 \ub54c |\\n| \ud658\uacbd\uc774 N\uac1c\uba74 | N\ubc88 \ube4c\ub4dc | \ud55c \ubc88 \ube4c\ub4dc + \uc124\uc815 N\uac1c |\\n| \ub300\ud45c \uc608 | `import.meta.env.VITE_*` | `window.__ENV__` |\\n\\n\ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785(`VITE_*`, `REACT_APP_*` \ub4f1)\uc740 \ud3b8\ud558\uc9c0\ub9cc, \uac12\uc774 \uacb0\uacfc\ubb3c\uc5d0 \ubc15\ud600 \ubc84\ub9bd\ub2c8\ub2e4. \ud658\uacbd\uc774 \ub298\uba74 \uadf8\ub9cc\ud07c \ub2e4\uc2dc \ube4c\ub4dc\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n## \uc65c \ub7f0\ud0c0\uc784 \uc124\uc815\uc778\uac00\\n\\n\ub7f0\ud0c0\uc784 \uc124\uc815\uc774 \ud544\uc694\ud55c \uc774\uc720\ub294, \uac19\uc740 \uc571\uc744 \ud658\uacbd\ub9c8\ub2e4 \ub2e4\ub978 \uac12\uc73c\ub85c \ub744\uc6cc\uc57c \ud560 \ub54c \ub9e4\ubc88 \ub2e4\uc2dc \ube4c\ub4dc\ud560 \uc218 \uc5c6\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ud2b9\ud788 \uace0\uac1d\uc0ac\ub9c8\ub2e4 API \uc8fc\uc18c\uac00 \ub2e4\ub978 \uc628\ud504\ub808\ubbf8\uc2a4 \ubc30\ud3ec\uc5d0\uc11c\ub294 \ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uc774 \uace7 \ubb34\ub108\uc9d1\ub2c8\ub2e4.\\n\\n\ud55c \ubc88 \uc778\uc1c4\ud55c \uc548\ub0b4 \ucc45\uc790\uc5d0 \ube44\uc720\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubcf8\ubb38(\uc571)\uc740 \ud55c \ubc88\ub9cc \ucc0d\uace0, \ub9c8\uc9c0\ub9c9 \uc8fc\uc18c \ud398\uc774\uc9c0(\uc124\uc815)\ub9cc \ud658\uacbd\ub9c8\ub2e4 \uac08\uc544 \ub07c\uc6c1\ub2c8\ub2e4. \ucc45\uc790\ub97c \ud1b5\uc9f8\ub85c \ub2e4\uc2dc \ucc0d\uc9c0 \uc54a\uc544\ub3c4 \ub429\ub2c8\ub2e4.\\n\\n## \ub7f0\ud0c0\uc784 \uc124\uc815 \uc8fc\uc785 \uad6c\ud604 (config.js, \uc5d4\ud2b8\ub9ac\ud3ec\uc778\ud2b8 \uce58\ud658)\\n\\n\ube4c\ub4dc \uacb0\uacfc\ubb3c \ubc14\uae65\uc5d0 \uc124\uc815 \ud30c\uc77c\uc744 \ub530\ub85c \ub450\uace0, \uc571\uc774 \uc2dc\uc791\ud560 \ub54c \uadf8 \ud30c\uc77c\uc744 \uc77d\uac8c \ud569\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/spa-runtime-config-2.webp\\"\\n    alt=\\"\ube4c\ub4dc\ud0c0\uc784 \uc8fc\uc785\uc740 \ud658\uacbd\ub9c8\ub2e4 \ub2e4\uc2dc \ube4c\ub4dc\ud558\uace0, \ub7f0\ud0c0\uc784 \uc8fc\uc785\uc740 \ud55c \ubc88 \ube4c\ub4dc\ud55c \ub4a4 \ud658\uacbd\ubcc4 \uc124\uc815 \ud30c\uc77c\ub9cc \uac08\uc544 \ub07c\uc6b0\ub294 \ube44\uad50\\"\\n  />\\n</figure>\\n\\n### 1. \uc124\uc815 \ud30c\uc77c\uc744 \ub530\ub85c \ub454\ub2e4\\n\\n\ube4c\ub4dc\uc5d0 \ud3ec\ud568\ud558\uc9c0 \uc54a\ub294 `env-config.js`\ub97c \ub9cc\ub4e4\uc5b4 \uc804\uc5ed \uac1d\uccb4\uc5d0 \uac12\uc744 \uc2e3\uc2b5\ub2c8\ub2e4.\\n\\n```js\\n// env-config.js  (\ube4c\ub4dc \uc0b0\ucd9c\ubb3c\uc774 \uc544\ub2c8\ub77c \ubc30\ud3ec \uc2dc \uac08\uc544 \ub07c\uc6b0\ub294 \ud30c\uc77c)\\nwindow.__ENV__ = {\\n  API_BASE_URL: \\"https://api.example.com\\",\\n};\\n```\\n\\n### 2. index.html\uc5d0\uc11c \uba3c\uc800 \uc77d\ub294\ub2e4\\n\\n\uc571 \ubc88\ub4e4\ubcf4\ub2e4 \uba3c\uc800 \uc124\uc815 \ud30c\uc77c\uc744 \ub85c\ub4dc\ud569\ub2c8\ub2e4.\\n\\n```html\\n<script src=\\"/env-config.js\\"><\/script>\\n<script type=\\"module\\" src=\\"/assets/index.js\\"><\/script>\\n```\\n\\n### 3. \ucf54\ub4dc\uc5d0\uc11c \uc0ac\uc6a9\ud55c\ub2e4\\n\\n```ts\\nconst API_BASE_URL =\\n  window.__ENV__?.API_BASE_URL ?? \\"http://localhost:8080\\"; // \ub85c\uceec \uae30\ubcf8\uac12\\n```\\n\\n### 4. \ud658\uacbd\ub9c8\ub2e4 \uc124\uc815 \ud30c\uc77c\ub9cc \uad50\uccb4\\n\\n\ubc30\ud3ec \ud658\uacbd\uc5d0\uc11c `env-config.js`\ub9cc \uadf8 \ud658\uacbd \uac12\uc73c\ub85c \ubc14\uafc9\ub2c8\ub2e4. \ucfe0\ubc84\ub124\ud2f0\uc2a4\ub77c\uba74 ConfigMap\uc744 \ubcfc\ub968\uc73c\ub85c \ub9c8\uc6b4\ud2b8\ud574 \uc774 \ud30c\uc77c\uc744 \ub36e\uc5b4\uc501\ub2c8\ub2e4. \uc571 \ubc88\ub4e4\uc740 \uadf8\ub300\ub85c \ub461\ub2c8\ub2e4.\\n\\n## \uc124\uc815 \ud30c\uc77c\uc774 CDN \uc5d0 \uce90\uc2dc\ub420 \ub54c\\n\\n\uac00\uc7a5 \uc790\uc8fc \ub370\uc774\ub294 \ud568\uc815\uc740 CDN \uce90\uc2dc\uc785\ub2c8\ub2e4. \ud654\uba74 \ud30c\uc77c\uc740 \ube60\ub978 \uc751\ub2f5\uc744 \uc704\ud574 CDN\uc5d0 \uce90\uc2dc\ub418\ub294\ub370, <span style={{ backgroundColor: \'#ffdce0\'}}>\uc124\uc815 \ud30c\uc77c\uae4c\uc9c0 \uce90\uc2dc\ub418\uba74 \uac12\uc744 \ubc14\uafd4\ub3c4 \uc61b \uc124\uc815\uc774 \uacc4\uc18d \ub0b4\ub824\uac11\ub2c8\ub2e4.</span>\\n\\n\uc124\uc815 \ud30c\uc77c\uc5d0\ub9cc \uce90\uc2dc\ub97c \ub044\uba74 \ud574\uacb0\ub429\ub2c8\ub2e4.\\n\\n```text\\nCache-Control: no-store      # env-config.js \uc5d0\ub9cc \uc801\uc6a9\\n```\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/spa-runtime-config-3.webp\\"\\n    alt=\\"CDN\uc774 \uc124\uc815 \ud30c\uc77c\uae4c\uc9c0 \uce90\uc2dc\ud574 \uc61b \uac12\uc774 \ub0b4\ub824\uac00\ub294 \ubb38\uc81c\uc640, \uc124\uc815 \ud30c\uc77c\uc5d0\ub9cc no-store\ub97c \uc801\uc6a9\ud55c \ud574\uacb0\\"\\n  />\\n</figure>\\n\\n\uadf8 \uc678 \uc8fc\uc758\uc810:\\n\\n- \ube4c\ub4dc\ud0c0\uc784\uacfc \ub7f0\ud0c0\uc784\uc744 \uc11e\uc9c0 \uc54a\uae30: `import.meta.env`\uc640 `window.__ENV__`\ub97c \ud55c \uac12\uc5d0 \uc11e\uc73c\uba74 \uc5b4\ub290 \ucabd\uc774 \uc801\uc6a9\ub410\ub294\uc9c0 \ud5f7\uac08\ub9bd\ub2c8\ub2e4. \ud658\uacbd\ubcc4 \uac12\uc740 \ub7f0\ud0c0\uc784\uc73c\ub85c \uc77c\uc6d0\ud654\ud569\ub2c8\ub2e4.\\n- \ub85c\uceec \uae30\ubcf8\uac12 \ub450\uae30: \uc124\uc815 \ud30c\uc77c\uc774 \uc5c6\uc744 \ub54c\ub97c \ub300\ube44\ud574 \ucf54\ub4dc\uc5d0 \uc548\uc804\ud55c \uae30\ubcf8\uac12(`?? localhost`)\uc744 \ub461\ub2c8\ub2e4.\\n- \ubbfc\uac10 \uc815\ubcf4 \uae08\uc9c0: `env-config.js`\ub294 \ube0c\ub77c\uc6b0\uc800\uac00 \uadf8\ub300\ub85c \uc77d\uc2b5\ub2c8\ub2e4. \ube44\ubc00 \ud0a4 \uac19\uc740 \ubbfc\uac10 \uac12\uc740 \uc808\ub300 \ub123\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## Q&A\\n\\n- **Next.js \uac19\uc740 SSR\ub3c4 \uac19\uc740 \ubc29\ubc95\uc778\uac00\uc694?**\\n  - SSR\uc740 \uc11c\ubc84\uc5d0\uc11c \ud658\uacbd \ubcc0\uc218\ub97c \uc9c1\uc811 \uc77d\uc744 \uc218 \uc788\uc5b4 \uc0ac\uc815\uc774 \ub2e4\ub985\ub2c8\ub2e4. \uc774 \ubc29\ubc95\uc740 \uc815\uc801\uc73c\ub85c \ube4c\ub4dc\ub418\ub294 SPA(CSR)\uc5d0\uc11c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n- **`.env` \ud30c\uc77c\uc744 \uc5ec\ub7ec \uac1c \ub450\uba74 \uc548 \ub418\ub098\uc694?**\\n  - `.env.production` \ub4f1\uc740 \uacb0\uad6d \ube4c\ub4dc\ud0c0\uc784\uc5d0 \ubc15\ud799\ub2c8\ub2e4. \ud658\uacbd\uc774 \ube4c\ub4dc \ud6c4\uc5d0 \uc815\ud574\uc9c0\ub294 \uacbd\uc6b0(\uc628\ud504\ub808\ubbf8\uc2a4 \ub4f1)\uc5d0\ub294 \ub7f0\ud0c0\uc784 \uc124\uc815\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- **\uc124\uc815 \uac12\uc774 \ub9ce\uc544\uc9c0\uba74\uc694?**\\n  - `window.__ENV__` \uac1d\uccb4\uc5d0 \ubaa8\uc74d\ub2c8\ub2e4. \ud0c0\uc785 \uc548\uc804\uc744 \uc704\ud574 \ud55c \uacf3\uc5d0\uc11c \uc77d\uc5b4 \uac80\uc99d\ud55c \ub4a4 \uc571 \uc804\uc5ed\uc5d0 \uc81c\uacf5\ud558\ub294 \ub798\ud37c\ub97c \ub450\uba74 \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- [MDN: Cache-Control](https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Cache-Control): `no-store`, `max-age`\\n- [The Twelve-Factor App: Config](https://12factor.net/config)"},{"id":"why-learn-python-now","metadata":{"permalink":"/blog/why-learn-python-now","source":"@site/blog/2025-07-03-why-learn-python-now/index.md","title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","description":"AI, \ub370\uc774\ud130, \uc790\ub3d9\ud654, \uadf8\ub9ac\uace0 \uc0c8\ub85c\uc6b4 \uc9c1\uad70\ub4e4\uc774 \uc0dd\uaca8\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4.","date":"2025-07-03T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"Python","permalink":"/blog/tags/python"}],"readingTime":1.29,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","slug":"why-learn-python-now","authors":["kgenots"],"tags":["Tech","Python"],"image":"/assets/blog/why-learn-python-now.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"SPA\ub97c \ud55c \ubc88 \ube4c\ub4dc\ud574 \uc5ec\ub7ec \ud658\uacbd\uc5d0 \ub744\uc6b0\uae30 (\ub7f0\ud0c0\uc784 \uc124\uc815)","permalink":"/blog/spa-runtime-config"},"nextItem":{"title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","permalink":"/blog/2025-h1-review"}},"content":"AI, \ub370\uc774\ud130, \uc790\ub3d9\ud654, \uadf8\ub9ac\uace0 \uc0c8\ub85c\uc6b4 \uc9c1\uad70\ub4e4\uc774 \uc0dd\uaca8\ub098\uace0 \uc788\uc2b5\ub2c8\ub2e4.  \\n\u2018MLOps \uc5d4\uc9c0\ub2c8\uc5b4\u2019, \u2018AI \ub9ac\uc11c\ucc98\u2019, \u2018\ub370\uc774\ud130 \ud37c\ube14\ub9ac\uc154\u2019\u2026  \\n\uc774\ub7f0 \ubcc0\ud654 \uc18d\uc5d0\uc11c \uac1c\ubc1c\uc790\ub294 \uc5b4\ub5a4 \uae30\uc220\uc744 \ubc30\uc6b0\uace0, \uc5b4\ub5a4 \ub3c4\uad6c\ub97c \uc775\ud600\uc57c \ud560\uae4c\uc694?\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/why-learn-python-now.webp\\"\\n    alt=\\"why-learn-python-now\\"\\n  />\\n</figure>\\n\\n## \ud83e\udded \uc775\uc219\ud55c \uae30\uc220, \ub0af\uc120 \uc2dc\ub300\\n\\n\ud55c\ub3d9\uc548 \uad6d\ub0b4 \uac1c\ubc1c \ud658\uacbd, \ud2b9\ud788 \uacf5\uacf5 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 **Java \uae30\ubc18\uc758 Spring Boot**\uac00 \ud45c\uc900\ucc98\ub7fc \uc0ac\uc6a9\ub410\uc2b5\ub2c8\ub2e4.\\n\\n- Spring + MyBatis \uc870\ud569\\n- JSP, DAO, Service \uacc4\uce35\uc73c\ub85c \ub098\ub25c \uad6c\uc870\\n- XML \uc124\uc815\uacfc \uc815\ud615\ud654\ub41c \ud328\ud134\\n- \uacf5\uacf5\uae30\uad00 \uc911\uc2ec\uc758 \uc548\uc815\uc801 \uad6c\uc870\\n\\n> \\"\uadf8\ub7fc \uc9c0\uae08\ub3c4 Java\ub9cc\uc73c\ub85c \ucda9\ubd84\ud560\uae4c?\\"\\n\\n## \ud83e\udd16 \uc0c8\ub85c\uc6b4 \uc9c1\uad70\uc740 Python\uc744 \uc4f4\ub2e4\\n\\nAI \uac1c\ubc1c, \ub370\uc774\ud130 \ubd84\uc11d, \uc790\ub3d9\ud654, \uc2dc\uc2a4\ud15c \uc6b4\uc601\u2026\\n\uc774 \ubaa8\ub4e0 \uc601\uc5ed\uc5d0\uc11c \uc911\uc2ec\uc5d0 \uc788\ub294 \uc5b8\uc5b4\ub294 **Python**\uc785\ub2c8\ub2e4.\\n\\n- ChatGPT, HuggingFace, Llama \uac19\uc740 LLM \u2192 \ubaa8\ub450 Python \uae30\ubc18\\n- FastAPI, Django \u2192 \ube60\ub978 \ubc31\uc5d4\ub4dc \uac1c\ubc1c \uac00\ub2a5\\n- Pandas, Jupyter \u2192 \ubd84\uc11d\uacfc \ubcf4\uace0 \uc790\ub3d9\ud654\\n- Airflow, Schedule \u2192 \uc5c5\ubb34 \ud750\ub984 \uc790\ub3d9\ud654\\n- Markdown + Python \u2192 \ubb38\uc11c\ud654 \ubc0f \ud37c\ube14\ub9ac\uc2f1\\n\\nPython\uc740 \ub2e8\uc21c\ud788 \\"\ubc30\uc6cc\ub450\uba74 \uc88b\uc740 \uc5b8\uc5b4\\"\uac00 \uc544\ub2d9\ub2c8\ub2e4.  \\n**\uc9c0\uae08\uc758 \uae30\uc220 \uc0dd\ud0dc\uacc4\uc5d0\uc11c \uac00\uc7a5 \uc790\uc8fc \uc4f0\uc774\uace0, \uc2e4\uc81c\ub85c \uc4f0\uc774\ub294 \uc5b8\uc5b4**\uc785\ub2c8\ub2e4.\\n\\n---\\n\\n## \u2699\ufe0f Java\uc640 Python, \ud568\uaed8 \uc368\ubd10\uc57c \ubcf4\uc778\ub2e4\\n\\nJava\ub9cc \uc368\ubcf8 \uac1c\ubc1c\uc790\ub77c\uba74, \uc774\ub7f0 \uc758\ubb38\uc774 \ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n> \u201cJava\ub85c\ub3c4 \ub2e4 \ub418\uc9c0 \uc54a\ub098?\u201d\\n\\n\ub9de\uc2b5\ub2c8\ub2e4. Java\ub294 \uc5ec\uc804\ud788 \uc720\ud6a8\ud558\uace0, \ud2b9\ud788 \ub300\uaddc\ubaa8 \ubc31\uc5d4\ub4dc \uc2dc\uc2a4\ud15c\uc5d0 \uac15\ud569\ub2c8\ub2e4.  \\n\ud558\uc9c0\ub9cc **\uc0dd\uc0b0\uc131, \uac04\uacb0\ud568, \uc790\ub3d9\ud654, \ube60\ub978 \ud53c\ub4dc\ubc31 \ub8e8\ud504**\ub294 Python\uc774 \ud6e8\uc52c \uc720\ub9ac\ud569\ub2c8\ub2e4.\\n\\n| \ud56d\ubaa9           | Java (\uc804\uc790\uc815\ubd80\ud504\ub808\uc784\uc6cc\ud06c) | Python                      |\\n| -------------- | ------------------------- | --------------------------- |\\n| \uc0dd\uc0b0\uc131         | \uc124\uc815 \ub9ce\uace0 \uad6c\uc870 \ubcf5\uc7a1       | \ube60\ub978 \uac1c\ubc1c, \uac04\uacb0\ud55c \ucf54\ub4dc      |\\n| AI/\ub370\uc774\ud130 \uc5f0\uacc4 | \uc57d\ud568                      | \uac15\ub825\ud55c \uc0dd\ud0dc\uacc4               |\\n| \uc790\ub3d9\ud654/Ops     | \ubb34\uac70\uc6c0                    | \uacbd\ub7c9\ud654, \uc2a4\ud06c\ub9bd\ud2b8 \uce5c\ud654       |\\n| \uc9c4\uc785\uc7a5\ubcbd       | \ub192\uc74c (JVM, \ube4c\ub4dc \ub3c4\uad6c \ub4f1)  | \ub0ae\uc74c (\uac04\ub2e8\ud55c \ubb38\ubc95)          |\\n| \ud37c\ube14\ub9ac\uc2f1       | JSP, JavaDoc \ub4f1 \uc804\ud1b5\uc801    | Markdown, Jupyter \ub4f1 \uc720\uc5f0\ud568 |\\n\\n---\\n\\n## \ud83e\udde0 \ud788\uc2a4\ud1a0\ub9ac\ub97c \uc544\ub294 Python \uac1c\ubc1c\uc790\\n\\n\uc5ec\uae30\uc11c \uc911\uc694\ud55c \uac74 **Java\ub97c \ubc84\ub9ac\uc790\ub294 \uac8c \uc544\ub2c8\ub77c**,  \\n**Java \uae30\ubc18 \uc2dc\uc2a4\ud15c\uc744 \uc774\ud574\ud558\ub294 \uc0ac\ub78c\uc774 Python\uae4c\uc9c0 \uc775\ud788\uba74 \ubb34\uae30\uac00 \ub41c\ub2e4\ub294 \uac83**\uc785\ub2c8\ub2e4.\\n\\n\uc804\uc790\uc815\ubd80\ud504\ub808\uc784\uc6cc\ud06c\ub85c \uad6c\uc131\ub41c \uc2dc\uc2a4\ud15c\uc744 \uc720\uc9c0\xb7\ubcf4\uc218\ud558\uba74\uc11c\ub3c4:\\n\\n- \ub85c\uadf8 \uc218\uc9d1 \ubc0f \ub9ac\ud3ec\ud305\uc740 Python\uc73c\ub85c\\n- \ubc30\uce58/\uc790\ub3d9\ud654 \uc2a4\ud06c\ub9bd\ud2b8\ub294 Python\uc73c\ub85c\\n- AI \uc5f0\ub3d9 \uae30\ub2a5\uc740 Python\uc73c\ub85c\\n- \uc6b4\uc601 \ub9ac\ud3ec\ud2b8 \uc790\ub3d9 \uc0dd\uc131\uc740 Python + Markdown\\n\\n> \ud788\uc2a4\ud1a0\ub9ac\ub97c \uc54c\uace0 \uc788\ub294 \uc0ac\ub78c\uc774,  \\n> \uc0c8\ub85c\uc6b4 \ub3c4\uad6c\ub85c \ubbf8\ub798\uae4c\uc9c0 \uc124\uacc4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n---\\n\\n## \ud83d\udca1 Python\uc740 \uc120\ud0dd\uc774 \uc544\ub2c8\ub77c, \uae30\ubcf8 \ub3c4\uad6c\\n\\n\uac1c\ubc1c\uc790\ub85c\uc11c \uc2dc\uc2a4\ud15c\uc744 \uc9c0\ud0a4\ub294 \uc77c\ub3c4 \uc911\uc694\ud558\uc9c0\ub9cc,  \\n\uc774\uc81c\ub294 \uadf8 \uc704\uc5d0 \ub370\uc774\ud130\ub97c \uc5f0\uacb0\ud558\uace0, \uc790\ub3d9\ud654\ud558\uace0,  \\n\ucf58\ud150\uce20\ub85c \uc815\ub9ac\ud574 **\uc804\ub2ec\ud560 \uc218 \uc788\ub294 \uc5ed\ub7c9**\uae4c\uc9c0 \uc694\uad6c\ub429\ub2c8\ub2e4.\\n\\n\uadf8 \ubaa8\ub4e0 \uc5ed\ud560\uc744 \uc720\uc5f0\ud558\uac8c \uc18c\ud654\ud560 \uc218 \uc788\ub294 \ub3c4\uad6c\uac00 \ubc14\ub85c Python\uc785\ub2c8\ub2e4.\\n\\n---\\n\\n## \u2615\ufe0f \ub9c8\ubb34\ub9ac\ud558\uba70\\n\\n\uc9c0\uae08 \uac1c\ubc1c\uc790\uc5d0\uac8c \ud544\uc694\ud55c \uac74 \\"\uc774 \uc5b8\uc5b4\uac00 \ub354 \uc88b\ub2e4\\"\ub294 \ub17c\uc7c1\uc774 \uc544\ub2d9\ub2c8\ub2e4.  \\n**\uae30\uc220\uc774 \ubc14\ub00c\ub294 \uc774\uc720\uc640 \ubc29\ud5a5\uc744 \uc774\ud574\ud558\uace0, \uac70\uae30\uc5d0 \uc801\uc751\ud560 \uc218 \uc788\ub294 \uc900\ube44**\uc785\ub2c8\ub2e4.\\n\\nJava\ub97c \uc798 \uc544\ub294 \uac1c\ubc1c\uc790\ub77c\uba74,\\nPython\uc740 \uc5b4\ub835\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.  \\n\uc624\ud788\ub824 **\ub354 \ube68\ub9ac, \ub354 \uac15\ud558\uac8c \uc131\uc7a5\ud560 \uc218 \uc788\ub294 \uae38**\uc774 \ub420 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc800\ub791 \ud568\uaed8\ud558\uace0 \uc2f6\ub2e4\uba74 kgenots@gmail.com \ub85c \uc5f0\ub77d\uc8fc\uc138\uc694 :D"},{"id":"2025-h1-review","metadata":{"permalink":"/blog/2025-h1-review","source":"@site/blog/2025-06-03-2025-1h-retrospective/index.md","title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","description":"2025\ub144 \uc0c1\ubc18\uae30\ub294 \uc65c \ub2ec\ub9ac\uace0 \uc788\ub294\uc9c0\ub97c \ub354 \ub9ce\uc774 \uace0\ubbfc\ud55c \uc2dc\uae30\uc600\uc2b5\ub2c8\ub2e4. \uae30\uc220\ud300 \ub9ac\ub354\ub85c\uc11c \ub9e1\ub294 \uc77c\uc774 \ub2ec\ub77c\uc84c\uace0, \ubc29\ud5a5\uc744 \ub2e4\uc2dc \uc7a1\uc544\uc57c \ud588\uc2b5\ub2c8\ub2e4.","date":"2025-06-03T00:00:00.000Z","tags":[{"inline":true,"label":"Tech","permalink":"/blog/tags/tech"},{"inline":true,"label":"\ud300\ub9ac\ub354\uc2ed","permalink":"/blog/tags/\ud300\ub9ac\ub354\uc2ed"},{"inline":true,"label":"\uc131\uc7a5\uae30\ub85d","permalink":"/blog/tags/\uc131\uc7a5\uae30\ub85d"}],"readingTime":0.79,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","slug":"2025-h1-review","authors":["kgenots"],"tags":["Tech","\ud300\ub9ac\ub354\uc2ed","\uc131\uc7a5\uae30\ub85d"],"image":"/assets/blog/retrospective-2025-1h.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\uc65c \uc9c0\uae08, Python\uc744 \uc54c\uc544\uc57c \ud560\uae4c?","permalink":"/blog/why-learn-python-now"},"nextItem":{"title":"Amazon Linux 2023 Docker Compose \uc124\uce58","permalink":"/blog/aws-linux-2023-docker"}},"content":"2025\ub144 \uc0c1\ubc18\uae30\ub294 \uc65c \ub2ec\ub9ac\uace0 \uc788\ub294\uc9c0\ub97c \ub354 \ub9ce\uc774 \uace0\ubbfc\ud55c \uc2dc\uae30\uc600\uc2b5\ub2c8\ub2e4. \uae30\uc220\ud300 \ub9ac\ub354\ub85c\uc11c \ub9e1\ub294 \uc77c\uc774 \ub2ec\ub77c\uc84c\uace0, \ubc29\ud5a5\uc744 \ub2e4\uc2dc \uc7a1\uc544\uc57c \ud588\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/retrospective-2025-1h.webp\\"\\n    alt=\\"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ub9e1\uc558\ub358 \uc77c\ub4e4\uc744 \uc11c\ube44\uc2a4, \uc2dc\uc2a4\ud15c, \ub370\uc774\ud130, \ud234\ub9c1\uc73c\ub85c \ub098\ub220 \uc815\ub9ac\ud55c \uadf8\ub9bc\\"\\n  />\\n</figure>\\n\\n## \uc11c\ube44\uc2a4 \uad6c\ucd95\uacfc \ub9ac\ub274\uc5bc\\n\\n- IT \uc911\uc7a5\uae30 \uacc4\ud68d \uc218\ub9bd\uacfc \ubb38\uc11c\ud654\\n- \ud769\uc5b4\uc838 \uc788\ub358 \ubc31\uc624\ud53c\uc2a4 \uc2dc\uc2a4\ud15c\uc744 \ud558\ub098\ub85c \ubaa8\uc73c\ub294 \uc791\uc5c5 (ERP)\\n- \ud68c\uc0ac \ud648\ud398\uc774\uc9c0 \uac1c\ud3b8 \uae30\ud68d\\n- \uc911\uac1c\uc0ac\uc6a9 \ub9e4\ubb3c \uad00\ub9ac \uc11c\ube44\uc2a4 \uae30\ud68d\\n\\n\uae30\ud68d\uc744 \ubb38\uc11c\ub85c \ub0a8\uae30\ub294 \ub370 \uc2dc\uac04\uc744 \ub9ce\uc774 \uc37c\uc2b5\ub2c8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uc190\uc774 \ub290\ub824\uc9c0\ub294 \ub290\ub08c\uc774\uc5c8\ub294\ub370, \uac19\uc740 \ub17c\uc758\ub97c \ub450 \ubc88 \ud558\uc9c0 \uc54a\uac8c \ub418\uba74\uc11c \uc18d\ub3c4\uac00 \ubd99\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \uae30\uc220\uacfc \uc2dc\uc2a4\ud15c \uad6c\uc131\\n\\n- FastAPI \uae30\ubc18 \ub9c8\uc774\ud06c\ub85c\uc11c\ube44\uc2a4 \uc544\ud0a4\ud14d\ucc98 \uc124\uacc4\\n- AWS Aurora PostgreSQL Serverless V2\uc640 RDS Proxy \uc870\ud569 \ucd5c\uc801\ud654\\n- Whisper\uc640 Streamlit, \ubb38\uc11c \ub3c4\uad6c\ub97c \uc5ee\uc740 \ud68c\uc758 \uae30\ub85d \uc790\ub3d9\ud654\\n- n8n\uc744 \uc774\uc6a9\ud55c \uc774\uba54\uc77c \uc790\ub3d9 \ubd84\ub958\uc640 \uc2a4\ud504\ub808\ub4dc\uc2dc\ud2b8 \uae30\ub85d \uc790\ub3d9\ud654\\n\\n:::info \uc0ac\ub78c\uc774 \ud558\ub358 \ubc1b\uc544\uc4f0\uae30\\n\ud68c\uc758\ub85d\uc740 \ub204\uad70\uac00 \ud68c\uc758 \ub0b4\ub0b4 \ubc1b\uc544 \uc801\uc5b4\uc57c \ud558\ub294 \uc77c\uc785\ub2c8\ub2e4. \ub179\uc74c\uc744 \ud14d\uc2a4\ud2b8\ub85c \ubcc0\ud658\ud558\ub294 \ub2e8\uacc4\ub9cc \uae30\uacc4\uc5d0 \ub9e1\uacbc\ub354\ub2c8, \uc0ac\ub78c\uc740 \uc815\ub9ac\ud558\uace0 \ud310\ub2e8\ud558\ub294 \uc77c\ub9cc \ub2f4\ub2f9\ud558\uba74 \ub410\uc2b5\ub2c8\ub2e4.\\n:::\\n\\n\uc790\ub3d9\ud654 \ub300\uc0c1\uc740 \uc0ac\ub78c\uc774 \ubc18\ubcf5\ud558\ub2e4 \uc2e4\uc218\ud558\ub294 \uc791\uc5c5\uc73c\ub85c \ud55c\uc815\ud588\uc2b5\ub2c8\ub2e4. \ud310\ub2e8\uc774 \ud544\uc694\ud55c \uc791\uc5c5\uc740 \uadf8\ub300\ub85c \ub450\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \ub370\uc774\ud130\ub97c \uadfc\uac70\ub85c \ud55c \uae30\ud68d\\n\\n- VOC \uc790\ub3d9\ud654\ubcf4\ub2e4 B2C \ud37c\ub110 \ud655\uc7a5\uacfc \ub0b4\ubd80 IT \ub9ac\uc18c\uc2a4 \ud6a8\uc728\ud654\uc5d0 \ubb34\uac8c\ub97c \ub450\uc5c8\uc2b5\ub2c8\ub2e4\\n- \ube0c\ub79c\ub4dc \ub9c8\ucf00\ud305 \uc870\uc9c1\uacfc \ud568\uaed8 \ud611\uc5c5 \uc544\uc820\ub2e4\ub97c \ubf51\uc558\uc2b5\ub2c8\ub2e4\\n\\n\uc6b0\uc120\uc21c\uc704\ub97c \uc815\ud560 \ub54c \uc22b\uc790\ub97c \uba3c\uc800 \ubcf8 \uc2b5\uad00\uc774 \ub3c4\uc6c0\uc774 \ub410\uc2b5\ub2c8\ub2e4.\\n\\n## \ud234\ub9c1\\n\\n- Ruff\uc640 uv \uc870\ud569\uc744 \ub3c4\uc785\ud574 Python \ud504\ub85c\uc81d\ud2b8 \ud234\ub9c1\uc744 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4\\n\\n\ub9b0\ud2b8\uc640 \uc758\uc874\uc131 \uc124\uce58\ub97c \uae30\ub2e4\ub9ac\ub294 \uc2dc\uac04\uc774 \uc904\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n## \ub3cc\uc544\ubcf4\uba70\\n\\n\uc0c1\ubc18\uae30 \ub0b4\ub0b4 \uc720\uc9c0\ud560 \uc218 \uc788\ub294 \ub9cc\ud07c\ub9cc \ub9cc\ub4e4\uc790\ub294 \uae30\uc900\uc744 \uc801\uc6a9\ud588\uc2b5\ub2c8\ub2e4. \ub9ac\ub354 \uc5ed\ud560\uc774 \ub2ec\ub77c\uc9c4 \uac83\ub3c4 \uac19\uc740 \uae30\uc900\uc5d0\uc11c \ube44\ub86f\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc9c0 \uacb0\uc815\ud558\ub294 \uc2dc\uac04\ubcf4\ub2e4 \ubb34\uc5c7\uc744 \ub9cc\ub4e4\uc9c0 \uc54a\uc744\uc9c0 \uacb0\uc815\ud558\ub294 \uc2dc\uac04\uc774 \ub354 \uae38\uc5c8\uc2b5\ub2c8\ub2e4."},{"id":"aws-linux-2023-docker","metadata":{"permalink":"/blog/aws-linux-2023-docker","source":"@site/blog/2024-03-21-aws-linux-2023-docker/index.md","title":"Amazon Linux 2023 Docker Compose \uc124\uce58","description":"\ucd5c\uc2e0 \ubc84\uc804\uc758 Docker Compose\ub97c \uc774\uc6a9\ud558\uae30 \uc704\ud574 Docker Compose \ud50c\ub7ec\uadf8\uc778\uc744 \uc0ac\uc6a9\ud574\ubcf4\uc790.","date":"2024-03-21T00:00:00.000Z","tags":[{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"AWS","permalink":"/blog/tags/aws"}],"readingTime":0.33,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Amazon Linux 2023 Docker Compose \uc124\uce58","slug":"aws-linux-2023-docker","authors":["kgenots"],"tags":["Ops","AWS"],"image":"/assets/blog/unnamed-docker.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"2025\ub144 \uc0c1\ubc18\uae30\uc5d0 \ud55c \uc77c \uc815\ub9ac","permalink":"/blog/2025-h1-review"},"nextItem":{"title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","permalink":"/blog/docker-commands"}},"content":"\ucd5c\uc2e0 \ubc84\uc804\uc758 Docker Compose\ub97c \uc774\uc6a9\ud558\uae30 \uc704\ud574 Docker Compose \ud50c\ub7ec\uadf8\uc778\uc744 \uc0ac\uc6a9\ud574\ubcf4\uc790.\\n\\n\x3c!--truncate--\x3e\\n\\n## Docker Compose \ud50c\ub7ec\uadf8\uc778 \uc124\uce58\\n\\n```\\n# Docker\\nsudo yum install -y docker\\nsudo usermod -aG docker ec2-user\\nsudo systemctl enable --now docker\\nexec bash\\n\\ndocker ps\\n\\n# Compose Plugin\\nsudo mkdir -p /usr/local/lib/docker/cli-plugins/\\nsudo curl -SL \\"https://github.com/docker/compose/releases/latest/download/docker-compose-linux-$(uname -m)\\" -o /usr/local/lib/docker/cli-plugins/docker-compose\\nsudo chmod +x /usr/local/lib/docker/cli-plugins/docker-compose\\n\\ndocker compose version\\n```\\n\\n## Docker Compose \ud50c\ub7ec\uadf8\uc778\uc744 docker-compose \uba85\ub839\uc5b4\ub85c \uc0ac\uc6a9\\n\\n```\\nalias docker-compose=\'docker compose --compatibility \\"$@\\"\'\\n```"},{"id":"docker-commands","metadata":{"permalink":"/blog/docker-commands","source":"@site/blog/2024-03-20-docker-commands/index.md","title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","description":"Docker\uc640 \uad00\ub828\ub41c \uae30\ubcf8 \uba85\ub839\uc5b4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.","date":"2024-03-20T00:00:00.000Z","tags":[{"inline":true,"label":"Ops","permalink":"/blog/tags/ops"},{"inline":true,"label":"Virtualization","permalink":"/blog/tags/virtualization"}],"readingTime":0.86,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","slug":"docker-commands","authors":["kgenots"],"tags":["Ops","Virtualization"],"image":"/assets/blog/unnamed-docker.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Amazon Linux 2023 Docker Compose \uc124\uce58","permalink":"/blog/aws-linux-2023-docker"},"nextItem":{"title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","permalink":"/blog/postgresql-saas-multitenancy"}},"content":"Docker\uc640 \uad00\ub828\ub41c \uae30\ubcf8 \uba85\ub839\uc5b4\ub97c \uc0b4\ud3b4\ubd05\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<b>PC\ub85c \uc811\uc18d\ud558\uc2e0 \ud6c4 \ud398\uc774\uc9c0 \uc6b0\uce21 \uc0c1\ub2e8\uc758 <span style={{ backgroundColor: \'#fff5b1\'}}>\ubaa9\ucc28</span>\ub97c \uc774\uc6a9\ud558\uc2dc\uba74 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.</b> (\uadf8\ub9ac\uace0 \ub4dc\ub798\uadf8 \uc548 \ub3fc\uc694...)\\n\\n## Docker Image \uad00\ub828\\n\\n### \uc774\ubbf8\uc9c0 \ubaa9\ub85d\\n\\n1. \uc804\uccb4 \uc774\ubbf8\uc9c0 \ubaa9\ub85d\\n\\n```\\ndocker images -a\\n```\\n\\n### \uc774\ubbf8\uc9c0 \uc0ad\uc81c\\n\\n1. <span style={{ backgroundColor: \'#fff5b1\'}}><b>\ud2b9\uc815 \uc774\ubbf8\uc9c0</b></span> \uc0ad\uc81c\\n\\n```\\ndocker rmi <image_id|name>\\n```\\n\\n2. <span style={{ backgroundColor: \'#ffdce0\'}}><b>\ubaa8\ub4e0 \uc774\ubbf8\uc9c0</b></span> \uc0ad\uc81c\\n\\n```\\ndocker rmi `docker images -q` -f\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc2e4\ud589\\n\\n```\\ndocker start <image_name:tag>\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc885\ub8cc\\n\\n```\\ndocker stop <container_id|name>\\n```\\n\\n---\\n\\n## Docker Container \uad00\ub828\\n\\n### \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n1. \uc2e4\ud589\uc911\uc778 \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n```\\ndocker ps\\n```\\n\\n2. \uc804\uccb4 \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n```\\ndocker ps -a\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc811\uc18d\\n\\n```\\ndocker exec -it <container_id|name> /bin/bash\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc811\uc18d \uc885\ub8cc\\n\\n```\\nexit\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \uc0ad\uc81c\\n\\n1. <span style={{ backgroundColor: \'#fff5b1\'}}><b>\ud2b9\uc815 \ucee8\ud14c\uc774\ub108</b></span> \uc0ad\uc81c\\n\\n```\\ndocker rm <container_id|name>\\n```\\n\\n2. <span style={{ backgroundColor: \'#ffdce0\'}}><b>\ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108</b></span> \uc0ad\uc81c (\ubcf5\uad6c\uac00 \ubd88\uac00\ub2a5\ud558\ub2c8 \uc8fc\uc758)\\n\\n```\\ndocker rm `docker ps -aq` -f\\n```\\n\\n3. <span style={{ backgroundColor: \'#f1f8ff\'}}><b>\uc911\uc9c0\ub41c \ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108</b></span> \uc0ad\uc81c\\n\\n```\\ndocker container prune\\n```\\n\\n### \ucee8\ud14c\uc774\ub108 \ub85c\uadf8 \ud655\uc778\\n\\n1. <span style={{ backgroundColor: \'#fff5b1\'}}><b>\ud2b9\uc815 \ucee8\ud14c\uc774\ub108</b></span> \ub85c\uadf8\\n\\n```\\ndocker logs -t -f <container_id|name>\\n```\\n\\n2. <span style={{ backgroundColor: \'#ffdce0\'}}><b>\ubaa8\ub4e0 \ucee8\ud14c\uc774\ub108</b></span> \ub85c\uadf8\\n\\n```\\ndocker logs -t -f\\n```\\n\\n---\\n\\n## Docker Compose \uad00\ub828\\n\\n### \ucef4\ud3ec\uc988 \uba85\ub839\uc5b4 \ubb38\uc81c\\n\\n\uba85\ub839\uc5b4 \ud638\ud658\uc131 \uc774\uc288 \uc788\uc744 \ub54c \uc0ac\uc6a9\\n\\n```\\nalias docker-compose=\'docker compose --compatibility \\"$@\\"\'\\n```\\n\\n### \ucef4\ud3ec\uc988 \uc2e4\ud589\\n\\n1. \ud3ec\uadf8\ub77c\uc6b4\ub4dc \uc2e4\ud589\\n\\n```\\ndocker compose up\\n```\\n\\n2. \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc2e4\ud589\\n\\n```\\ndocker compose up -d\\n```\\n\\n### \ucef4\ud3ec\uc988 \uc885\ub8cc\\n\\n1. \uae30\ubcf8\\n\\n```\\ndocker compose down\\n```\\n\\n2. \ubcfc\ub968 \uc81c\uac70 \ud544\uc694\uc2dc\\n\\n```\\ndocker compose down -v\\n```\\n\\n### \uc0dd\uc131\ub41c \ucee8\ud14c\uc774\ub108 \ubaa9\ub85d\\n\\n```\\ndocker compose ps\\n```\\n\\n---"},{"id":"postgresql-saas-multitenancy","metadata":{"permalink":"/blog/postgresql-saas-multitenancy","source":"@site/blog/2023-11-13-posgresql-saas-multitenancy/index.md","title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","description":"\uba40\ud2f0\ud14c\ub10c\uc2dc\uc758 \uc758\ubbf8\ub97c \uc54c\uc544\ubcf4\uace0 PostgreSQL \uc5d0\uc11c \uba40\ud2f0\ud14c\ub10c\uc2dc\ub97c \uad6c\uc131\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubd05\ub2c8\ub2e4.","date":"2023-11-13T00:00:00.000Z","tags":[{"inline":true,"label":"DB","permalink":"/blog/tags/db"},{"inline":true,"label":"PostgreSQL","permalink":"/blog/tags/postgre-sql"}],"readingTime":1.91,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","slug":"postgresql-saas-multitenancy","authors":["kgenots"],"tags":["DB","PostgreSQL"],"image":"/assets/blog/unnamed-postgresql.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Docker \uba85\ub839\uc5b4 \uc815\ub9ac (\uc774\ubbf8\uc9c0, \ucee8\ud14c\uc774\ub108)","permalink":"/blog/docker-commands"},"nextItem":{"title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","permalink":"/blog/database-generate-erd"}},"content":"\uba40\ud2f0\ud14c\ub10c\uc2dc\uc758 \uc758\ubbf8\ub97c \uc54c\uc544\ubcf4\uace0 PostgreSQL \uc5d0\uc11c \uba40\ud2f0\ud14c\ub10c\uc2dc\ub97c \uad6c\uc131\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubd05\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uba40\ud2f0\ud14c\ub10c\uc2dc(Multi-Tenancy) \ub780?\\n\\n\uba3c\uc800, \ud14c\ub10c\uc2dc(Tenancy)\ub780 \'\ucc28\uc6a9, \uc18c\uc791\'\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ud558\ub098\uc758 \uc778\uc2a4\ud134\uc2a4\ub85c \uc5ec\ub7ec \uace0\uac1d\uc5d0\uac8c \uc11c\ube44\uc2a4\ub97c \uc81c\uacf5\ud560 \uc218 \uc788\ub294 \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uc544\ud0a4\ud14d\ucc98\ub97c \'\uba40\ud2f0\ud14c\ub10c\uc2dc(Multi-Tenancy)\'\ub77c\uace0 \ud569\ub2c8\ub2e4. \ubc18\ub300\ub418\ub294 \uac1c\ub150\uc73c\ub85c \ub2e8\uc77c \uc778\uc2a4\ud134\uc2a4 - \ub2e8\uc77c \uace0\uac1d\uc778 \uacbd\uc6b0 \ub2e8\uc77c \ud14c\ub10c\uc2dc\ub77c\uace0 \ud569\ub2c8\ub2e4.\\n\\n\ub2e4\uc2dc \ub9d0\ud574, \uba40\ud2f0 \ud14c\ub10c\uc2dc\ub294 \ud558\ub098\uc758 \uc11c\ube44\uc2a4 \ub0b4\uc5d0\uc11c \'\uace0\uac1d\uc758 \uc815\ubcf4\ub97c \ubd84\ub9ac/\uad00\ub9ac\'\ud558\ub294 \uac83\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5\\n\\n\uba40\ud2f0\ud14c\ub10c\uc2dc\ub97c \uad6c\uc131\ud558\ub294 \uc804\ub7b5\uc740 \ub300\ud45c\uc801\uc73c\ub85c Silo \ubaa8\ub378, Pool \ubaa8\ub378, Bridge \ubaa8\ub378 3\uac00\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n<table style={{textAlign:\'center\'}}>\\n  <thead>\\n    <tr>\\n      <th width=\\"25%\\" rowSpan=\'2\'>Silo Model</th>\\n      <th width=\\"50%\\" colSpan=\'2\'>Bridge Model</th>\\n      <th width=\\"25%\\" rowSpan=\'2\'>Pool Model</th>\\n    </tr>\\n    <tr>\\n      <th width=\\"25%\\">Database</th>\\n      <th width=\\"25%\\">Schema</th>\\n    </tr>\\n  </thead>\\n<tbody>\\n <tr>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-silo.png\\"\\n        alt=\\"saas-postgresql-silo\\"\\n      />\\n    </td>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-bridge-dbs.png\\"\\n        alt=\\"saas-postgresql-bridge-dbs\\"\\n      />\\n    </td>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-bridge-schemas.png\\"\\n        alt=\\"saas-postgresql-bridge-schemas\\"\\n      />\\n    </td>\\n    <td>\\n      <img\\n        src=\\"/assets/blog/saas-postgresql-pool.png\\"\\n        alt=\\"saas-postgresql-pool\\"\\n      />\\n    </td>\\n </tr>\\n </tbody>\\n</table>\\n\\n### Silo Model (\uc0ac\uc77c\ub85c \ubaa8\ub378)\\n\\n\uc0ac\uc77c\ub85c \ubaa8\ub378\uc740 \uac01 \ud14c\ub10c\ud2b8\uc5d0 \ub300\ud574\\n<span style={{ backgroundColor: \'#fff5b1\'}}><b>\ubcc4\ub3c4\uc758 DB Instance</b></span> \ub97c \ubd80\uc5ec\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n<span style={{ textDecoration: \'underline\'}}>\ubb3c\ub9ac\uc801/\ub17c\ub9ac\uc801\uc73c\ub85c \ud14c\ub10c\ud2b8 \uac04\uc758 \uc11c\ub85c \uc0c1\uad00 \uad00\uacc4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</span>\\n\ubcf4\uc548 \ubb38\uc81c\ub098 \uaddc\uc81c\ub85c \uc778\ud574 \uace0\uac1d\uc774 \ucd94\uac00 \ube44\uc6a9\uc744 \uc9c0\ubd88\ud558\uace0 \ub370\uc774\ud130\uc758 \uc644\uc804 \ubd84\ub9ac\ub97c \uc6d0\ud558\ub294 \uacbd\uc6b0 \uc81c\uacf5\ud560 \uc218 \uc788\ub294 \uc11c\ube44\uc2a4 \ud615\ud0dc\uc785\ub2c8\ub2e4.\\n\\n### Pool Model (\ud480 \ubaa8\ub378)\\n\\n\ud480 \ubaa8\ub378\uc740\\n<span style={{ backgroundColor: \'#fff5b1\'}}><b>\ub2e8\uc77c DB Instance, \ud589 \uc218\uc900 \ubcf4\uc548(RTS)</b></span>\\n\ub97c \uc0ac\uc6a9\ud558\uc5ec \uad6c\ud604\ub429\ub2c8\ub2e4. `tenant_id` \ub610\ub294 `org_id` \uc640 \uac19\uc740 Foreign Key\ub97c \ud1b5\ud574 \ud14c\ub10c\ud2b8 \ub370\uc774\ud130\uc758 \uaca9\ub9ac\ub97c \uc720\uc9c0\ud569\ub2c8\ub2e4. \uc0ac\uc77c\ub85c \ubaa8\ub378\uc5d0 \ube44\ud574 \uc6b4\uc601 \uc624\ubc84\ud5e4\ub4dc\uac00 \ub354 \uc801\uc740 \uc7a5\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ud14c\ub10c\ud2b8\ubcc4 \ub9ac\uc18c\uc2a4 \uad00\ub9ac(\ubd84\ub9ac) \ubc0f \ubd84\uc11d\uc774 \uc5b4\ub835\ub2e4\ub294 \ub2e8\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### Bridge Model (\ube0c\ub9bf\uc9c0 \ubaa8\ub378)\\n\\n\ube0c\ub9bf\uc9c0 \ubaa8\ub378\uc740 \uc0ac\uc77c\ub85c \ubaa8\ub378\uacfc \ud480 \ubaa8\ub378\uc744 \uc870\ud569\ud55c \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ub2e8\uc77c DB Instance \ub0b4\ubd80\uc5d0\uc11c\\n<span style={{ textDecoration: \'underline\'}}>\ub17c\ub9ac\uc801 Database \ubd84\ud560</span>\\n\ub610\ub294\\n<span style={{ textDecoration: \'underline\'}}>\ud14c\ub10c\ud2b8\ubcc4\ub85c Schema \uc0dd\uc131 \ubc0f \uad00\ub9ac</span>\\n\ud569\ub2c8\ub2e4. \ud480 \ubaa8\ub378\uc758 \uacb0\ud569 \uc815\ub3c4\ub97c \ub04a\uc5b4\ub0b4\uace0, \ubb3c\ub9ac\uc801\uc73c\ub85c\ub294 \ub3d9\uc77c\ud55c DB Instance\ub97c \uc0ac\uc6a9\ud558\uae30\uc5d0 \uac01\uac01\uc758 \ub2e8\uc810\uc744 \ubcf4\uc644\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n<span style={{ backgroundColor: \'#f1f8ff\'}}>PostgreSQL\uc758 \uacbd\uc6b0 Database \uc640 Table \uc0ac\uc774 Schema \ub77c\ub294 \uc77c\uc885\uc758 \ub124\uc784\uc2a4\ud398\uc774\uc2a4\ub97c \uad6c\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</span>\\n\\n## \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \ube44\uad50\\n\\n<figure style={{ display:\'flex\', justifyContent: \'center\' }}>\\n| -                                   | Silo Model        | Pool Model       | Bridge Model                      |\\n| ----------------------------------- | ----------------- | ---------------- | --------------------------------- |\\n| \ud14c\ub10c\ud2b8 \uad6c\uc131 \uc2dc\uac04                    | \ud83d\udc0c\ub9e4\uc6b0 \ub290\ub9bc       | \u26a1\ufe0f\ub9e4\uc6b0 \ube60\ub984     | \ud83d\udc22 \ub290\ub9bc(\uc2a4\ud0a4\ub9c8 \uc0dd\uc131, \ud14c\uc774\ube14 \uc0dd\uc131) |\\n| \ub370\uc774\ud130 \uc720\ucd9c \uc704\ud5d8                    | \uc548\uc804(independent) | \uc704\ud5d8(tenant_id)  | \ub35c \uc704\ud5d8(query)                    |\\n| \uacf5\uc720\ud14c\uc774\ube14 \uc0dd\uc131, <br /> \ud14c\ub10c\ud2b8 \ubcd1\ud569 | SQL\ub85c \uc218\ud589 \ubd88\uac00   | \ub9e4\uc6b0 \uc26c\uc6c0        | SQL\ub85c \uc218\ud589 \uac00\ub2a5                   |\\n| DB \ub9c8\uc774\uadf8\ub808\uc774\uc158                     | \ud83d\udc0c\ub9e4\uc6b0 \ub290\ub9bc       | \u26a1\ufe0f\ub9e4\uc6b0 \ube60\ub984     | \ud83d\udc22 \ub290\ub9bc(\uc2a4\ud0a4\ub9c8 \uc0dd\uc131, \ud14c\uc774\ube14 \uc0dd\uc131) |\\n| \uc6b4\uc601 \uc624\ubc84\ud5e4\ub4dc                       | \uc218\uc791\uc5c5            | \uac70\uc758 \uc5c6\uc74c        | \uac00\ub054 \ubc1c\uc0dd                         |\\n| \ubcf5\uc7a1\uc131                              | ...               | tenent_id\ub85c \uad00\ub9ac | search_path \ubc0f PG \uae30\ub2a5\uc73c\ub85c \ucee4\ubc84   |\\n| \ud14c\ub10c\ud2b8\ubcc4 \ub370\uc774\ud130 \ucd94\ucd9c                | \uc26c\uc6c0              | \ubc88\uac70\ub85c\uc6b4 \uc791\uc5c5    | \uc26c\uc6c0                              |\\n| \ud14c\ub10c\ud2b8\ubcc4 \uad6c\uc870 \ucee4\uc2a4\ud130\ub9c8\uc774\uc9d5          | \uac00\ub2a5              | \ubb38\uc81c             | \uac00\ub2a5                              |\\n</figure>\\n\\n## \uc120\ud638\ud558\ub294 \uc804\ub7b5\\n\\nBackEnd \ub294 \uc5ed\ud560\ubcc4\ub85c (DBA) DB + SQL / (BE) DTO + DAO + Controller / (API) API \ub85c \uad6c\ubd84\ub429\ub2c8\ub2e4.\\n\\n\uc804\ud1b5\uc801\uc778 Role \uc911\uc2ec\uc758 \uad6c\uc870\uc640\ub294 \ub2ec\ub9ac \uc11c\ube44\uc2a4\uc758 \ud655\uc7a5\uc131, \ub2e4\uc591\uc131, \ubb34\uacb0\uc131\uc744 \ud0c0\ud611\ud560 \uc218 \uc788\ub2e4\uba74,\\n<span style={{ backgroundColor: \'#fff5b1\'}}>Schema\uac00 \ubd84\ub9ac\ub41c <b>\ube0c\ub9bf\uc9c0 \ubaa8\ub378</b></span>\uc744 ORM(SQLAlchemy, Prisma, TypeORM)\uc744 \ud1b5\ud574 \uad00\ub9ac\ud558\ub294 \ubc29\uc2dd\uc744 \uc120\ud638\ud558\ub294 \ud3b8\uc785\ub2c8\ub2e4.\\n\\n\uc774 \ubc29\uc2dd\uc740 ORM\uc744 \ud1b5\ud574 \uae30\ubcf8 Schema\ub97c \uc0dd\uc131\ud558\uace0 \ud14c\ub10c\ud2b8\uac00 \uc720\uc785\ub420 \uc2dc, \ud574\ub2f9 Schema\ub97c \ubcf5\uc81c\ud558\ub294 \ubc29\ubc95\uc73c\ub85c \ud14c\ub10c\ud2b8\ubcc4 \ub370\uc774\ud130\ub97c \uaca9\ub9ac\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \uc8fc\uc758\ud560 \uc810\uc73c\ub85c\ub294 SQL(Raw Query)\ub85c \uc9c1\uc811 Schema \ub97c \uad00\ub9ac\ud558\uac8c \ub418\uba74, Schema \ubcc4\ub85c \ub2e4\ub978 ERD \uad6c\uc131\uc774 \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub54c\ubb38\uc5d0 ORM\uc744 \ud1b5\ud574 \uae30\ubcf8 ERD \ub97c \uc218\uc815 \ubc0f \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ud558\ub294 \uc804\ub7b5\uc744 \uc120\ud638\ud569\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\uc790\ub8cc\\n\\n- https://docs.aws.amazon.com/prescriptive-guidance/latest/saas-multitenant-managed-postgresql"},{"id":"database-generate-erd","metadata":{"permalink":"/blog/database-generate-erd","source":"@site/blog/2023-11-12-database-generate-erd/index.md","title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","description":"ERD(\uc774\uc54c\ub514)\ub780 \\"Entity Relationship Diagram\\"\uc758 \uc57d\uc790\ub85c, \uac1c\uccb4-\uad00\uacc4 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc774\ub77c\uace0\ub3c4 \ud558\uba70 \ub9d0\ub85c \ub418\uc5b4 \uc788\ub294 \uc694\uad6c\uc0ac\ud56d\uc744 \ubd84\uc11d\ud558\uc5ec \uadf8\ub9bc\uc73c\ub85c \uadf8\ub824\ub0b4\uc5b4 \uadf8 \uad00\uacc4\ub97c \ub3c4\ucd9c\ud55c \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc744 \ub9d0\ud569\ub2c8\ub2e4.","date":"2023-11-12T00:00:00.000Z","tags":[{"inline":true,"label":"DB","permalink":"/blog/tags/db"}],"readingTime":0.63,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","slug":"database-generate-erd","authors":["kgenots"],"tags":["DB"],"image":"/assets/blog/unnamed-postgresql.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"PostgreSQL \uba40\ud2f0\ud14c\ub10c\uc2dc \uad6c\uc131 \uc804\ub7b5 (ft. SaaS \uad6c\uc131)","permalink":"/blog/postgresql-saas-multitenancy"},"nextItem":{"title":"Database \uc124\uacc4 \ubc29\ubc95","permalink":"/blog/database-design"}},"content":"ERD(\uc774\uc54c\ub514)\ub780 \\"Entity Relationship Diagram\\"\uc758 \uc57d\uc790\ub85c, \uac1c\uccb4-\uad00\uacc4 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc774\ub77c\uace0\ub3c4 \ud558\uba70 \ub9d0\ub85c \ub418\uc5b4 \uc788\ub294 \uc694\uad6c\uc0ac\ud56d\uc744 \ubd84\uc11d\ud558\uc5ec \uadf8\ub9bc\uc73c\ub85c \uadf8\ub824\ub0b4\uc5b4 \uadf8 \uad00\uacc4\ub97c \ub3c4\ucd9c\ud55c \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc744 \ub9d0\ud569\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n- \ucd9c\ucc98: http://wiki.hash.kr/index.php/ERD\\n\\n## ERD \uc0dd\uc131 \uc21c\uc11c\\n\\n1. DB \u2192 SQL \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n2. SQL \u2192 DBML \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n3. DBML \u2192 ERD \uc791\uc131\\n\\n## ERD \uc0dd\uc131 \ubc29\ubc95\\n\\n### 1. SQL \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n\\nDBML\uc740 SQLite3\uc758 \ubb38\ubc95\uc744 \ucc98\ub9ac\ud558\uc9c0 \ubabb\ud569\ub2c8\ub2e4. \ub54c\ubb38\uc5d0 MySQL \ubb38\ubc95\uc5d0 \ub9de\ucdb0 SQL \ud30c\uc77c\uc744 \uc791\uc131\ud569\ub2c8\ub2e4.\\n\\n- \ud30c\uc77c\uba85: `DATABASE.sql`\\n- \uc0d8\ud50c \ud30c\uc77c: mysql_sample.sql / [\ub2e4\uc6b4\ub85c\ub4dc](/assets/blog/mysql_sample.sql)\\n\\n### 2. DBML \ud30c\uc77c \uc0dd\uc131 (\ub364\ud504)\\n\\nDBML \ud30c\uc77c \uc9c1\uc811 \uc791\uc131\ud574\ub3c4 \ub418\uc9c0\ub9cc, \uc774\ubbf8 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uc2a4\ud0a4\ub9c8\uac00 \uc788\ub294 \uacbd\uc6b0 SQL \ud30c\uc77c\ub85c\ubd80\ud130 DBML \ud30c\uc77c\uc744 \ub364\ud504\ud558\ub294 \uac83\uc774 \ub0ab\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub97c \uc704\ud574\uc11c\ub294 DBML CLI\uac00 \ud544\uc694\ud55c\ub370, \uc774\ub97c \uc2e4\ud589\ud558\ub824\uba74 Node.js\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n- Node.js \uc124\uce58 (https://nodejs.org/ko/download/)\\n\\n  - Terminal, CMD \ucc3d\uc5d0\uc11c `npm`\uc744 \uc785\ub825\ud588\uc744 \ub54c, \uc544\ub798\uc640 \uac19\uc774 \ub098\uc628\ub2e4\uba74 Node.js \uac00 \uc124\uce58\ub418\uc5b4 \uc788\ub2e4\ub294 \uc758\ubbf8\uc785\ub2c8\ub2e4.\\n\\n  ![Nodejs](/assets/blog/node-npm.webp)\\n\\n- \uba85\ub839\uc5b4 \uc21c\uc11c\\n  - DBML CLI \uc124\uce58\\n    `npm install -g @dbml/cli`\\n  - DBML \ud30c\uc77c \uc0dd\uc131\\n    `sql2dbml DATABASE.sql -o DATABASE.dbml`\\n  - \uacb0\uacfc\ubb3c: `DATABASE.dbml`\\n\\n### 3. ERD \uc0dd\uc131\\n\\n[dbdiagram.io](https://dbdiagram.io/)\uc5d0\uc11c <b>Create your diagram</b>\ub97c \ud074\ub9ad\ud569\ub2c8\ub2e4.\\n\\n\uc67c\ucabd \ud3b8\uc9d1 \uacf5\uac04\uc5d0 DATABASE.dbml\uc758 \ub0b4\uc6a9\uc744 \ubd99\uc5ec\ub123\uc73c\uba74 \uc624\ub978\ucabd\uc5d0 \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc774 \uc790\ub3d9\uc73c\ub85c \uadf8\ub824\uc9d1\ub2c8\ub2e4.\\n\\n![ERD Sample](/assets/blog/erd.webp)"},{"id":"database-design","metadata":{"permalink":"/blog/database-design","source":"@site/blog/2023-11-11-database-design/index.md","title":"Database \uc124\uacc4 \ubc29\ubc95","description":"\uc81c\uc77c \uc911\uc694\ud55c\ub370 \ub2ec\ub2ec \uc678\uc6b4 \uc774\ub860\uc740 \uc798 \uc598\uae30\ud558\uba74\uc11c \uc124\uacc4\ud560 \ub54c \ubb54\uc9c0 \ubaa8\ub974\ub294 \uc0ac\ub78c \ub108\ubb34 \ub9ce\uc544\uc11c \uae30\ub85d","date":"2023-11-11T00:00:00.000Z","tags":[{"inline":true,"label":"DB","permalink":"/blog/tags/db"}],"readingTime":0.9,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Database \uc124\uacc4 \ubc29\ubc95","slug":"database-design","authors":["kgenots"],"tags":["DB"],"image":"/assets/blog/unnamed-postgresql.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"ERD \uc790\ub3d9 \uc0dd\uc131\ud558\ub294 \ubc29\ubc95 (ft. DB, SQLite)","permalink":"/blog/database-generate-erd"},"nextItem":{"title":"Coroutine \uc54c\uc544\ubcf4\uae30","permalink":"/blog/unity-coroutine"}},"content":"\uc81c\uc77c \uc911\uc694\ud55c\ub370 \ub2ec\ub2ec \uc678\uc6b4 \uc774\ub860\uc740 \uc798 \uc598\uae30\ud558\uba74\uc11c \uc124\uacc4\ud560 \ub54c \ubb54\uc9c0 \ubaa8\ub974\ub294 \uc0ac\ub78c \ub108\ubb34 \ub9ce\uc544\uc11c \uae30\ub85d\\n\\n\x3c!--truncate--\x3e\\n\\n### Transaction (\ud2b8\ub79c\uc7ad\uc158)\\n\\n\uc5ec\ub7ec \uac1c\uc758 \ud074\ub77c\uc774\uc5b8\ud2b8\uac00 \ub3d9\uc2dc\uc5d0 \uc561\uc138\uc2a4\ud55c\uac70\ub098, \ub370\uc774\ud130 \ucc98\ub9ac\uac00 \uc911\ub2e8\ub418\ub294 \uacbd\uc6b0 <b>\ub370\uc774\ud130 \ubd80\uc815\ud569</b>\uc744 \ubc29\uc9c0\\n\\n:::info \uae08\uc735 \uac70\ub798\uc5d0 \ube44\uad50\ud558\uae30\\n\\n- \uc1a1\uae08\ud560 \ub54c,\\n  - A \uacc4\uc88c \uc794\uc561\uc744 \ubd88\ub7ec\uc628\ub2e4.\\n  - B \uacc4\uc88c \uc794\uc561\uc744 \ubd88\ub7ec\uc628\ub2e4.\\n  - A \uacc4\uc88c\uc5d0\uc11c 1\ub9cc\uc6d0 \uc778\ucd9c\ud558\ub294 \uae30\ub85d\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n  - B \uacc4\uc88c\uc5d0\uc11c 1\ub9cc\uc6d0 \uc785\uae08\ud558\ub294 \uae30\ub85d\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n  - A \uacc4\uc88c \uc794\uc561\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n  - B \uacc4\uc88c \uc794\uc561\uc744 \uc800\uc7a5\ud55c\ub2e4.\\n\\n\uc989, 6\uac1c\uc758 \uba54\uc11c\ub4dc(\uae30\ub2a5)\ub97c \uac01\uac01 \ub9cc\ub4e4\ub354\ub77c\ub3c4, \ud2b8\ub79c\uc7ad\uc158\uc744 \uc5f4\uace0 \ub2eb\ub294 \uc0ac\uc774 6\uac1c\uc758 \uae30\ub2a5\uc774 \ubaa8\ub450 \ub3d9\uc791\ud574\uc57c\ud55c\ub2e4. <br/>\\n\ub610, C\ub77c\ub294 \ub2e4\ub978 \uace0\uac1d\uacfc B\uac00 \uac70\ub798\ub97c \ud558\ub354\ub77c\ub3c4 \uc704 A, B \uc0ac\uc774\uc758 \uac70\ub798\uc5d0\ub294 \ubb38\uc81c\uac00 \uc0dd\uae30\uc9c0 \uc54a\uc544\uc57c\ud55c\ub2e4.\\n:::\\n\\n### ACID \uc6d0\uce59\\n\\n- <b>Atomicity (\uc6d0\uc790\uc131)</b>: \uc911\uac04 \ub2e8\uacc4\uae4c\uc9c0 \uc2e4\ud589\ub418\uace0 \uc2e4\ud328\ud558\ub294 \uc77c\uc774 \uc5c6\uc5b4\uc57c \ud55c\ub2e4.\\n- <b>Consistency (\uc77c\uad00\uc131/\uc815\ud569\uc131)</b>: \ud2b8\ub79c\uc7ad\uc158 \uc804\ud6c4\uc758 \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uaddc\uce59\uc740 \uac19\uc544\uc57c\\n  \ud55c\ub2e4.\\n- <b>Isolation (\ub3c5\ub9bd\uc131)</b>: \ud2b8\ub79c\uc7ad\uc158\uc740 \uc11c\ub85c \ub3c5\ub9bd\uc801\uc774\uc5b4\uc57c \ud55c\ub2e4.\\n- <b>Duration (\uc9c0\uc18d\uc131)</b>: \ud2b8\ub79c\uc7ad\uc158\uc5d0 \ub300\ud55c \ub85c\uadf8\ub294 \uc601\uad6c\uc801\uc73c\ub85c \ub0a8\uc544\uc57c \ud55c\ub2e4.\\n\\n:::info \uae08\uc735 \uac70\ub798\uc5d0 \ube44\uad50\ud558\uae30\\n\\n- Atomicity: 1\ub9cc\uc6d0 \uc1a1\uae08 \uc2dc, \uc131\uacf5\ud558\uac70\ub098 \uc2e4\ud328\ub9cc \ub0a8\uc544\uc57c\ud568. (5\ucc9c\uc6d0\uc740 \uc131\uacf5\ud558\uace0, 5\ucc9c\uc6d0 \uc2e4\ud328\ud558\uace0 \uadf8\ub7f0\uac70 \uc5c6\uc74c)\\n- Consistency: 1\ub9cc\uc6d0 \uc1a1\uae08 \uc2dc, \uc1a1\uae08 \uc804 \ud6c4 \ub0b4 \uc2e0\uc0c1\uc774 \ubc14\ub00c\uc9c0\ub294 \uc54a\uc74c. (\uc1a1\uae08 \uc804 \ub0a8\uc790\uc600\ub294\ub370, \uc1a1\uae08 \ud6c4 \uc5ec\uc790\ub77c\uac70\ub098 \uadf8\ub7f0\uac70 \uc5c6\uc74c)\\n- Isolation: A\uc5d0\uac8c 1\ub9cc\uc6d0 \uc1a1\uae08, B\uc5d0\uac8c 1\ub9cc\uc6d0 \uc1a1\uae08\ud588\ub2e4\uace0 \ub458 \uc911 \ud558\ub098\uc5d0\uac8c \ub2e4\uc9dc\uace0\uc9dc 2\ub9cc\uc6d0 \uc92c\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub294 \ub178\ub987.\\n- Durability: \uc2dc\uc2a4\ud15c \uc624\ub958\ub4e0, \uc0ac\ub78c \uc624\ub958\ub4e0 1\ub9cc\uc6d0 \uc1a1\uae08 \uc644\ub8cc \uc2dc, \uae30\ub85d\uc774 \ub0a8\uc544\uc57c \ud568. \\"\ub09c \ubcf4\ub0c8\ub294\ub370\uc694\\" \ub77c\uace0 \ub9d0\ub85c\ub9cc \ud560 \uc218\ub294 \uc5c6\ub294 \ub178\ub987.\\n\\n:::\\n\\n### \ud2b8\ub79c\uc7ad\uc158 \uace0\ub9bd\uc131 \uc218\uc900(Isolation Level)\\n\\n- TODO.\\n\\n## Q&A\\n\\n- DB\uc5d0\uc11c Table \uc774\ub984\uc744 \ubcc0\uc218(Variable)\ub85c \uc0ac\uc6a9\ud574\ub3c4 \ub418\ub098\uc694?\\n  - \uc0ac\uc6a9\ud574\ub3c4 \ub418\uc9c0\ub9cc, <b>\uad8c\uc7a5\ub418\uc9c0 \uc54a\ub294 \ubc29\ubc95</b>\uc785\ub2c8\ub2e4.\\n  - <b> \ubcf4\uc548(SQL Injection \ucde8\uc57d), \uac00\ub3c5\uc131 \ubc0f \uc720\uc9c0\ubcf4\uc218, \ucd5c\uc801\ud654 \ub610\ub294 \uc131\ub2a5 </b> \ubb38\uc81c\uc640\\n    \uad00\ub828\uc774 \uc788\uc2b5\ub2c8\ub2e4."},{"id":"unity-coroutine","metadata":{"permalink":"/blog/unity-coroutine","source":"@site/blog/2023-11-10-unity-coroutine/index.md","title":"Coroutine \uc54c\uc544\ubcf4\uae30","description":"Unity \uac8c\uc784 \uac1c\ubc1c\uc5d0\uc11c Coroutine(\ucf54\ub8e8\ud2f4)\uc740 \uc8fc\uc694\ud55c \uac1c\ub150 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \uc774 \ubb38\uc11c\uc5d0\uc11c\ub294 Unity\uc5d0\uc11c\uc758 Coroutine\uc758 \uae30\ucd08\ubd80\ud130 \uc2ec\ud654 \ub0b4\uc6a9\uae4c\uc9c0 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ucf54\ub8e8\ud2f4\uc740 \uac8c\uc784\uc758 \uc131\ub2a5 \ud5a5\uc0c1, \uc560\ub2c8\uba54\uc774\uc158 \uc81c\uc5b4, \uc2dc\uac04 \uae30\ubc18 \uc791\uc5c5, \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc791\uc5c5 \ub4f1 \ub2e4\uc591\ud55c \uc0c1\ud669\uc5d0\uc11c \uc0ac\uc6a9\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","date":"2023-11-10T00:00:00.000Z","tags":[{"inline":true,"label":"Unity","permalink":"/blog/tags/unity"}],"readingTime":1.29,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Coroutine \uc54c\uc544\ubcf4\uae30","slug":"unity-coroutine","authors":["kgenots"],"tags":["Unity"],"image":"/assets/blog/unnamed-unity.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Database \uc124\uacc4 \ubc29\ubc95","permalink":"/blog/database-design"},"nextItem":{"title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","permalink":"/blog/markdown-text-color"}},"content":"Unity \uac8c\uc784 \uac1c\ubc1c\uc5d0\uc11c Coroutine(\ucf54\ub8e8\ud2f4)\uc740 \uc8fc\uc694\ud55c \uac1c\ub150 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \uc774 \ubb38\uc11c\uc5d0\uc11c\ub294 Unity\uc5d0\uc11c\uc758 Coroutine\uc758 \uae30\ucd08\ubd80\ud130 \uc2ec\ud654 \ub0b4\uc6a9\uae4c\uc9c0 \uc790\uc138\ud788 \uc0b4\ud3b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ucf54\ub8e8\ud2f4\uc740 \uac8c\uc784\uc758 \uc131\ub2a5 \ud5a5\uc0c1, \uc560\ub2c8\uba54\uc774\uc158 \uc81c\uc5b4, \uc2dc\uac04 \uae30\ubc18 \uc791\uc5c5, \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc791\uc5c5 \ub4f1 \ub2e4\uc591\ud55c \uc0c1\ud669\uc5d0\uc11c \uc0ac\uc6a9\ub420 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uc18c\uac1c\\n\\nCoroutine\uc740 Unity\uc758 MonoBehaviour \ud074\ub798\uc2a4\uc5d0\uc11c \uc0ac\uc6a9\ub418\uba70, \uac8c\uc784 \ub85c\uc9c1\uc744 \ube44\ub3d9\uae30\uc801\uc73c\ub85c \ucc98\ub9ac\ud560 \ub54c \ud2b9\ud788 \uc720\uc6a9\ud569\ub2c8\ub2e4. Coroutine\uc740 Update() \ud568\uc218\uc640\ub294 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc2e4\ud589\ub418\uba70, \uc8fc\ub85c \uc2dc\uac04 \uae30\ubc18 \uc791\uc5c5\uc5d0 \uc801\ud569\ud569\ub2c8\ub2e4.\\n\\n![Coroutine Flow](/assets/blog/coroutine.webp)\\n\\n## Coroutine\uacfc Thread\\n\\n.NET(\ub2f7\ub137)\uc740 Multi-thread\ub97c \uc9c0\uc6d0\ud558\uc9c0\ub9cc, .NET\uc744 \uc0ac\uc6a9\ud558\ub294 \uc720\ub2c8\ud2f0\ub294 **Single-thread**\ub85c \ub3d9\uc791\ud569\ub2c8\ub2e4.\\nSingle-thread \ud658\uacbd\uc5d0\uc11c \ub3d9\uc2dc\uc5d0 \uc5ec\ub7ec \ub3d9\uc791\uc744 \ud558\uae30 \uc704\ud574(\uba40\ud2f0\uc4f0\ub808\ub4dc\ub97c \ud749\ub0b4\ub0b4\uae30 \uc704\ud574), Unity\uc5d0\uc11c\ub294 **Coroutine**\uc744 \uc0ac\uc6a9\ud574\uc57c\ud569\ub2c8\ub2e4.\\n\\n## \uae30\ubcf8\uc801\uc778 \uc0ac\uc6a9\ubc95\\n\\nCoroutine \ub0b4\uc5d0\uc11c\ub294 `yield return` \ubb38\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc591\ubcf4\ud558\uace0 \uae30\ub2e4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uac00\uc7a5 \uc77c\ubc18\uc801\uc778 \uc0ac\uc6a9 \uc0ac\ub840 \uc911 \ud558\ub098\ub294 `yield return new WaitForSeconds(time)`\ub97c \uc0ac\uc6a9\ud558\uc5ec \ub300\uae30 \uc2dc\uac04\uc744 \uc9c0\uc815\ud558\ub294 \uac83\uc785\ub2c8\ub2e4.\\n\\n```csharp\\nIEnumerator Example() {\\n    Debug.Log(\\"Start Coroutine\\");\\n    yield return new WaitForSeconds(2.0f); // 2\ucd08 \ub300\uae30\\n    Debug.Log(\\"Coroutine Resumed after 2 seconds\\");\\n}\\n```\\n\\n## Coroutine \uc2dc\uc791 (StartCoroutine)\\n\\nUnity\uc5d0\uc11c Coroutine\uc744 \uc2dc\uc791\ud558\ub294 \ubc29\ubc95\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n```csharp\\nvoid Start() {\\n    StartCoroutine(MyCoroutine());\\n}\\n\\nIEnumerator MyCoroutine() {\\n    // \ucf54\ub8e8\ud2f4 \ub0b4\uc6a9\\n    yield return null;\\n}\\n```\\n\\n## Coroutine \uc911\ub2e8 (StopCoroutine)\\n\\nCoroutine\uc744 \uc911\ub2e8\ud558\ub294 \ubc29\ubc95\uc5d0\ub294 \uc138 \uac00\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n1. `StopCoroutine(IEnumerator routine)`: \ud2b9\uc815 Coroutine\uc744 \uc911\ub2e8\ud569\ub2c8\ub2e4.\\n\\n```csharp\\nvoid StopExample() {\\n    StopCoroutine(MyCoroutine());\\n}\\n```\\n\\n2. `StopCoroutine(string methodName)`: Coroutine \ud568\uc218 \uc774\ub984\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc911\ub2e8\ud569\ub2c8\ub2e4.\\n\\n```csharp\\nvoid StopExample() {\\n    StopCoroutine(\\"MyCoroutine\\");\\n}\\n```\\n\\n3. `StopAllCoroutines()`: \ud604\uc7ac \ud074\ub798\uc2a4\uc5d0\uc11c \uc2e4\ud589 \uc911\uc778 \ubaa8\ub4e0 Coroutine\uc744 \uc911\ub2e8\ud569\ub2c8\ub2e4.\\n\\n```csharp\\nvoid StopAllExample() {\\n    StopAllCoroutines();\\n}\\n```\\n\\n## Coroutine \uc911\ucca9 (Nested Coroutine)\\n\\nCoroutine \ub0b4\uc5d0\uc11c \ub2e4\ub978 Coroutine\uc744 \uc2dc\uc791\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub807\uac8c \ud558\uba74 \uc791\uc5c5\uc744 \uc870\uc9c1\ud654\ud558\uace0 \uc758\uc874\uc131\uc744 \ucc98\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```csharp\\nIEnumerator TestRoutine() {\\n    Debug.Log(\\"Start TestRoutine\\");\\n    yield return StartCoroutine(OtherRoutine());\\n    Debug.Log(\\"Finish TestRoutine\\");\\n}\\n\\nIEnumerator OtherRoutine() {\\n    Debug.Log(\\"Start OtherRoutine #1\\");\\n    yield return new WaitForSeconds(1.0f);\\n    Debug.Log(\\"Start OtherRoutine #2\\");\\n    yield return new WaitForSeconds(1.0f);\\n    Debug.Log(\\"Start OtherRoutine #3\\");\\n    yield return new WaitForSec\'onds(1.0f);\\n    Debug.Log(\\"Finish OtherRoutine\\");\\n}\\n```\\n\\n## \uc694\uc57d \ubc0f \ud301\\n\\n1. **Coroutine**\uc740 Unity MonoBehaivour\uc758 LifeCycle\uacfc \ubcc4\uac1c\ub85c **\uba40\ud2f0\uc4f0\ub808\ub4dc\ub97c \ud749\ub0b4**\ub0b4\uae30 \uc704\ud574 \uc0ac\uc6a9\ud558\ub294 IEnumerator\ub97c \ubc18\ud658\ud558\ub294 \ud568\uc218\uc785\ub2c8\ub2e4.\\n2. **Coroutine**\uc740 StartCoroutine\uc744 \ud638\ucd9c\ud558\ub294 **MonoBehaviour\uc5d0 \uc885\uc18d**\ub418\uc5b4\uc788\uc5b4 \ud574\ub2f9 MonoBehaviour \ube44\ud65c\uc131\ud654\uc2dc \uac19\uc774 \ube44\ud65c\uc131\ud654\ub429\ub2c8\ub2e4.\\n\\n## \ub9c8\ubb34\ub9ac\\n\\nCoroutine\uc740 \uc4f0\ub2e4 \ubcf4\uba74 \\"\uc774\uac8c \uc65c \uba48\ucdc4\uc9c0\\"\ub85c \ud55c \ubc88\uc740 \uc2dc\uac04\uc744 \uc501\ub2c8\ub2e4. \ub300\uac1c \uc6d0\uc778\uc740 \ucf54\ub8e8\ud2f4 \uc790\uccb4\uac00 \uc544\ub2c8\ub77c \uadf8\uac83\uc744 \uc2dc\uc791\ud55c MonoBehaviour\uac00 \uaebc\uc9c4 \ucabd\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc624\ube0c\uc81d\ud2b8 \uc218\uba85\uacfc \ud568\uaed8 \ubcf8\ub2e4\ub294 \uac83\ub9cc \uae30\uc5b5\ud574 \ub450\uba74 \ub098\uba38\uc9c0\ub294 \uc5b4\ub835\uc9c0 \uc54a\uc740 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n## \ucc38\uace0 \uc790\ub8cc\\n\\n- [Unity \uacf5\uc2dd \ubb38\uc11c - Coroutine](http://docs.unity3d.com/kr/current/Manual/Coroutines.html)\\n  - [MonoBehaviour.StartCoroutine](http://docs.unity3d.com/ScriptReference/MonoBehaviour.StartCoroutine.html)\\n  - [MonoBehaviour.StopCoroutine](http://docs.unity3d.com/ScriptReference/MonoBehaviour.StopCoroutine.html)"},{"id":"markdown-text-color","metadata":{"permalink":"/blog/markdown-text-color","source":"@site/blog/2023-11-09-markdown-text/index.md","title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","description":"\ub9c8\ud06c\ub2e4\uc6b4 \ubb38\uc11c\uc5d0\uc11c \uae00\uc790 \ud06c\uae30 \ubc0f \uc0c9\uc0c1\uc744 \uc870\uc808\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.","date":"2023-11-09T00:00:00.000Z","tags":[{"inline":true,"label":"Markdown","permalink":"/blog/tags/markdown"}],"readingTime":0.82,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","slug":"markdown-text-color","authors":["kgenots"],"tags":["Markdown"],"image":"/assets/blog/unnamed-markdown.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Coroutine \uc54c\uc544\ubcf4\uae30","permalink":"/blog/unity-coroutine"},"nextItem":{"title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","permalink":"/blog/blog-renewal"}},"content":"\ub9c8\ud06c\ub2e4\uc6b4 \ubb38\uc11c\uc5d0\uc11c \uae00\uc790 \ud06c\uae30 \ubc0f \uc0c9\uc0c1\uc744 \uc870\uc808\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574\uc11c \uc54c\uc544\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \uae00\uc790 \ud06c\uae30 \ubc0f \uc18d\uc131\\n\\n### \uc81c\ubaa9\\n\\n| **\uc608\uc2dc**      | **\ucf54\ub4dc**    |\\n| ------------- | ----------- |\\n| <h1> H1 </h1> | `# H1`      |\\n| <h2> H2 </h2> | `## H2`     |\\n| <h3> H3 </h3> | `### H3`    |\\n| <h4> H4 </h4> | `#### H4`   |\\n| <h5> H5 </h5> | `##### H5`  |\\n| <h6> H6 </h6> | `###### H6` |\\n\\n### \uac15\uc870\\n\\n\uc774\ud0e4\ub9ad\uccb4 (\uae30\uc6b8\uc5ec\uc4f0\uae30) : _Italic_ <br />\\n\ubcfc\ub4dc\uccb4 (\uad75\uac8c\uc4f0\uae30) : **Bold**\\n\\n```\\n*Italic*\\n**Bold**\\n```\\n\\n### \uc778\uc6a9\ubb38\\n\\n> \uc778\uc6a9\ubb38\\n\\n```\\n>\uc778\uc6a9\ubb38\\n```\\n\\n### \ucf54\ub4dc\\n\\n#### \ucf54\ub4dc (\uc778\ub77c\uc778)\\n\\n`Inline Code Block`\\n\\n```\\n`Inline Code Block`\\n```\\n\\n#### \ucf54\ub4dc (\ube14\ub7ed / \uba40\ud2f0\ub77c\uc778)\\n\\n```\\nCode\\nBlock\\n```\\n\\n````\\n```\\nCode\\nBlock\\n```\\n````\\n\\n### \uac01\uc8fc\\n\\n\uac01\uc8fc[^1]\\n[^1]: \uac01\uc8fc\uc5d0 \ub300\ud55c \uc124\uba85\\n\\n```\\n\uac01\uc8fc[^1]\\n[^1]: \uac01\uc8fc\uc5d0 \ub300\ud55c \uc124\uba85\\n```\\n\\n## \uae00\uc790 \uc0c9\uc0c1\\n\\n- <span style={{ color: \'#FF0000\' }}>\\n  \ube68\uac15\\n  </span>\\n\\n- <span style={{ color: \'#0000FF\' }}>\\n  \ud30c\ub791\\n  </span>\\n\\n- <span style={{ color: \'#008000\' }}>\\n  \ucd08\ub85d\\n  </span>\\n\\n- <span style={{ color: \'#808080\' }}>\\n  \uadf8\ub808\uc774\\n  </span>\\n\\n- <span style={{ color: \'#ffd33d\' }}>\\n  \ub178\ub791\\n  </span>\\n\\n```html\\n<span style=\\"color: #FF0000\\">\ube68\uac15</span>\\n<span style=\\"color: #0000FF\\">\ud30c\ub791</span>\\n<span style=\\"color: #008000\\">\ucd08\ub85d</span>\\n<span style=\\"color: #808080\\">\ud68c\uc0c9</span>\\n<span style=\\"color: #ffd33d\\">\ub178\ub791</span>\\n```\\n\\n## \uae00\uc790 \ud615\uad11\ud39c(\ubc30\uacbd\uc0c9)\\n\\n- <span style={{ backgroundColor: \'#fff5b1\'}}>\\n  \ub178\ub780\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#f6f8fa\'}}>\\n  \ud68c\uc0c9\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#f1f8ff\'}}>\\n  \ud30c\ub791\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#ffdce0\'}}>\\n  \ube68\uac15\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#dcffe4\'}}>\\n  \ucd08\ub85d\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#f5f0ff\'}}>\\n  \ubcf4\ub77c\ud615\uad11\ud39c\\n  </span>\\n\\n- <span style={{ backgroundColor: \'#F7DDBE\'}}>\\n  \uc8fc\ud669\ud615\uad11\ud39c\\n  </span>\\n\\n```html\\n<span style=\\"background-color: #fff5b1\\">\ub178\ub780\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #f6f8fa\\">\ud68c\uc0c9\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #f1f8ff\\">\ud30c\ub791\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #ffdce0\\">\ube68\uac15\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #dcffe4\\">\ucd08\ub85d\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #f5f0ff\\">\ubcf4\ub77c\ud615\uad11\ud39c</span>\\n<span style=\\"background-color: #F7DDBE\\">\uc8fc\ud669\ud615\uad11\ud39c</span>\\n```\\n\\n[^1]: \uac01\uc8fc\uc5d0 \ub300\ud55c \uc124\uba85."},{"id":"blog-renewal","metadata":{"permalink":"/blog/blog-renewal","source":"@site/blog/2023-08-29-blog-renewal/index.md","title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","description":"\uc7ac\ud14c\ud06c, \ubd80\ub3d9\uc0b0, \uac74\uac15 \ub4f1 \uc5ec\ub7ec \ube14\ub85c\uadf8\ub97c \uc6b4\uc601\ud558\uace0 \uc788\uc9c0\ub9cc, \uac00\uc7a5 \uc6b4\uc601\uc5d0 \uace0\ubbfc\uc774 \ub418\ub294 \ube14\ub85c\uadf8\ub294 \ud56d\uc0c1 \uac1c\ubc1c \ube14\ub85c\uadf8\uc778\uac83 \uac19\uc2b5\ub2c8\ub2e4.","date":"2023-08-29T00:00:00.000Z","tags":[{"inline":true,"label":"Essay","permalink":"/blog/tags/essay"}],"readingTime":0.76,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","slug":"blog-renewal","authors":["kgenots"],"tags":["Essay"],"image":"/assets/blog/2023-08-29-blog-history1.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Markdown \uae00\uc790 \ud06c\uae30, \uc0c9\uc0c1, \ud615\uad11\ud39c \uc124\uc815 \ubc29\ubc95","permalink":"/blog/markdown-text-color"},"nextItem":{"title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","permalink":"/blog/vscode-extensions"}},"content":"\uc7ac\ud14c\ud06c, \ubd80\ub3d9\uc0b0, \uac74\uac15 \ub4f1 \uc5ec\ub7ec \ube14\ub85c\uadf8\ub97c \uc6b4\uc601\ud558\uace0 \uc788\uc9c0\ub9cc, \uac00\uc7a5 \uc6b4\uc601\uc5d0 \uace0\ubbfc\uc774 \ub418\ub294 \ube14\ub85c\uadf8\ub294 \ud56d\uc0c1 \uac1c\ubc1c \ube14\ub85c\uadf8\uc778\uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n## \ube14\ub85c\uadf8 \ub9ac\ub274\uc5bc\\n\\n\ub2e4\ub978 \uc8fc\uc81c\uc758 \ube14\ub85c\uadf8\uc758 \uacbd\uc6b0, \uc815\ubcf4\uc131 \uae00\ub9cc \uc62c\ub9ac\ub2e4\ubcf4\ub2c8 \uc815\ud655\ub3c4\ub9cc \uc2e0\uacbd \uc4f0\uba74 \ub418\ub294 \ud3b8\uc785\ub2c8\ub2e4. \ubc18\uba74\uc5d0 \uac1c\ubc1c \ube14\ub85c\uadf8\ub294 \ud56d\uc0c1 \uafb8\uc900\ud788 \ub0b4\uac00 \ud559\uc2b5\ud558\uace0 \uacbd\ud5d8\ud574 \ubcf8 \uc9c0\uc2dd\ub4e4\uc744 \uc801\uc5b4\uc57c\ud558\ub294 \ubd80\ub2f4\uac10\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc815\ud655\ub3c4\ub97c \uc2e0\uacbd \uc4f0\ub294\ub9cc\ud07c \uafb8\uc900\ud788 \uac1c\ubc1c\ud558\uace0 \uadf8 \uc77c\ub4e4\uc744 \uae30\ub85d\ud558\ub294 \uc77c\ub4e4\uc774 \uadf8\ub9cc\ud07c \uc27d\uc9c0 \uc54a\ub2e4\ub294 \uac83\uc774\uc9c0\uc694.\\n\\n### \ube14\ub85c\uadf8... \uc600\ub358 \uac83\\n\\nGithub Blog, Tistory, Velog \uc774\uacf3\uc800\uacf3 \ub5a0\ub3cc\uc544\ub2e4\ub2c8\uba74\uc11c \ud3ec\uc2a4\ud305\uc744 \ud588\uc73c\ub098, \uc5b4\ub514 \ud558\ub098 \uc790\ub9ac\uc7a1\uace0 \uafb8\uc900\ud788 \uc801\uc9c0 \ubabb\ud558\uace0 \ub9cc\ub4e4\uace0 \uc9c0\uc6b0\uace0\ub97c \ubc18\ubcf5\ud588\ub358 \ud754\uc801\uc774 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/2023-08-29-blog-history1.webp\\"\\n    alt=\\"tistory-blog\\"\\n  />\\n  <figcaption>Tistory \ube14\ub85c\uadf8</figcaption>\\n</figure>\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/2023-08-29-blog-history2.webp\\"\\n    alt=\\"github-blog\\"\\n  />\\n  <figcaption>Github \ube14\ub85c\uadf8...\uc600\ub358 \uac83</figcaption>\\n</figure>\\n\\n## Github Pages \uc7ac\uac1c\ubc1c\\n\\n\uc77c\uc804\uc5d0 [Jekyll](https://jekyllrb-ko.github.io/), [Gatsby](https://www.gatsbyjs.com/) \ub4f1\ub4f1 \uc5ec\ub7ec \uc2dc\ub3c4\ub97c \ud574\ubcf4\uc558\uc73c\ub098, \ub514\uc790\uc778\ub9cc \uace0\ub974\ub2e4\uac00 \uacb0\uad6d \ud3ec\uae30\ud558\uae30\ub97c \uc218\ub3c4 \uc5c6\uc774 \ubc18\ubcf5\ud588\ub358 \uac83 \uac19\uc2b5\ub2c8\ub2e4 .\\n\\n[Docusaurus](https://docusaurus.io/) \ub77c\ub294 **Meta**\uc758 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc0dd\uae34 \uac83\uc744 \ud655\uc778\ud558\uace0 [Dyte Docs](https://docs.dyte.io/)\uc758 \ud15c\ud50c\ub9bf\uc744 \uc0ac\uc6a9\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.\\n\\nDocusaurus\ub294 \uac1c\ubc1c \ubb38\uc11c\uc640 \ube14\ub85c\uadf8\ub97c \uac19\uc774 \uc798 \uad00\ub9ac\ud560 \uc218 \uc788\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778 \uac83 \uac19\uc2b5\ub2c8\ub2e4. \uc774\uc655 \ub9c8\uc74c\uba39\uace0 \ub2e4\uc2dc \uc2dc\uc791\ud55c \uae40\uc5d0 **\ud504\ub85c\ud544, \ud3ec\ud2b8\ud3f4\ub9ac\uc624, \uc774\ub825\uc11c, \ube14\ub85c\uadf8**\ub97c \ud55c\uaebc\ubc88\uc5d0 \ud1b5\ud569\ud574\uc57c\uaca0\ub2e4\ub294 \uc0dd\uac01\uc73c\ub85c \ub2e4\uc2dc \ub9cc\ub4e4\uace0 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\ube14\ub85c\uadf8\uc758 \ud575\uc2ec\uc740 \uc5ed\uc2dc\ub098 \uae00\uc778\uc9c0\ub77c \uafb8\uc900\ud568\uc774 \ub610 \ud544\uc694\ud558\uaca0\uc9c0\uc694 \u3160\u3160\\n\\n## \ub9c8\ubb34\ub9ac\\n\\n\uc544\uc9c1 \uae00 \uc19c\uc528\uac00 \uc88b\uc9c0\ub294 \ubabb\ud574\uc11c \ub9d0\ud22c\ub098 \ubb38\uc7a5\uc744 \uc801\ub294 \uc2b5\uad00\uc774 \uc88b\uc9c4 \uc54a\uc740 \uac83 \uac19\uc9c0\ub9cc, \uc774\uc655 \uac1c\uc778 \ubb38\uc11c\ub97c \ub2e4 \ubaa8\uc544 \ub193\ub294\ub2e4\uace0 \uc0dd\uac01\ud558\uace0 \uafb8\uc900\ud788 \ud574\ubd10\uc57c\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\uc0c1 ~~"},{"id":"vscode-extensions","metadata":{"permalink":"/blog/vscode-extensions","source":"@site/blog/2022-11-25-vscode-extensions/index.md","title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","description":"VSCode\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc720\uc6a9\ud55c \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c \ud3ec\uc2a4\ud2b8\uc785\ub2c8\ub2e4.","date":"2022-11-25T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":2.38,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","slug":"vscode-extensions","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/vscode-extensions.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ube14\ub85c\uadf8 \uc0c8\ub85c \uc2dc\uc791\ud558\uae30","permalink":"/blog/blog-renewal"},"nextItem":{"title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","permalink":"/blog/mac-dock-speed-up"}},"content":"VSCode\uc5d0\uc11c \uc0ac\uc6a9\ub418\ub294 \uc720\uc6a9\ud55c \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c \ud3ec\uc2a4\ud2b8\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n\ub9ce\uc740 \ud68c\uc0ac\uc5d0\uc11c \uc720\ub8cc IDE\ub97c \uc4f0\uac70\ub098 \ubb34\uac70\uc6b4 Visual Studio\ub97c \uc4f0\ub294 \uac83\uacfc \ubcc4\uac1c\ub85c \ud544\uc790\ub294 \uac1c\uc778\uc801\uc73c\ub85c VSCode \uc774\uc6a9\uc744 \ucd94\ucc9c\ud569\ub2c8\ub2e4. \uae30\ubcf8 \ud504\ub85c\uadf8\ub7a8 \uc790\uccb4\uac00 \uac00\ubcbc\uc6b4 \uce21\uba74\ub3c4 \uc788\uad6c, \ud544\uc694\ud55c \ud234\uc744 \ud655\uc7a5(Extension) \ud504\ub85c\uadf8\ub7a8\ub9cc \uc124\uce58\ud574\uc8fc\uba74 \ub418\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4.\\n\\n\uadf8 \uc911 \uc81c\uac00 \uc4f0\uba74\uc11c \ucd94\ucc9c\ud558\ub294 \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8 \uba87 \uac1c\ub97c \ub4e4\uace0\uc640 \ubd24\uc2b5\ub2c8\ub2e4.\\n\\n## 1. GitLens\\n\\n[https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens](https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://eamodio.gallerycdn.vsassets.io/extensions/eamodio/gitlens/2023.12.1104/1702285683062/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              GitLens \u2014 Git supercharged - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Supercharge Git within VS Code \u2014 Visualize code authorship at a glance via Git blame annotations and CodeLens, seamlessly navigate and explore Git repositories, gain valuable insights via rich visualizations and powerful comparison commands, and so much more\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nGitLens\ub294 Git\uc774 \uc138\ud305\ub418\uc5b4 \uc788\ub294 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc904(Line)\uc5d0 \ucee4\uc11c\ub97c \uc62c\ub9ac\uba74 \uc5b8\uc81c \ub204\uac00 \uc218\uc815\ud588\ub294\uc9c0\ub97c \uace7\ubc14\ub85c \uc54c\uac8c\ud574\uc8fc\ub294 \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8\uc785\ub2c8\ub2e4. \ud574\ub2f9 \uc791\uc5c5\uc774 \uc77c\uc5b4\ub09c \ucee4\ubc0b\uc758 \ud788\uc2a4\ud1a0\ub9ac\ub97c \ucd94\uc801\ud574\uc57c\ud558\ub294 \uacbd\uc6b0\uc5d0 \uc720\uc6a9\ud55c \ud234\uc785\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/vscode-gitlens.webp\\"\\n    alt=\\"vscode-gitlens\\"\\n  />\\n  <figcaption>GitLens \uc801\uc6a9 \uc608\uc2dc</figcaption>\\n</figure>\\n\\n## 2. indent-rainbow\\n\\n[https://marketplace.visualstudio.com/items?itemName=oderwat.indent-rainbow](https://marketplace.visualstudio.com/items?itemName=oderwat.indent-rainbow)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=oderwat.indent-rainbow\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://oderwat.gallerycdn.vsassets.io/extensions/oderwat/indent-rainbow/8.3.1/1649543509070/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              indent-rainbow - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Makes indentation easier to read\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nindent-rainbow\ub294 \ub4e4\uc5ec\uc4f0\uae30\uc758 \ub2e8\uacc4\ub9c8\ub2e4 \ub2e4\ub978 \uc0c9\uc0c1\uc73c\ub85c \ud45c\ud604\ud574\uc8fc\ub294 \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8 \uc785\ub2c8\ub2e4. \uae30\ubcf8 \uc0c9\uc0c1\uc740 \uc21c\uc11c\ub300\ub85c \ub178\ub791, \ucd08\ub85d, \ubcf4\ub77c, \ud30c\ub791 \uc21c\uc11c\ub300\ub85c\uc9c0\ub9cc, \ubcc4\ub3c4\ub85c \ucee4\uc2a4\ud130\ub9c8\uc774\uc9d5\uc774 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\npython \uacfc \uac19\uc774 indent(\ub4e4\uc5ec\uc4f0\uae30)\uc758 \uce78\uc218\uac00 \ub9de\uc9c0 \uc54a\uc544\uc11c \uc624\ub958\uac00 \ub098\ub294 \uacbd\uc6b0\uc5d0\ub294 \ube68\uac04\uc0c9\uc73c\ub85c \ud45c\uc2dc\uac00 \ub429\ub2c8\ub2e4. indent-rainbow\uc73c\ub85c \ub4e4\uc5ec\uc4f0\uae30 \uac04\uaca9\uc774 \ub9de\ub294\uc9c0 \uc77c\uc77c\uc774 \uccb4\ud06c\ud574\uc57c\ud558\ub294 \uc218\uace0\ub85c\uc6c0\uc744 \ub35c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/vscode-indent-rainbow.webp\\"\\n    alt=\\"vscode-indent-rainbow\\"\\n  />\\n  <figcaption>indent-rainbow \uc801\uc6a9 \uc608\uc2dc</figcaption>\\n</figure>\\n\\n## 3. Material Icon Theme\\n\\n[https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme](https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=PKief.material-icon-theme\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://pkief.gallerycdn.vsassets.io/extensions/pkief/material-icon-theme/4.32.0/1700479629849/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              Material Icon Theme - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Material Design Icons for Visual Studio Code\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nMaterial Icon Theme\ub294 \ud30c\uc77c\uc758 \ud655\uc7a5\uc790 \ubc0f \uc774\ub984\uc5d0 \ub530\ub77c \ud3f4\ub354 \ubc0f \ud30c\uc77c\uc758 \uc544\uc774\ucf58\uc744 \ubcf4\uae30 \uc26c\uc6b4 \uc544\uc774\ucf58\uc73c\ub85c \ubcc0\uacbd\ud574\uc90d\ub2c8\ub2e4.\\n\\n\uc720\uc0ac \ud655\uc7a5 \ud504\ub85c\uadf8\ub7a8\uc73c\ub85c [vscode-icons](https://marketplace.visualstudio.com/items?itemName=vscode-icons-team.vscode-icons) \uac00 \uc788\uc2b5\ub2c8\ub2e4. \uae00 \uc791\uc131\uc77c \uae30\uc900\uc73c\ub85c \ub2e4\uc6b4\ub85c\ub4dc \uc218\uac00 \uac01\uac01 Material Icons Theme(15\ubc31\ub9cc), vscode-icons(12.5\ubc31\ub9cc)\uc73c\ub85c \ucde8\ud5a5 \ucc28\uc774 \uc815\ub3c4\ub85c \uc0dd\uac01\ud558\uace0 \uc88b\uc544\ud558\ub294 \uac78 \uc4f0\uba74 \ub420 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<table>\\n<thead>\\n    <tr>\\n      <th width=\\"50%\\">\uc801\uc6a9 \uc804</th>\\n      <th width=\\"50%\\">\uc801\uc6a9 \ud6c4</th>\\n    </tr>\\n  </thead>\\n<tbody>\\n <tr>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/vscode-material-icon-before.webp\\"\\n          alt=\\"vscode-material-icon-before\\"\\n        />\\n    </td>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/vscode-material-icon-after.webp\\"\\n          alt=\\"vscode-material-icon-after\\"\\n        />\\n    </td>\\n </tr>\\n </tbody>\\n</table>\\n\\n## 4. Color Highlight\\n\\n[https://marketplace.visualstudio.com/items?itemName=naumovs.color-highlight](https://marketplace.visualstudio.com/items?itemName=naumovs.color-highlight)\\n\\n<div class=\\"link-preview-container\\">\\n    <a \\n      href=\\"https://marketplace.visualstudio.com/items?itemName=naumovs.color-highlight\\">\\n    </a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img \\n              src=\\"https://naumovs.gallerycdn.vsassets.io/extensions/naumovs/color-highlight/2.5.0/1631530639439/Microsoft.VisualStudio.Services.Icons.Default\\"\\n              alt=\\"Article Thumbnail\\" \\n            />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">\\n              Color Highlight - Visual Studio Marketplace\\n            </div>\\n            <div class=\\"link-preview-description\\">\\n              Extension for Visual Studio Code - Highlight web colors in your editor\\n            </div>\\n        </div>\\n    </div>\\n</div>\\n\\nColor Highlight \ub294 \uc785\ub825\ub41c \uc0c9\uc0c1(rgb, hex \ub4f1)\uc744 \ubc14\ub85c \ud574\ub2f9 \ud14d\uc2a4\ud2b8\uc5d0 \uc0c9\uc0c1\uc73c\ub85c \ud45c\uc2dc\ud574\uc90d\ub2c8\ub2e4.\\n\\n**\uc0ac\uc6a9\uc608\uc2dc:**\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/vscode-color-highlight.webp\\"\\n    alt=\\"vscode-color-highlight\\"\\n  />\\n  <figcaption>indent-rainbow \uc801\uc6a9 \uc608\uc2dc</figcaption>\\n</figure>"},{"id":"mac-dock-speed-up","metadata":{"permalink":"/blog/mac-dock-speed-up","source":"@site/blog/2022-11-23-mac-dock-speed-up/index.md","title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","description":"MacOS \ub0b4 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ub354 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-11-23T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.5,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","slug":"mac-dock-speed-up","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/mac-dock-speed-up.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ud611\uc5c5\uc744 \uc704\ud55c VSCode \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8(Extension) \ucd94\ucc9c","permalink":"/blog/vscode-extensions"},"nextItem":{"title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","permalink":"/blog/nodejs-uninstall"}},"content":"MacOS \ub0b4 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ub354 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\nMacOS\ub97c \uc0ac\uc6a9\ud558\ub2e4\ubcf4\uba74 \ud654\uba74 \uc544\ub798\uc5d0 \uc228\uaca8\uc9c4 \ub3c5\uc744 \ubcf4\uae30 \uc704\ud574 \ub9c8\uc6b0\uc2a4\ub97c \ud654\uba74 \uc544\ub798\ub85c \uac00\uc838\ub2e4\ub300\uba74 \uc0dd\uac01\ubcf4\ub2e4 \ud55c\ucc38 \uc788\ub2e4\uac00 \uc2a4\ub974\ub975 \ud558\uace0 \uc5f4\ub9ac\ub294 \ub3c5\uc744 \ubcfc \uc218 \uc788\uc744\uac81\ub2c8\ub2e4. \uc774\ub97c \ub2f5\ub2f5\ud574\ud558\ub294 \ubd84\ub4e4\uc774 \uc788\uae30\uc5d0 \ub3c5\uc774 \uc5f4\ub9ac\ub294 \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ud560 \uc218 \uc788\ub294 \uba87 \uac00\uc9c0 \ud574\uacb0 \ubc29\ubc95\uc744 \uac00\uc9c0\uace0 \uc640 \ubd24\uc2b5\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-dock-speed-up.webp\\"\\n    alt=\\"mac-dock-speed-up\\"\\n  />\\n</figure>\\n\\n## \ubc29\ubc95 1. \ub2e8\ucd95\ud0a4\ub97c \uc774\uc6a9\ud574 \uc790\ub3d9 \uc228\uae40/\ubcf4\uc774\uae30 \uc124\uc815\\n\\n\ub2e8\ucd95\ud0a4 **options + command + D** \ub97c \uc785\ub825\ud558\uba74 \ud654\uba74 \uc544\ub798 \uac00\ub824\uc838 \uc788\ub358 \ub3c5\uc774 \uc62c\ub77c\uc624\uac8c \ub429\ub2c8\ub2e4. \ub610 \ubc18\ub300\ub85c \uc228\uae30\ub294 \uac83\ub3c4 \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n## \ubc29\ubc95 2. \ud130\ubbf8\ub110\uc744 \ud1b5\ud574 \ub3c5 \uc124\uc815\uac12 \ubcc0\uacbd\\n\\n1. \uc560\ub2c8\uba54\uc774\uc158 \uc5c6\uc774 \ubc14\ub85c \ub728\uac8c \ud558\ub294 \ubc29\ubc95\\n\\n```\\ndefaults write com.apple.dock autohide-time-modifier -int 0;killall Dock\\n```\\n\\n2. \uc560\ub2c8\uba54\uc774\uc158 \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95\\n\\n```\\ndefaults write com.apple.dock autohide-time-modifier -float 0.15;killall Dock\\n```\\n\\n3. \uc6d0\ub798 \uc0c1\ud0dc\ub85c \ubcf5\uad6c\ud558\ub294 \ubc29\ubc95\\n\\n```\\ndefaults delete com.apple.dock autohide-time-modifier;killall Dock\\n```"},{"id":"nodejs-uninstall","metadata":{"permalink":"/blog/nodejs-uninstall","source":"@site/blog/2022-11-21-nodejs-uninstall/index.md","title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","description":"Node.js \ubc84\uc804 \ubcc0\uacbd\uc774\ub098 \ucda9\ub3cc \ub4f1 \uc5ec\ub7ec \ubb38\uc81c\ub85c \uc778\ud574 Node.js\ub97c \uc9c0\uc6cc\uc57c \ud558\ub294 \uacbd\uc6b0, \uae54\ub054\ud788 \uc9c0\uc6b0\ub294 \ubc29\ubc95\uc744 \uc54c\ub824\ub4dc\ub9bd\ub2c8\ub2e4.","date":"2022-11-21T00:00:00.000Z","tags":[{"inline":true,"label":"NodeJS","permalink":"/blog/tags/node-js"},{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.63,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","slug":"nodejs-uninstall","authors":["kgenots"],"tags":["NodeJS","MacOS"],"image":"/assets/blog/nodejs-uninstall.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9e5 \ub3c5(Dock) \ub728\ub294 \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\ub294 \ubc29\ubc95","permalink":"/blog/mac-dock-speed-up"},"nextItem":{"title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","permalink":"/blog/mac-remove-window-shadow"}},"content":"Node.js \ubc84\uc804 \ubcc0\uacbd\uc774\ub098 \ucda9\ub3cc \ub4f1 \uc5ec\ub7ec \ubb38\uc81c\ub85c \uc778\ud574 Node.js\ub97c \uc9c0\uc6cc\uc57c \ud558\ub294 \uacbd\uc6b0, \uae54\ub054\ud788 \uc9c0\uc6b0\ub294 \ubc29\ubc95\uc744 \uc54c\ub824\ub4dc\ub9bd\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/nodejs-uninstall.webp\\"\\n    alt=\\"nodejs-uninstall\\"\\n  />\\n</figure>\\n\\n## 1. Node.js \uae54\ub054\ud558\uac8c \uc9c0\uc6b0\ub294 \ubc29\ubc95\\n\\n### [Node.js](https://nodejs.org/) \ud648\ud398\uc774\uc9c0\uc5d0\uc11c \ubc1b\uc558\uc744 \ub54c,\\n\\n```\\nsudo rm -rf /usr/local/lib/node\\nsudo rm -rf /usr/local/lib/node_modules\\nsudo rm /usr/local/lib/dtrace/node.d\\nsudo rm /usr/local/share/man/man1/node.1\\nsudo rm -rf /usr/local/share/doc/node\\nsudo rm -rf /usr/local/share/systemtap/tapset/node.stp\\nsudo rm -rf /usr/local/include/node\\nsudo rm /usr/local/bin/node\\nsudo rm /usr/local/bin/npm\\nsudo rm /usr/local/bin/npx\\n```\\n\\n### Homebrew \uc5d0\uc11c \ubc1b\uc558\uc744 \ub54c,\\n\\n```\\nbrew uninstall node\\nbrew doctor\\nbrew cleanup\\n```\\n\\n### \uc124\uce58\ub41c NPM \uce90\uc2dc, \ud658\uacbd\ud30c\uc77c\uae4c\uc9c0 \uc81c\uac70\ud558\ub824\uba74,\\n\\n```\\nsudo rm -rf /Users/$USER/.npm\\nsudo rm -rf ~/.npm\\n```\\n\\n## 2. Node.js \uc124\uce58 \ubc0f \uc81c\uac70 \uc5ec\ubd80 \ud655\uc778 \ubc29\ubc95\\n\\n```\\n// node \ubc84\uc804 \ud655\uc778\\nnode -v\\t\\t//\ubc84\uc804\ud45c\uae30(x.x.x)\uac00 \ub098\uc624\uba74 \uc124\uce58\ub41c \uc0c1\ud0dc\\n        \\t//command not found: node \uac00 \ub098\uc624\uba74 \uc81c\uac70\ub41c \uc0c1\ud0dc\\n\\n// npm \ubc84\uc804 \ud655\uc778\\nnpm -v\\t\\t//\ubc84\uc804\ud45c\uae30(x.x.x)\uac00 \ub098\uc624\uba74 \uc124\uce58\ub41c \uc0c1\ud0dc\\n        \\t//No such file or directory \uac00 \ub098\uc624\uba74 \uc81c\uac70\ub41c \uc0c1\ud0dc\\n```"},{"id":"mac-remove-window-shadow","metadata":{"permalink":"/blog/mac-remove-window-shadow","source":"@site/blog/2022-11-19-mac-remove-window-shadow/index.md","title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","description":"\ub9e5\uc5d0\uc11c \ucc3d \uc601\uc5ed\uc744 \ucea1\uccd0\ud560 \ub54c, \ucc3d \ud06c\uae30\ubcf4\ub2e4 \ub113\uc740 \uc601\uc5ed(\uadf8\ub9bc\uc790 \ud3ec\ud568)\uc758 \uacb0\uacfc\ubb3c\uc774 \ub098\uc624\ub294 \uacbd\uc6b0\uc758 \ub300\ucc98 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-11-19T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.91,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","slug":"mac-remove-window-shadow","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/mac-remove-window-shadow.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"Node.js, NPM \uc81c\uac70\ud558\ub294 \ubc29\ubc95 - MAC","permalink":"/blog/nodejs-uninstall"},"nextItem":{"title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","permalink":"/blog/mac-startup-program"}},"content":"\ub9e5\uc5d0\uc11c \ucc3d \uc601\uc5ed\uc744 \ucea1\uccd0\ud560 \ub54c, \ucc3d \ud06c\uae30\ubcf4\ub2e4 \ub113\uc740 \uc601\uc5ed(\uadf8\ub9bc\uc790 \ud3ec\ud568)\uc758 \uacb0\uacfc\ubb3c\uc774 \ub098\uc624\ub294 \uacbd\uc6b0\uc758 \ub300\ucc98 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-remove-window-shadow.webp\\"\\n    alt=\\"mac-remove-window-shadow\\"\\n  />\\n</figure>\\n\\nMacOS \ub0b4\uc5d0\uc11c \ucc3d \ucea1\uccd0\ub97c \ud558\uba74\uc11c \uc0dd\uacbc\ub358 \uadf8\ub9bc\uc790\uac00 \ud3ec\ud568\ub418\uc5b4 \ucc0d\ud788\ub294 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubcf4\ub3c4\ub85d \ud558\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n## \ub9e5\uc5d0\uc11c \ucc3d \ucea1\ucc98 \ubc29\ubc95\\n\\n\uc6b0\uc120, \ub9e5\uc5d0\uc11c \ucc3d \ucea1\ucc98(\uc2a4\ud06c\ub9b0\uc0f7)\ub97c \ud558\ub294 \ubc29\ubc95\uc740,\\n\\n**Shift + Command + 4** \ud0a4\ub97c \ub204\ub985\ub2c8\ub2e4. \uc774 \uc0c1\ud0dc\uc5d0\uc11c **Space bar** \ub97c \ub204\ub974\uba74 \ub9c8\uc6b0\uc2a4\uac00 \uce74\uba54\ub77c \ubaa8\uc591\uc73c\ub85c \ubc14\ub01d\ub2c8\ub2e4.\\n\\n\uc774 \uc0c1\ud0dc\uc5d0\uc11c \uc6d0\ud558\ub294 \ucc3d\uc5d0 \uc62c\ub824\ub450\uace0 **Enter**\xa0\ub97c \ub204\ub974\uba74 \ucc3d\uc774 \ucea1\ucc98\uac00 \ub429\ub2c8\ub2e4.\\n\\n## \uadf8\ub9bc\uc790 \uc720\ubb34 \ucc28\uc774 \ube44\uad50\\n\\n<table>\\n<thead>\\n    <tr>\\n      <th width=\\"50%\\">with shadow</th>\\n      <th width=\\"50%\\">without shadow</th>\\n    </tr>\\n  </thead>\\n<tbody>\\n <tr>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/mac-capture-with-shadow.webp\\"\\n          alt=\\"mac-capture-with-shadow\\"\\n          style={{border: \\"1px solid red\\"}}\\n        />\\n    </td>\\n    <td>\\n        <img\\n          src=\\"/assets/blog/mac-capture-without-shadow.webp\\"\\n          alt=\\"mac-capture-without-shadow\\"\\n          style={{border: \\"1px solid red\\"}}\\n        />\\n    </td>\\n </tr>\\n </tbody>\\n</table>\\n\\n\uc67c\ucabd \ucea1\ucc98\ubcf8\uc740 \ubcc4\ub3c4\uc758 \uc124\uc815\uc5c6\uc774 \ucc3d \ucea1\ucc98\ub97c \ud588\uc744 \ub54c\uc758 \uacb0\uacfc\ubb3c\uc785\ub2c8\ub2e4. \uc774 \uacbd\uc6b0, \ucc3d \ubc16\uc758 \uadf8\ub9bc\uc790 \ubd80\ubd84\uae4c\uc9c0 \ud3ec\ud568\ud558\uc5ec \ucea1\ucc98\uac00 \ub429\ub2c8\ub2e4. \ubc18\ub300\ub85c \uc624\ub978\ucabd \ucea1\ucc98\ubcf8\uc740 \uadf8\ub9bc\uc790 \uc81c\uac70 \uc124\uc815\uc744 \ud558\uc600\uae30\uc5d0, \ucc3d \ubc16\uc758 \uadf8\ub9bc\uc790\ub97c \uc81c\uc678\ud558\uace0 \ucc3d \ubd80\ubd84\ub9cc \uae54\ub054\ud558\uac8c \ucea1\ucc98\uac00 \ub41c \ubaa8\uc2b5\uc785\ub2c8\ub2e4.\\n\\n_\ucc3d \ucea1\ucc98 \uc2dc, \ubc30\uacbd\uc740 \ud22c\uba85 \ucc98\ub9ac\ub41c \uc0c1\ud0dc\uc785\ub2c8\ub2e4._\\n\\n## \ucc3d \ud06c\uae30\uac00 \ub2e4\ub978\uac70 \uc544\ub2cc\uac00\uc694?\\n\\n\uc704 \ud654\uba74\uc5d0\uc11c \uadf8\ub9bc\uc790\ub97c \ud3ec\ud568\ud55c \ucea1\ucc98 \uc774\ubbf8\uc9c0\uac00 \uc791\uc544\ubcf4\uc774\uc9c0\ub9cc, \uc2e4\uc81c\ub85c\ub294 \ucc3d\uc758 \ud06c\uae30\ub294 \uac19\uace0, \uc5ec\ubc31\uc744 \ud3ec\ud568\ud55c \uacb0\uacfc\ubb3c\uc774 \uc774\ubbf8\uc9c0\uc758 \ud06c\uae30\uac00 \ud07d\ub2c8\ub2e4.\\n\\n## \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95\\n\\n### \uadf8\ub9bc\uc790 \uc81c\uac70 \ud65c\uc131\ud654\\n\\n\'\ud130\ubbf8\ub110\' \uc571\uc744 \uc5f4\uace0 \uc544\ub798 \uba85\ub839\uc5b4\ub97c \uc21c\uc11c\ub300\ub85c \uc2e4\ud589\ud574\uc90d\ub2c8\ub2e4.\\n\\n\uc544\ub798 \uba85\ub839\uc5b4\ub97c \uc2e4\ud589\ud574\uba74 \uc544\ubb34 \uba54\uc138\uc9c0 \ub098\uc624\uc9c0 \uc54a\uc9c0\ub9cc \uc801\uc6a9\uc774 \ub41c \uc0c1\ud0dc\uc785\ub2c8\ub2e4.\\n\\n```\\ndefaults write com.apple.screencapture disable-shadow -bool true\\nkillall SystemUIServer\\n```\\n\\n### \uadf8\ub9bc\uc790 \uc81c\uac70 \ube44\ud65c\uc131\ud654 (\uc6d0\uc0c1\ubcf5\uad6c)\\n\\n\uc704\uc5d0\uc11c \uba85\ub839\uc5b4\ub97c \uc2e4\ud589\ud588\ub358 \uac83\ucc98\ub7fc \'\ud130\ubbf8\ub110\' \uc571\uc744 \uc5f4\uace0 \uc544\ub798 \uba85\ub839\uc5b4\ub97c \uc21c\uc11c\ub300\ub85c \uc2e4\ud589\ud574\uc90d\ub2c8\ub2e4.\\n\\n```\\ndefaults write com.apple.screencapture disable-shadow -bool false\\nkillall SystemUIServer\\n```"},{"id":"mac-startup-program","metadata":{"permalink":"/blog/mac-startup-program","source":"@site/blog/2022-11-19-mac-startup-program/index.md","title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","description":"Mac \ubd80\ud305 \ub610\ub294 \ub85c\uadf8\uc778 \uc2dc \uc790\ub3d9\uc73c\ub85c \uc2e4\ud589\ub418\ub294 \uc2dc\uc791\ud504\ub85c\uadf8\ub7a8\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-11-19T00:00:00.000Z","tags":[{"inline":true,"label":"MacOS","permalink":"/blog/tags/mac-os"}],"readingTime":0.67,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","slug":"mac-startup-program","authors":["kgenots"],"tags":["MacOS"],"image":"/assets/blog/mac-startup-program.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9e5 \ud654\uba74\ucea1\ucc98 \uc2dc, \ucc3d \uadf8\ub9bc\uc790 \uc81c\uac70 \ubc29\ubc95","permalink":"/blog/mac-remove-window-shadow"},"nextItem":{"title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","permalink":"/blog/npm-remove-unused-packages"}},"content":"Mac \ubd80\ud305 \ub610\ub294 \ub85c\uadf8\uc778 \uc2dc \uc790\ub3d9\uc73c\ub85c \uc2e4\ud589\ub418\ub294 \uc2dc\uc791\ud504\ub85c\uadf8\ub7a8\uc744 \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-startup-program.webp\\"\\n    alt=\\"mac-startup-program\\"\\n  />\\n</figure>\\n\\nMacOS \ubd80\ud305 \uc2dc, \uc0ac\uc6a9\uc790\uc758 \uae30\ud638\uc5d0 \ub530\ub77c \uc790\ub3d9 \uc2e4\ud589\uc774 \ud544\uc694\ud55c \uc571\ub4e4\uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n_AlDente(\ubc30\ud130\ub9ac \uad00\ub9ac \ud504\ub85c\uadf8\ub7a8),_\\n\\n_Rectangle(\ud654\uba74 \ubd84\ud560 \ub2e8\ucd95\ud0a4 \uc124\uc815),_\\n\\n_Karabiner(\ud0a4\ubcf4\ub4dc \uc124\uc815),_\\n\\n_\uce74\uce74\uc624\ud1a1(?)_\\n\\n\uc704\uc640 \uac19\uc740 \uc798 \ub9cc\ub4e4\uc5b4\uc9c4 \uc571\ub4e4\uc740 \uc571 \ub0b4\ubd80 \uc124\uc815\uc73c\ub85c \ub300\ubd80\ubd84 \uc790\ub3d9\uc73c\ub85c \ub4f1\ub85d\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4.\\n\\n\ud558\uc9c0\ub9cc \uadf8\ub807\uc9c0 \uc54a\uc740 \uc571\ub4e4\ub3c4 \uc885\uc885 \uc788\ub294\ub370\uc694.\\n\\n\ub300\ud45c\uc801\uc73c\ub85c \uc81c\uac00 \uc0ac\uc6a9\uc911\uc778 _TermHere(\ud30c\uc778\ub354 \ud604\uc7ac \uacbd\ub85c\uc5d0\uc11c \ud130\ubbf8\ub110 \uc5f4\uae30)_ \uc774 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc774\ub7f0 \uacbd\uc6b0, \ub85c\uadf8\uc778 \ud56d\ubaa9\uc744 \uc9c1\uc811 \uad00\ub9ac\ud574 \uc904 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n## \ub85c\uadf8\uc778 \ud56d\ubaa9 \uc124\uc815\ud558\ub294 \ubc29\ubc95\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-spotlight.webp\\"\\n    alt=\\"mac-spotlight\\"\\n  />\\n</figure>\\n\\n**Command + Space bar** \ub610\ub294 **\uc6b0\uc0c1\ub2e8 \uac80\uc0c9 \uc544\uc774\ucf58**\uc744 \ub20c\ub974\uace0,\\n\\nSpotlight \uac80\uc0c9\uc744 \uc5f4\uc5b4 \'**\uc2dc\uc2a4\ud15c \uc124\uc815**\'\uc744 \uc785\ub825\ud558\uace0 \ub4e4\uc5b4\uac00\uc90d\ub2c8\ub2e4.\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-system-config.webp\\"\\n    alt=\\"mac-system-config\\"\\n  />\\n</figure>\\n\\n\uc704\uc640 \uac19\uc774 \uc2dc\uc2a4\ud15c \uc124\uc815 \ucc3d\uc774 \ub72c \ud6c4,\\n\\n\uc67c\ucabd \uc0c1\ub2e8 \uac80\uc0c9\uc5d0\uc11c \'**\ub85c\uadf8\uc778 \ud56d\ubaa9**\' \uc744 \uc785\ub825\ud574\uc90d\ub2c8\ub2e4.\\n\\n_\\\\- Spotlight \uac80\uc0c9\uc5d0\uc11c \'\ub85c\uadf8\uc778 \ud56d\ubaa9\' \uac80\uc0c9\ud574\ub3c4 \ubc14\ub85c \ub4e4\uc5b4\uac00\uc9c0\ub124\uc694._\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/mac-login-program.webp\\"\\n    alt=\\"mac-login-program\\"\\n  />\\n</figure>\\n\\n\ub85c\uadf8\uc778 \uc2dc \uc5f4\uae30 \ud56d\ubaa9\uc5d0\uc11c + \ub610\ub294 - \ubc84\ud2bc\uc744 \ud1b5\ud574 \uc751\uc6a9 \ud504\ub85c\uadf8\ub7a8\uc744 \ucd94\uac00 \ub610\ub294 \uc81c\uac70\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n_\uc774 \ud3ec\uc2a4\ud2b8\ub294 MacOS Ventura(\ubca4\ud22c\ub77c) 13.0.1 \ubc84\uc804\uc5d0\uc11c \uc791\uc131\ub418\uc5c8\uc2b5\ub2c8\ub2e4._"},{"id":"npm-remove-unused-packages","metadata":{"permalink":"/blog/npm-remove-unused-packages","source":"@site/blog/2022-09-08-npm-remove-unused-packages/index.md","title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","description":"\ud504\ub85c\uc81d\ud2b8 \ub0b4\ubd80\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 npm module\uc744 package.json\uc5d0\uc11c \ud655\uc778 \ubc0f \uc81c\uac70\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-09-08T00:00:00.000Z","tags":[{"inline":true,"label":"NPM","permalink":"/blog/tags/npm"}],"readingTime":0.67,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","slug":"npm-remove-unused-packages","authors":["kgenots"],"tags":["NPM"],"image":"/assets/blog/npm-remove-unused-packages.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"\ub9e5 \uc790\ub3d9\uc2e4\ud589 \ud56d\ubaa9 \uc124\uc815 \ubc29\ubc95","permalink":"/blog/mac-startup-program"},"nextItem":{"title":"npm package.json \uc21c\uc11c \uc815\ub82c\ud558\ub294 \ubc29\ubc95 (sort-package-json)","permalink":"/blog/npm-sort-package-json"}},"content":"\ud504\ub85c\uc81d\ud2b8 \ub0b4\ubd80\uc5d0\uc11c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 npm module\uc744 package.json\uc5d0\uc11c \ud655\uc778 \ubc0f \uc81c\uac70\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign: \'center\' }}>\\n  <img\\n    src=\\"/assets/blog/npm-remove-unused-packages.webp\\"\\n    alt=\\"npm-remove-unused-packages\\"\\n  />\\n</figure>\\n\\n\ud504\ub85c\uc81d\ud2b8\ub97c \uc7a5\uae30\uac04 \uc9c4\ud589\ud558\ub2e4\ubcf4\uba74, node module \uc744 \uc124\uce58\ud558\uace0 \uc9c0\uc6b0\uace0\ub97c \ubc18\ubcf5\ud558\ub294 \uacbd\uc6b0\uac00 \uc0dd\uae41\ub2c8\ub2e4.\\n\\nrequire \ub098 import \ub97c \ud1b5\ud574 node module \uc0ac\uc6a9 \ubd80\ubd84\uc740 \uc9c0\uc6b0\uae30 \ud3b8\ud558\uc9c0\ub9cc, \uc124\uce58 \ub2f9\uc2dc\uc5d0 \ucd94\uac00\ub41c package.json \ub0b4\ubd80\uc758 dependencies\uc640 devDependencies \uc5d0\uc11c\ub294 \uc9c0\uc6b0\uc9c0 \ubabb\ud574 \ub0a8\ub294 \uacbd\uc6b0\uac00 \uc885\uc885 \uc0dd\uae30\uace4 \ud569\ub2c8\ub2e4.\\n\\ndepcheck\ub97c \uc774\uc6a9\ud558\uba74 \ubbf8\uc0ac\uc6a9\uc0c1\ud0dc\ub85c dependencies\uc640 devDependencies\uc5d0 \uc801\ud600\uc788\ub294 node module\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n**\uc8fc\uc758\uc0ac\ud56d\uc73c\ub85c lint, prettier \ub4f1 runtime \ucf54\ub4dc\uc5d0\uc11c \ud638\ucd9c\ub418\uc9c0 \uc54a\uace0 \uac1c\ubc1c\uc744 \uc704\ud574\uc11c\ub9cc \uc0ac\uc6a9\ub418\ub294 module\ub3c4 \uc0ac\uc6a9\ub418\uc9c0 \uc54a\ub294 \ubaa8\ub4c8\uc5d0 \ud3ec\ud568\ub420 \uc218 \uc788\uc73c\ub2c8 \uc219\ub828\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \ubaa8\ub974\ub294 \ubaa8\ub4c8 \uc81c\uac70\ub294 \uc0bc\uac00\ud558\ub294 \uac83\uc744 \ucd94\ucc9c\ud569\ub2c8\ub2e4.**\\n\\n## \uc0ac\uc6a9\ubc29\ubc95\\n\\n```\\nnpx depcheck\\n```\\n\\n## \ucc38\uace0\\n\\nhttps://github.com/depcheck/depcheck\\n\\n<div class=\\"link-preview-container\\">\\n  <a href=\\"https://github.com/depcheck/depcheck\\"></a>\\n\\n  <div class=\\"link-preview-top\\">\\n    <div class=\\"link-preview-image\\">\\n      <img\\n        src=\\"https://opengraph.githubassets.com/c2050797da1d240a5d0f73c6995e3f7ca7044ccb6585a61df8c72f8d1065c9c0/depcheck/depcheck\\"\\n        alt=\\"Article Thumbnail\\"\\n      />\\n    </div>\\n\\n    <div class=\\"link-preview-content\\">\\n      <div class=\\"link-preview-title\\">\\n        GitHub - depcheck/depcheck: Check your npm module for unused\\n        dependencies\\n      </div>\\n      <div class=\\"link-preview-description\\">\\n        Check your npm module for unused dependencies. Contribute to\\n        depcheck/depcheck development by creating an account on GitHub.\\n      </div>\\n    </div>\\n\\n  </div>\\n</div>"},{"id":"npm-sort-package-json","metadata":{"permalink":"/blog/npm-sort-package-json","source":"@site/blog/2022-09-08-npm-sort-package-json/index.md","title":"npm package.json \uc21c\uc11c \uc815\ub82c\ud558\ub294 \ubc29\ubc95 (sort-package-json)","description":"npm install \ud560 \ub54c, \uc124\uce58\ud55c \uc21c\uc11c\ub300\ub85c \uc791\uc131\ub418\ub294 package.json\uc744 \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub85c \uc815\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.","date":"2022-09-08T00:00:00.000Z","tags":[{"inline":true,"label":"NPM","permalink":"/blog/tags/npm"}],"readingTime":0.65,"hasTruncateMarker":true,"authors":[{"name":"KGENOTS","title":"KGENOTS","url":"https://github.com/kgenots","imageURL":"https://github.com/kgenots.png","key":"kgenots","page":null}],"frontMatter":{"title":"npm package.json \uc21c\uc11c \uc815\ub82c\ud558\ub294 \ubc29\ubc95 (sort-package-json)","slug":"npm-sort-package-json","authors":["kgenots"],"tags":["NPM"],"image":"/assets/blog/npm-sort-package-json.webp","hide_table_of_contents":false},"unlisted":false,"prevItem":{"title":"npm \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \ubaa8\ub4c8 \uc81c\uac70\ud558\ub294 \ubc29\ubc95 (depcheck)","permalink":"/blog/npm-remove-unused-packages"}},"content":"npm install \ud560 \ub54c, \uc124\uce58\ud55c \uc21c\uc11c\ub300\ub85c \uc791\uc131\ub418\ub294 package.json\uc744 \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub85c \uc815\ub9ac\ud558\ub294 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n\x3c!--truncate--\x3e\\n\\n<figure style={{ textAlign:\'center\' }}>\\n  <img \\n    src=\\"/assets/blog/npm-sort-package-json.webp\\"\\n    alt=\\"npm-sort-package-json\\"\\n  />\\n</figure>\\n\\npackage.json \uc758 dependencies \ub098 devDependencies \uac00 \uc54c\ud30c\ubcb3 \uc21c\uc11c\ub300\ub85c \uc815\ub9ac\ud558\uace0 \uc2f6\uc744 \ub54c, package.json\uc758 \ud0a4 \uc21c\uc11c\uac00 \uc11e\uc5ec\uc788\uc5b4\uc11c license \ub4f1 \ud2b9\uc815 \ud0a4\ub97c \ucc3e\uae30 \uc5b4\ub824\uc6cc \ud560 \ub54c \ud130\ubbf8\ub110\uc5d0\uc11c **npx sort-package-json**\ub9cc \uc785\ub825\ud574\uc8fc\uba74 \ud574\ub2f9 \ub514\ub809\ud1a0\ub9ac \ub0b4 package.json \ub0b4\uc6a9\uc774 \uc815\ub9ac\uac00 \ub429\ub2c8\ub2e4.\\n\\n## \uc0ac\uc6a9\ubc29\ubc95\\n\\n```\\nnpx sort-package-json\\n```\\n\\npackage.json \ud30c\uc77c\uc774 \uc874\uc7ac\ud558\ub294 \ud3f4\ub354\uc5d0\uc11c \ud130\ubbf8\ub110\uc744 \uc5f4\uace0 \uc704 \uba85\ub839\uc5b4\ub97c \uc2e4\ud589\ud569\ub2c8\ub2e4.\\n\\n## \ucc38\uace0\\n\\nhttps://github.com/keithamus/sort-package-json\\n\\n<div class=\\"link-preview-container\\">\\n    <a href=\\"https://github.com/keithamus/sort-package-json\\"></a>\\n    \\n    <div class=\\"link-preview-top\\">\\n        <div class=\\"link-preview-image\\">\\n            <img src=\\"https://opengraph.githubassets.com/9baae571fe9d426d5a6ba3cc1cef97baa5b8f9497fce5a54886a46088e04548f/keithamus/sort-package-json\\" alt=\\"Article Thumbnail\\" />\\n        </div>\\n        \\n        <div class=\\"link-preview-content\\">\\n            <div class=\\"link-preview-title\\">GitHub - keithamus/sort-package-json: Sort an Object or package.json based on the well-known package.json keys</div>\\n            <div class=\\"link-preview-description\\">Sort an Object or package.json based on the well-known package.json keys - GitHub - keithamus/sort-package-json: Sort an Object or package.json based on the well-known package.json keys</div>\\n        </div>\\n    </div>\\n</div>"}]}}')}}]);